S=struct('status','RUNNING','lastTime',NaN,'firstThrustMismatch',NaN,...
 'firstTorqueOverLimit',NaN,'firstRefError05',NaN,'firstBetaWarning',NaN,...
 'firstAlphaGrowth',NaN,'maxRawTorque',0,'maxPositionError',0,...
 'minBetaRcond',Inf,'maxAlphaNorm',0,'maxThrustMismatch',0,...
 'nSteps',0,'failure','');
