elseif strcmp(p,'full')
 C={'A01','ORIGINAL','NOMINAL';...
    'A02','ORIGINAL','R1_EXACT';...
    'A03','ORIGINAL','POST_V1_T';...
    'A04','ORIGINAL','V1_VALUE';...
    'A05','ORIGINAL','V1_D1';...
    'A06','ORIGINAL','V1_D2';...
    'A07','ORIGINAL','V1_D3';...
    'A08','ORIGINAL','V1_JET';...
    'A09','ORIGINAL','TORQUE_ROLL_POST';...
    'A10','ORIGINAL','TORQUE_ROLL_VIRTUAL';...
    'A11','ORIGINAL','TORQUE_PITCH_POST';...
    'A12','ORIGINAL','TORQUE_PITCH_VIRTUAL';...
