function y=v32FlightLoadJet(f,t,L)
raw=double(f(max(0,t)));raw=raw(:);
assert(numel(raw)==28 && all(isfinite(raw)), ...
 'CBF:HLCV32SourceGeneratorShape',...
 'R193 exact 6th-order source jet must have 28 entries, got %d',numel(raw));
raw(3)=raw(3)-L;y=raw;
end

function xyz=v32XYZJet(fullFcn,t,k)
assert(k>=0 && k<=6 && floor(k)==k,'CBF:HLCV32JetOrder','0..6 only');
y=double(fullFcn(t)); xyz=y(4*k+(1:3));xyz=xyz(:);
end

function z=v32LaneFullJet(base,t,amp,startTime,rise,holdTime)
z=base(t);amp=amp(:);
for k=0:6
  smooth=v32S7(t-startTime,rise,k)-...
       v32S7(t-(startTime+rise+holdTime),rise,k);
  z(4*k+(1:3))=z(4*k+(1:3))+amp*smooth;
end
end

function y=v32S7(t,D,k)
% V34 NUMERICALLY STABLE exact d^k/dt^k of degree-15 S7(t/D).
% S7(s) = regularized incomplete beta I_s(8,8), 0<s<1.
% k=0: positive Bernstein sum (no cancellation near s=1).
% k=1..7: derivative of S7'(s)=51480*s^7*(1-s)^7 using
% Leibniz's rule. This avoids catastrophic cancellation of power-basis
% terms of order 1e7 near s=1 (V33 endpoint audit failure).
assert(isfinite(t) && isfinite(D) && D>0 && ...
    isscalar(k) && k>=0 && k<=7 && floor(k)==k,...
    'CBF:HLCV34S7','Invalid S7 arguments');
s=t/D;
% Floating-point endpoint arithmetic can give s=1-1e-15 when the
% intended knot is exactly 1. Snap ONLY within roundoff tolerance.
if s<=64*eps(1),y=0;return;end
if s>=1-64*eps(1),y=double(k==0);return;end
if k==0
    y=0;
    for j=8:15
        y=y+nchoosek(15,j)*s^j*(1-s)^(15-j);
    end
    return;
end
m=k-1;y=0;
for j=0:m
    a=nchoosek(m,j)*factorial(7)/factorial(7-j)*...
      factorial(7)/factorial(7-m+j);
    y=y+(-1)^(m-j)*a*s^(7-j)*(1-s)^(7-m+j);
end
y=51480*y/D^k;
end

function dv=v32V1Wave(t,opts)
dv=zeros(1,5);start=opts.continuousV1Start;
for k=0:4
 dv(k+1)=opts.continuousV1Amplitude*(...
     v32S7(t-start,opts.continuousV1Rise,k)-...
     v32S7(t-(start+opts.continuousV1Rise+opts.continuousV1Hold),...
             opts.continuousV1Fall,k));
end
end

function pass=v32ReferenceAudit(sc,base,opts,work)
% Source-derived R193 normal Flight reference; NO fabricated/replanned
% trajectory. Check all seven 0..6 derivative orders against independent
% closed form of the known constant-speed gen_ref_line call, not against
% the same function handle twice.
J=cell(0,5);T=unique([0,.1,.6,.9,1.5,2.5,4.0,opts.continuousDuration]);
for it=1:numel(T)
    t=T(it);y=base(t);
    assert(numel(y)==28 && all(isfinite(y)),...
       'CBF:HLCV34SourceNonfinite','Original 6-jet invalid');
    for k=0:6
      measured=y(4*k+(1:4));
      expected=zeros(4,1);
      if k==0
          expected=[0;1.5*t;3-sc.settings.physical.cableLength;pi/2];
      elseif k==1
          expected=[0;1.5;0;0];
      end
      err=norm(measured-expected,Inf);
      J(end+1,:)={'ORIGINAL',t,k,err,'R193_GEN_REF_LINE_INDEPENDENT_LINEAR_JET'}; %#ok<AGROW>
    end
end
% C7 reference checks are not involved in the original nominal Flight.
% They are available only with explicit diagnostic opt-in.
if opts.continuousSyntheticReference
 for D=[opts.continuousFastRamp,opts.continuousSlowRamp]
  for tk=[opts.continuousLaneStart,opts.continuousLaneStart+D,...
         opts.continuousLaneStart+D+opts.continuousLaneHold,...
         opts.continuousLaneStart+2*D+opts.continuousLaneHold]
   for k=0:7
    val=v32S7(tk-opts.continuousLaneStart,D,k)-...
       v32S7(tk-(opts.continuousLaneStart+D+opts.continuousLaneHold),D,k);
    expected=0;
    if k==0
      expected=double(tk>=opts.continuousLaneStart+D &&...
         tk<=opts.continuousLaneStart+D+opts.continuousLaneHold);
    end
    err=abs(val-expected);
    J(end+1,:)={sprintf('OPTIONAL_C7_D_%.3g',D),tk,k,err,...
                 'EXPERIMENTAL_NOT_ORIGINAL_REFERENCE'}; %#ok<AGROW>
   end
  end
 end
end
names={'source','time_s','derivativeOrder','absoluteError','auditType'};
writetable(cell2table(J,'VariableNames',names),...
    fullfile(work,'V34_ORIGINAL_REFERENCE_0_TO_6_AUDIT.csv'));
pass=all(cell2mat(J(:,4))<1e-7);
assert(pass,'CBF:HLCV34OriginalJetAudit',...
 'Original R193 gen_ref_line analytic 0..6 jet mismatched expected constant-speed flight source');
% Record exact source provenance + initial HLC commands for reproducibility.
a=v23HLC(sc.x0,0,sc,v23MakeHLC(sc.settings,opts.dt),v23EstimatedMass(opts,0));
lines={['source_gen_ref_line = ' char(which('gen_ref_line'))];...
 ['source_gen_ref_for_rigid_body = ' char(which('gen_ref_for_rigid_body'))];...
 'nominal p0=[0 0 3] m; speed=1.5 m/s; direction=[0 1 0]';...
 'R193 source returns struct.pYaw(t); exact 0..6 normal Flight line jet is used';...
 sprintf('payload_Z_shift_only_position_order0 = -%.10g m',sc.settings.physical.cableLength);...
 sprintf('x0_payload = [%g %g %g] m',sc.x0(8:10));...
 sprintf('x0_payload_velocity = [%g %g %g] m/s',sc.x0(11:13));...
 sprintf('initial_HLC_raw_T=%g N, raw_tau_inf=%g Nm',a.thrust,a.rawTorqueInf);...
 'R193 source Flight real takeoff phase and true EKF state NOT reproduced unless user supplies a tick-matched state.'};
v23WriteText(fullfile(work,'V32_ORIGINAL_SOURCE_PROVENANCE.txt'),strjoin(lines,newline));
end

function [T,S]=v32RunContinuousOne(sc,mode,opts)
H=v23MakeHLC(sc.settings,opts.dt);x=sc.x0(:);
s=sc.settings;lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
K=round(opts.continuousDuration/opts.dt);
assert(abs(K*opts.dt-opts.continuousDuration)<1e-8, ...
 'CBF:HLCV32TimeGrid','continuousDuration must be divisible by dt');
columns={'time_s','mode','estimatedMass_kg','trueMass_kg',...
 'refX_m','refY_m','refZ_m','loadX_m','loadY_m','loadZ_m',...
 'posError_m','velError_mps','HLC_rawT_N','HLC_rawTauInf_Nm',...
 'desiredT_N','desiredTauInf_Nm','appliedT_N','appliedTauInf_Nm',...
 'desiredTauX_Nm','desiredTauY_Nm','desiredTauZ_Nm',...
 'appliedTauX_Nm','appliedTauY_Nm','appliedTauZ_Nm',...
 'rawToAppliedClipInf','desiredToAppliedClipInf','V1Wave',...
 'V1WaveD1','V1WaveD2','V1WaveD3','V1WaveD4',...
 'desiredVirtualMapResidual','physicalVirtualMapResidual',...
 'VsNorm','alpha2Norm','betaRcond','HLCdenominator',...
 'referenceJetMaxNorm','minCableH','appliedTension_N',...
 'truePlantQz','cableOmegaNorm','rawThrustOverflow_N',...
 'rawTorqueOverflow_Nm','demandedVirtualTorqueInf',...
 'r1StoppedHere','virtualVsOffsetInf','virtualTauReconstructionErrorNm',...
 'minSubstepCableH','minSubstepTensionN','physicalInputToVirtualMapResidual',...
 'torquePerturbationNm',...
 'virtualTargetT_N','virtualTargetTauInf_Nm',...
 'beforeClipTargetThrustMismatch_N','beforeClipTargetTorqueMismatch_Nm',...
 'afterClipTargetThrustMismatch_N','afterClipTargetTorqueMismatch_Nm',...
 'alteredBetaRcond','incrementalVsCommandInf',... 
 'nativeV1_D0','nativeV1_D1','nativeV1_D2','nativeV1_D3','nativeV1_D4',...
 'targetV1_D0','targetV1_D1','targetV1_D2','targetV1_D3','targetV1_D4',...
 'nativeV2','nativeV3','nativeV4',...
 'v1CoupledV2','v1CoupledV3','v1CoupledV4',...
 'independentDeltaV2','independentDeltaV3','independentDeltaV4',...
 'targetV2','targetV3','targetV4','nativeV1_D5','targetV1_D5'};
rows=cell(K+1,numel(columns));last=0;
tStart=0;
if isfield(opts,'v40StartTime'),tStart=opts.v40StartTime;end
S=struct('status','COMPLETED_DIAGNOSTIC_NOT_SAFETY_CERTIFIED',...
 'detail','Integrated full duration','tEnd',NaN,'maxRawTau',0,...
 'maxRawT',0,'maxPosErr',0,'maxVs',0,'minH',Inf,...
 'minTension',Inf,'nHnegative',0,'nClip',0,'maxMapResidual',0,...
 'maxJetDemand',0,'firstClip',NaN,'firstHnegative',NaN,...
 'maxAppliedMismatch',0);
for k=0:K
 t=tStart+k*opts.dt;mhat=v23EstimatedMass(opts,t);
 a=v23HLC(x,t,sc,H,mhat);
 if ~all(isfinite([a.raw;a.vsNorm;a.alphaNorm])) || a.betaRcond<1e-14
  S.status='STOP_HLC_INVERSION_OR_NONFINITE';S.detail=sprintf('t=%g',t);break;
 end
 baseline=max(lo,min(hi,a.raw));desired=baseline;
 dv=v32V1Wave(t,opts);plannedMap=NaN(4,1);
 mapResidual=0;physResidual=0;virtualVs=0;virtualTauErr=0;
 subH=NaN;subTension=NaN;
 % V38: separate the coupling caused by changing v1 from an intentional
 % *additional* v2-v4 command. Only these measured channels are described
 % as algebraically consistent with the original generated HLC at this tick.
 nativeVf=a.vfRaw(:).';targetVf=nativeVf;
 vsCoupled=a.vsRaw(:);vsChange=zeros(3,1);vsTarget=vsCoupled;
 fullBeta=[];fullAlpha=[];
 dTau=v33TorqueWave(t,opts,mode);
 switch upper(mode)
  case 'NOMINAL'
  case 'R1_EXACT'
   [desired,status]=v25R1ExactFilter(x,s,sc.obstacles,baseline);
   if ~strcmp(status,'OK')
       desired=baseline; % no candidate is applied after an infeasible R1 stop
       S.status=['R1_FILTER_STOP_' status];S.detail=sprintf('t=%.5g; %s',t,status);
   end
  case 'V41_R1_MATCH_T_V1_ZERO'
   % Same ACTUAL R1 CBF thrust (and same full physical state at each tick)
   % but recompute Vs, Beta2, alpha2 and torque after changing v1(0).
   % This is pointwise inverse consistency ONLY. The other five Vfd
   % columns are not derivatives of the changed, potentially nonsmooth
   % R1 thrust time series; do not label as full-jet-consistent or safe.
   [r1u,r1status]=v25R1ExactFilter(x,s,sc.obstacles,baseline);
   if ~strcmp(r1status,'OK')
      desired=baseline;
      S.status=['R1_FILTER_STOP_' r1status];
      S.detail=sprintf('t=%.5g; %s',t,r1status);
   else
      targetVf=a.vfRaw(:).';
      % Differentiate the ORIGINAL generated thrust map w.r.t. v1_0
      % using its exactly affine structure at fixed physical state.
      vProbe=targetVf;vProbe(1)=vProbe(1)+1;
      tProbe=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vProbe,a.HLCparam);
      thrustGain=tProbe(1)-a.raw(1);
      if ~isfinite(thrustGain) || abs(thrustGain)<1e-12
          error('CBF:HLCV41ThrustMapDegenerate',...
               'Cannot invert HLC Uf map at t=%.8g',t);
      end
      targetVf(1)=targetVf(1)+(r1u(1)-a.raw(1))/thrustGain;
      try
         [newU,newVs,newAlpha,newBeta]=v30VirtualMap(H,x,a,targetVf);
      catch MEvirtual
         % A CBF-feasible thrust need NOT have a regular HLC inverse.
         % This is a meaningful feasibility stop, not a simulated crash.
         S.status='STOP_R1_MATCHED_VIRTUAL_INVERSE_UNREALIZABLE';
         S.detail=sprintf('t=%.8g, source=%s, detail=%s',...
                    t,MEvirtual.identifier,MEvirtual.message);
         S.tEnd=t;
         break; % Exit time loop; never silently apply another input.
      end
      if abs(newU(1)-r1u(1))>1e-7*max(1,abs(r1u(1)))
          error('CBF:HLCV41ThrustMismatch',...
                'R1 and mapped thrust disagree at t=%.8g',t);
      end
      desired=newU; plannedMap=newU;
      vsCoupled=newVs(:); vsTarget=vsCoupled;
      fullAlpha=newAlpha(:); fullBeta=newBeta;
      mapResidual=norm(fullBeta*desired(2:4)-fullAlpha(:));
   end
  case {'POST_V1_T','V1_VALUE','V1_D1','V1_D2','V1_D3','V1_JET'}
   vf0=a.vfRaw(:).'; vf4=vf0;vf4(1:5)=vf4(1:5)+dv;
   [fullU,fullVs,fullAlpha,fullBeta]=v30VirtualMap(H,x,a,vf4);
   plannedMap=fullU;targetVf=vf4;vsCoupled=fullVs(:);vsTarget=vsCoupled;
   switch upper(mode)
    case 'POST_V1_T',desired=[fullU(1);baseline(2:4)];
    case 'V1_VALUE',ord=0;
    case 'V1_D1',ord=1;
    case 'V1_D2',ord=2;
    case 'V1_D3',ord=3;
    case 'V1_JET',ord=4;
   end
   if ~strcmpi(mode,'POST_V1_T')
       vfPart=vf0;vfPart(1:ord+1)=vfPart(1:ord+1)+dv(1:ord+1);
       [desired,partialVs,~,~]=v30VirtualMap(H,x,a,vfPart);
       targetVf=vfPart;vsCoupled=partialVs(:);vsTarget=vsCoupled;
   end
   mapResidual=norm(fullBeta*desired(2:4)-fullAlpha(:));
  case {'TORQUE_ROLL_POST','TORQUE_PITCH_POST','TORQUE_PITCH_NEG_POST','TORQUE_YAW_POST',...
        'TORQUE_ROLL_VIRTUAL','TORQUE_PITCH_VIRTUAL','TORQUE_PITCH_NEG_VIRTUAL','TORQUE_YAW_VIRTUAL'}
    targetTau=baseline(2:4)+dTau;
    if endsWith(upper(mode),'_POST')
        desired=[baseline(1);targetTau];
    else
        [tau,virtualVs,virtualTauErr]=v33VirtualTorqueTarget(H,x,a,...
             a.vfRaw(:).',a.vsRaw(:),a.alpha(:),a.beta,targetTau);
        desired=[baseline(1);tau];
    end
  case {'VIRTUAL_VS_1','VIRTUAL_VS_2','VIRTUAL_VS_3'}
    idx=str2double(mode(end));
    vsShift=zeros(3,1);vsShift(idx)=opts.continuousVsAmplitude*...
         v33TorqueEnvelope(t,opts);
    alphaNew=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,a.vfRaw,...
            a.vsRaw(:)+vsShift,a.HLCparam);
    desired=[baseline(1);a.beta\alphaNew(:)];
    virtualVs=norm(vsShift,Inf);
  case {'V37_POST_T','V37_NATIVE_V1','V37_NATIVE_ALL',...
        'V37_POST_SAME_ALL','V37_POST_INDEPENDENT','V37_POST_TAU',...
        'V37_NATIVE_VS','V37_NATIVE_VS_X','V37_NATIVE_VS_Y',...
        'V37_NATIVE_VS_YAW',...
        'V37_POST_T_LOW','V37_NATIVE_ALL_LOW','V37_POST_INDEPENDENT_LOW',...
        'V37_POST_T_HIGH','V37_NATIVE_ALL_HIGH','V37_POST_INDEPENDENT_HIGH',...
        'V37_POST_T_SLOW','V37_NATIVE_ALL_SLOW','V37_POST_INDEPENDENT_SLOW',...
        'V37_NATIVE_ALL_HIGH_SLOW'}
    % V37: independently recompute the HLC inverse from the altered
    % virtual 4-channel command, including the 0..4 v1 correction jet.
    % The underlying reference stays exactly the original Flight 6-jet.
    vsChange=v37VirtualVsWave(t,opts,mode);
    if contains(upper(mode),'POST_TAU') || contains(upper(mode),'POST_INDEPENDENT')
       % Unlike the native Vs offset, this is an INDEPENDENT real pitch
       % torque correction, held over each 25-ms integration interval.
       dTau=[0;opts.continuousTorqueAmplitudeNm*...
                 v33TorqueEnvelope(t,opts);0];
    end
    isVsOnly=contains(upper(mode),'NATIVE_VS') || contains(upper(mode),'POST_TAU');
    vfTarget=a.vfRaw(:).';
    if ~isVsOnly
       % Vfd in the original generated HLC has SIX columns (orders 0..5).
       % The fifth derivative is required for a consistent total v1 jet,
       % even when torque only explicitly uses d0..4 at a given state.
       vfTarget(1:6)=vfTarget(1:6)+v38FullV1Wave(t,opts);
    end
    [uBase,vsRecalc,~,betaChanged]=v30VirtualMap(H,x,a,vfTarget);
    targetVf=vfTarget;vsCoupled=vsRecalc(:);vsTarget=vsCoupled+vsChange;
    targetAlpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vfTarget,...
        vsRecalc(:)+vsChange,a.HLCparam);
    fullAlpha=targetAlpha(:);fullBeta=betaChanged;
    plannedMap=[uBase(1);betaChanged\fullAlpha];
    virtualVs=norm(vsChange,Inf);
    if contains(upper(mode),'POST_TAU')
        desired=[baseline(1);baseline(2:4)+dTau];
    elseif contains(upper(mode),'POST_INDEPENDENT')
        desired=[plannedMap(1);baseline(2:4)+dTau];
    elseif contains(upper(mode),'POST_T')
        desired=[plannedMap(1);baseline(2:4)];
    elseif contains(upper(mode),'NATIVE_V1')
        % Derivative coherent delta-v1, but no additive delta-Vs.
        desired=uBase;
        fullAlpha=betaChanged*uBase(2:4);
        plannedMap=uBase;
    else
        % Native {v1(0..4), v2, v3, v4} HLC inverse, or same physical
        % input recast as post-HLC for the strict physical identity check.
        desired=plannedMap;
    end
    mapResidual=norm(fullBeta*desired(2:4)-fullAlpha(:));
  case {'V40_EQUAL_POST','V40_EQUAL_VIRTUAL'}
    % Physical-input amplitude matching under SAME modified v1 and SAME
    % current state. The virtual choice gets a different torque direction,
    % not an automatically safer input. Both are continuous-wave commands.
    vfTarget=a.vfRaw(:).';
    vfTarget(1:6)=vfTarget(1:6)+v38FullV1Wave(t,opts);
    [uBase,vsBase,alphaBase,betaNew]=v30VirtualMap(H,x,a,vfTarget);
    targetVf=vfTarget;vsCoupled=vsBase(:);vsTarget=vsCoupled;
    fullBeta=betaNew;fullAlpha=alphaBase(:);plannedMap=uBase;
    amp=abs(opts.continuousTorqueAmplitudeNm)*v33TorqueEnvelope(t,opts);
    if strcmpi(mode,'V40_EQUAL_POST')
       dTau=[0;amp;0];
       desired=[uBase(1);uBase(2:4)+dTau];
       % A modified torque without changed alpha is NOT map-consistent.
    else
       w=[1;-.65;.4];
       alphaTrial=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,...
            vfTarget,vsBase(:)+w,a.HLCparam);
       tauDir=betaNew\(alphaTrial(:)-alphaBase(:));
       if norm(tauDir,Inf)<1e-11
          error('CBF:HLCV40MatchedVsRank','Vs perturbation has no torque authority');
       end
       vsChange=w*(amp/norm(tauDir,Inf));
       vsTarget=vsBase(:)+vsChange;
       fullAlpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,...
            vfTarget,vsTarget,a.HLCparam);
       desired=[uBase(1);betaNew\fullAlpha(:)];
       dTau=desired(2:4)-uBase(2:4);
       plannedMap=desired;
    end
    mapResidual=norm(fullBeta*desired(2:4)-fullAlpha(:));
  case {'JOINT_DIRECT','JOINT_VIRTUAL_EQUIV','JOINT_NATIVE'}
    vf4=a.vfRaw(:).';vf4(1:5)=vf4(1:5)+dv;
    [fullU,fullVs,fullAlpha,fullBeta]=v30VirtualMap(H,x,a,vf4);
    plannedMap=fullU;
    switch upper(mode)
      case 'JOINT_DIRECT'
        desired=[fullU(1);baseline(2:4)+dTau];
      case 'JOINT_VIRTUAL_EQUIV'
        [tau,virtualVs,virtualTauErr]=v33VirtualTorqueTarget(H,x,a,...
              vf4,fullVs,fullAlpha,fullBeta,baseline(2:4)+dTau);
        desired=[fullU(1);tau];
      case 'JOINT_NATIVE'
        targetTau=fullU(2:4)+dTau;
        [tau,virtualVs,virtualTauErr]=v33VirtualTorqueTarget(H,x,a,...
              vf4,fullVs,fullAlpha,fullBeta,targetTau);
        desired=[fullU(1);tau];
    end
    mapResidual=norm(fullBeta*desired(2:4)-fullAlpha(:));
  otherwise,error('CBF:HLCV33Mode','Unknown case %s',mode);
 end
 if startsWith(S.status,'R1_FILTER_STOP_')
    S.tEnd=t;break; % do NOT log a fictitious applied-input row
 end
 u=max(lo,min(hi,desired));
 desiredClip=norm(desired-u,Inf);rawClip=norm(a.raw-u,Inf);
 if all(isfinite(plannedMap))
     physResidual=norm(fullBeta*u(2:4)-fullAlpha(:));
 end
 h=v23CableSafety(x,sc);tension=v23Tension(x,s,u(1));
 % Sampled interstep monitor: RK4 endpoints at dt/substeps. NOT a
 % continuous-time certificate, and no zero-order hold motor model.
 if k<K && opts.continuousIntersampleAudit && tension>0 && ...
       abs(a.thrustDenominator)>=opts.mappingDenominatorGuard && ...
       abs(a.qVertical)>=opts.mappingDenominatorGuard
      [xnext,subH,subTension]=v33SubstepDynamics(x,u,s,sc,opts);
 else
      xnext=[];
 end
 dTauMetric=NaN;if all(isfinite(plannedMap)),dTauMetric=norm(plannedMap(2:4),Inf);end
 last=last+1;
 row={t,mode,mhat,s.physical.massLoad,a.refPos(1),a.refPos(2),a.refPos(3),...
 x(8),x(9),x(10),a.posErr,a.velErr,a.raw(1),a.rawTorqueInf,...
 desired(1),norm(desired(2:4),Inf),u(1),norm(u(2:4),Inf),...
 desired(2),desired(3),desired(4),u(2),u(3),u(4),...
 rawClip,desiredClip,dv(1),dv(2),dv(3),dv(4),dv(5),...
 mapResidual,physResidual,a.vsNorm,a.alphaNorm,a.betaRcond,...
 a.thrustDenominator,a.refDerivNorm,h,tension,x(16),...
 a.cableOmega,max([lo(1)-a.raw(1),a.raw(1)-hi(1),0]),...
 max([abs(a.tau)-hi(2:4);0;0;0]),dTauMetric,...
 double(startsWith(S.status,'R1_FILTER_STOP_')),...
 virtualVs,virtualTauErr,subH,subTension,physResidual,norm(dTau,Inf),...
 v37TargetComponent(plannedMap,1),v37TargetTau(plannedMap),...
 v37TargetDiff(plannedMap,desired,1),v37TargetDiff(plannedMap,desired,2),...
 v37TargetDiff(plannedMap,u,1),v37TargetDiff(plannedMap,u,2),...
 v37Rcond(fullBeta),norm(vsChange,Inf)};
 row=[row,num2cell(nativeVf(1:5)),num2cell(targetVf(1:5)),...
     num2cell(a.vsRaw(:).'),num2cell(vsCoupled(:).'),...
     num2cell(vsChange(:).'),num2cell(vsTarget(:).'),...
     {nativeVf(6),targetVf(6)}];
 assert(numel(row)==numel(columns),'CBF:HLCV32RowShape','Row has %d fields expected %d',numel(row),numel(columns));
 rows(last,:)=row;
 S.tEnd=t;S.maxRawTau=max(S.maxRawTau,a.rawTorqueInf);
 S.maxRawT=max(S.maxRawT,abs(a.raw(1)));S.maxPosErr=max(S.maxPosErr,a.posErr);
 S.maxVs=max(S.maxVs,a.vsNorm);S.minH=min(S.minH,h);
 S.minTension=min(S.minTension,tension);
 S.nHnegative=S.nHnegative+double(h<0);
 S.nClip=S.nClip+double(desiredClip>1e-9);
 S.maxMapResidual=max(S.maxMapResidual,physResidual);
 S.maxJetDemand=max(S.maxJetDemand,a.refDerivNorm);
 S.maxAppliedMismatch=max(S.maxAppliedMismatch,rawClip);
 if isnan(S.firstClip) && desiredClip>1e-9,S.firstClip=t;end
 if isnan(S.firstHnegative) && h<0,S.firstHnegative=t;end
 if startsWith(S.status,'R1_FILTER_STOP_'),break;end
 if tension<=0
   S.status='STOP_NONPOSITIVE_APPLIED_TENSION';S.detail=sprintf('t=%.5g',t);break;
 end
 if abs(a.thrustDenominator)<opts.mappingDenominatorGuard || ...
    abs(a.qVertical)<opts.mappingDenominatorGuard
   S.status='STOP_HLC_DOMAIN';S.detail=sprintf('t=%.5g',t);break;
 end
 if k==K,break;end
 if isempty(xnext)
     x=v25StepOnce(x,u,s,opts);
 else
     x=xnext;
 end
 if any(~isfinite(x)) || max(abs([norm(x(1:4))-1,...
        norm(x(14:16))-1,dot(x(14:16),x(17:19))]))>1e-3
    S.status='STOP_PLANT_NONFINITE_OR_MANIFOLD';...
    S.detail=sprintf('t=%.5g',t);break;
 end
end
T=cell2table(rows(1:last,:),'VariableNames',columns);
end

function v32WriteCaseSummary(R,work)
cols={'caseID','referenceProfile','inputMode','initialStateProvenance',...
 'status','detail','lastTime_s','maxRawTorque_Nm','maxRawThrust_N',...
 'maxPositionError_m','maxVsNorm','minCableEllipsoidH',...
 'minAppliedTension_N','nUnsafeSamples','nInputClips',...
 'maxPhysicalMapResidual','maxReferenceJetNorm','firstClip_s',...
 'firstCableHNegative_s','maxRawToAppliedMismatch'};
assert(size(R,2)==numel(cols),'CBF:HLCV32SummaryColumns','Summary table field count');
writetable(cell2table(R,'VariableNames',cols),...
 fullfile(work,'V33_CONTINUOUS_CASES_SUMMARY.csv'));
end

function v32Plot(T,work,id)
try
 f=figure('Visible','off');
 tiledlayout(2,2,'Padding','compact');
 nexttile;plot(T.time_s,T.HLC_rawTauInf_Nm);hold on;...
    plot(T.time_s,T.appliedTauInf_Nm);hold off;ylabel('torque Nm');legend('raw','applied');
 nexttile;plot(T.time_s,T.posError_m);ylabel('load position error m');
 nexttile;plot(T.time_s,T.minCableH);ylabel('cable ellipse h');yline(0,'--');
 nexttile;plot(T.time_s,T.desiredToAppliedClipInf);ylabel('physical clipping');xlabel('s');
 exportgraphics(f,fullfile(work,['v32_plot_' lower(id) '.png']));close(f);
catch ME
 if exist('f','var')&&ishandle(f),close(f);end
 v23WriteText(fullfile(work,['V32_PLOT_WARNING_' id '.txt']),ME.message);
end
end

% =========================================================================
% V34 NORMAL SOURCE JET REPAIR + V33 TORQUE/VIRTUAL-MAP CAUSAL AUDITS
% =========================================================================
function v33LocalJetOrderAudit(sc,opts,work)
% Same-state derivative order sensitivity. Does not demonstrate future
% consistency of native generated Vfd or physical reachability.
H=v23MakeHLC(sc.settings,opts.dt);x=sc.x0(:);
lo=[sc.settings.input.thrustMin;sc.settings.input.torqueMin(:)];
hi=[sc.settings.input.thrustMax;sc.settings.input.torqueMax(:)];
cols={'time_s','includedV1Derivatives0To','deltaV1_0',...
 'deltaV1_1','deltaV1_2','deltaV1_3','deltaV1_4',...
 'rawThrust_N','rawTauInf_Nm','deltaThrust_N',...
 'deltaTauInf_Nm','physicalClipInf','alpha2Norm','betaRcond',...
 'interpretation'};
R=cell(0,numel(cols));
for t=[.65,.9,1.2,1.65,2.2]
 m=v23EstimatedMass(opts,t);a=v23HLC(x,t,sc,H,m);
 dv=v32V1Wave(t,opts);
 for degree=0:4
   vf=a.vfRaw(:).';vf(1:degree+1)=vf(1:degree+1)+dv(1:degree+1);
   [u,~,alpha,beta]=v30VirtualMap(H,x,a,vf);
   phys=max(lo,min(hi,u));
   R(end+1,:)={t,degree,dv(1),dv(2),dv(3),dv(4),dv(5),...
       u(1),norm(u(2:4),Inf),u(1)-a.raw(1),...
       norm(u(2:4)-a.raw(2:4),Inf),norm(u-phys,Inf),...
       norm(alpha(:)),rcond(beta),...
       'INCREMENTAL_V1_JET_ORDER_POINTWISE_ONLY'}; %#ok<AGROW>
 end
end
assert(size(R,2)==numel(cols),'CBF:HLCV33LocalAuditColumns');
writetable(cell2table(R,'VariableNames',cols),...
 fullfile(work,'V33_SAME_STATE_V1_DERIVATIVE_ORDER_AUDIT.csv'));
end

function f=v33TorqueEnvelope(t,opts)
% Analytic C7 switching. Smooth up to derivative 7 at both switching times.
s=opts.continuousV1Start; a=opts.continuousV1Rise;
h=opts.continuousV1Hold;b=opts.continuousV1Fall;
f=v32S7(t-s,a,0)-v32S7(t-(s+a+h),b,0);
end

function dtau=v33TorqueWave(t,opts,mode)
e=opts.continuousTorqueAmplitudeNm*v33TorqueEnvelope(t,opts);
dtau=zeros(3,1);u=upper(mode);
if contains(u,'ROLL'),dtau(1)=e;
elseif contains(u,'PITCH'),dtau(2)=e;
elseif contains(u,'YAW'),dtau(3)=e;
elseif startsWith(u,'JOINT_'),dtau(2)=e;
end
if contains(u,'NEG_'),dtau=-dtau;end
end

function [tau,vsOffset,err]=v33VirtualTorqueTarget(H,x,a,vf,vsBase,alphaBase,beta,targetTau)
% Affine-in-Vs consistency check. For a changed v1 jet use its OWN beta,
% Vs and alpha; never use stale original beta for an altered thrust map.
vsBase=vsBase(:);alphaBase=alphaBase(:);targetTau=targetTau(:);
assert(numel(vsBase)==3 && numel(targetTau)==3 && isequal(size(beta),[3 3]),...
 'CBF:HLCV33VirtualShape','virtual torque mapping shape mismatch');
J=zeros(3,3);
for j=1:3
   sample=vsBase;sample(j)=sample(j)+1;
   aj=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,sample,a.HLCparam);
   J(:,j)=aj(:)-alphaBase;
end
if ~all(isfinite(J(:))) || rcond(J)<1e-11
    error('CBF:HLCV33VirtualVsRank', ...
        'alpha2 derivative with respect to Vs is ill-conditioned (rcond %.4g)',rcond(J));
end
deltaVs=J\(beta*targetTau-alphaBase);
newAlpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,...
                          vsBase+deltaVs,a.HLCparam);
tau=beta\newAlpha(:);
vsOffset=norm(deltaVs,Inf);err=norm(tau-targetTau,Inf);
assert(err < 1e-7*max(1,norm(targetTau,Inf)),...
 'CBF:HLCV33AffineVsFailure','Vs-to-torque inverse is not affine at this point');
end

function [next,minH,minTen]=v33SubstepDynamics(x,u,s,sc,opts)
% Same 25-ms piecewise constant input, check each of substeps endpoints.
% For the R193_24 adapter this calls the existing original plant adapter.
p=opts;p.dt=opts.dt/opts.substeps;p.substeps=1;
next=x;minH=Inf;minTen=Inf;
for j=1:opts.substeps
  next=v25StepOnce(next,u,s,p);
  if ~all(isfinite(next)),return;end
  minH=min(minH,v23CableSafety(next,sc));
  minTen=min(minTen,v23Tension(next,s,u(1)));
end
end

function v33ComparePhysicalEquivalence(work,rows)
% Mapped vs direct torque: only if the applied u(t) and x(t) are same.
% Compare at matching sample times; early stops count as incomplete.
pairs={'TORQUE_ROLL_POST','TORQUE_ROLL_VIRTUAL';...
       'TORQUE_PITCH_POST','TORQUE_PITCH_VIRTUAL';...
       'TORQUE_PITCH_NEG_POST','TORQUE_PITCH_NEG_VIRTUAL';...
       'TORQUE_YAW_POST','TORQUE_YAW_VIRTUAL';...
       'JOINT_DIRECT','JOINT_VIRTUAL_EQUIV'};
col={'leftMode','rightMode','nMatched','nLeft','nRight',...
     'maxAppliedInputDifferenceInf','maxLoadStateDifference_m',...
     'maxRawTorqueDifferenceInf','maxCableHDifference','assessment'};
R=cell(0,numel(col));
for p=1:size(pairs,1)
 lmode=pairs{p,1};rmode=pairs{p,2};
 il=find(strcmp(rows(:,3),lmode));ir=find(strcmp(rows(:,3),rmode));
 if isempty(il)||isempty(ir),continue;end
 lfn=fullfile(work,['v32_trace_' lower(char(rows{il(1),1})) '.csv']);
 rfn=fullfile(work,['v32_trace_' lower(char(rows{ir(1),1})) '.csv']);
 if ~isfile(lfn)||~isfile(rfn),continue;end
 L=readtable(lfn);Rr=readtable(rfn);
 n=min(height(L),height(Rr));du=NaN;dp=NaN;dr=NaN;dh=NaN;
 if n>0
  assert(max(abs(L.time_s(1:n)-Rr.time_s(1:n)))<1e-10,...
    'CBF:HLCV33PairedTimes','paired torque experiments have unmatched times');
  d=[L.appliedT_N(1:n)-Rr.appliedT_N(1:n),...
      L.appliedTauX_Nm(1:n)-Rr.appliedTauX_Nm(1:n),...
      L.appliedTauY_Nm(1:n)-Rr.appliedTauY_Nm(1:n),...
      L.appliedTauZ_Nm(1:n)-Rr.appliedTauZ_Nm(1:n)];
  du=max(abs(d(:)));
  dx=[L.loadX_m(1:n)-Rr.loadX_m(1:n),...
      L.loadY_m(1:n)-Rr.loadY_m(1:n),...
      L.loadZ_m(1:n)-Rr.loadZ_m(1:n)];
  dp=max(sqrt(sum(dx.^2,2)));
  dr=max(abs(L.HLC_rawTauInf_Nm(1:n)-Rr.HLC_rawTauInf_Nm(1:n)));
  dh=max(abs(L.minCableH(1:n)-Rr.minCableH(1:n)));
 end
 if n==height(L) && n==height(Rr) && n>0 && du<1e-8 && dp<1e-7
    decision='POINTWISE_PHYSICAL_EQUIVALENCE_PASSED_NOT_SAFETY_PROOF';
 else
    decision='MISMATCH_OR_EARLY_STOP_REVIEW_LOGS';
 end
 R(end+1,:)={lmode,rmode,n,height(L),height(Rr),du,dp,dr,dh,decision}; %#ok<AGROW>
end
writetable(cell2table(R,'VariableNames',col),...
 fullfile(work,'V33_TORQUE_PHYSICAL_EQUIVALENCE_AUDIT.csv'));
end

% =========================================================================
% V35 critical causal audit: excite physical coupling without altering the
% actual Flight six-derivative reference. No claimed CBF safety proof.
% =========================================================================
function v35LocalSensitivityAudit(sc,opts,work)
H=v23MakeHLC(sc.settings,opts.dt);
x=sc.x0(:); q=x(14:16); w=x(17:19);
assert(numel(x)==19 && all(isfinite(x)) &&...
       abs(norm(q)-1)<1e-10 && abs(dot(q,w))<1e-10,...
       'CBF:HLCV35InitialManifold','Invalid initial physical manifold');
cols={'time_s','v1DerivativeOrder','baseV1Column','finiteDifferenceStep',...
 'dTperV1Derivative','dTauXperV1Derivative',...
 'dTauYperV1Derivative','dTauZperV1Derivative',...
 'dTauInfPerV1Derivative','baseRawT_N', 'baseRawTauInf_Nm',...
 'baseBetaRcond','initialQx','initialQy','initialQz',...
 'initialCableOmegaNorm','initialCableOrthogonalityError',...
 'interpretation'};
R=cell(0,numel(cols));
for tt=[0 0.65 0.9 1.2 2.2]
 a=v23HLC(x,tt,sc,H,v23EstimatedMass(opts,tt));
 v=a.vfRaw(:).';
 assert(numel(v)>=5,'CBF:HLCV35VfShape',...
  'Original R193 generated Vfd must contain at least 0..4 derivatives');
 for k=1:5
  hstep=1e-4*max(1,abs(v(k)));
  vp=v;vm=v;vp(k)=vp(k)+hstep;vm(k)=vm(k)-hstep;
  [up,~,~,~]=v30VirtualMap(H,x,a,vp);
  [um,~,~,~]=v30VirtualMap(H,x,a,vm);
  J=(up(:)-um(:))/(2*hstep);
  R(end+1,:)={tt,k-1,v(k),hstep,J(1),J(2),J(3),J(4),...
   norm(J(2:4),Inf),a.raw(1),a.rawTorqueInf,a.betaRcond,...
   q(1),q(2),q(3),norm(w),abs(dot(q,w)),...
   'POINTWISE_FINITE_DIFFERENCE_NOT_TIME_CONSISTENT_CBF'}; %#ok<AGROW>
 end
end
writetable(cell2table(R,'VariableNames',cols),...
 fullfile(work,'V35_PHYSICAL_STATE_V1_COLUMN_SENSITIVITY.csv'));
end

function v35R1InitialFeasibilityAudit(sc,work)
% Investigate why the old rectified *thrust only* CBF stops at t=0.
% Never silently change obstacle or omit a failing constraint.
cols={'obstacleIndex','originalCableH','rectifiedH','thrustCoefficient',...
 'requiredRHS','nonAffineH2','earlyTorqueEffect',...
 'feasibleLowerT_N','feasibleUpperT_N','status'};
R=cell(0,numel(cols));
for j=1:numel(sc.obstacles)
 z=CBF_V18_R1_RectifiedCable(sc.x0,sc.settings,sc.obstacles{j});
 a=z.rectifiedCoefficient;b=z.rectifiedRHS;
 lo=sc.settings.input.thrustMin;hi=sc.settings.input.thrustMax;
 verdict='GEOMETRIC_ROW_FEASIBLE';
 if z.hR< -1e-9
   verdict='INITIAL_RECTIFIED_SET_INVALID';
 elseif z.nonAffineH2>1e-7 || z.earlyTorqueEffect>1e-8
   verdict='NONAFFINE_OR_EARLY_TORQUE';
 elseif abs(a)<1e-10
   if b>1e-9,verdict='ZERO_INPUT_AUTHORITY_POSITIVE_RHS';end
 elseif a>0
   lo=max(lo,b/a);
 else
   hi=min(hi,b/a);
 end
 if lo>hi+1e-8,verdict='INFEASIBLE_THRUST_INTERVAL';end
 R(end+1,:)={j,v23CableSafety(sc.x0,sc),z.hR,a,b,...
  z.nonAffineH2,z.earlyTorqueEffect,lo,hi,verdict}; %#ok<AGROW>
end
writetable(cell2table(R,'VariableNames',cols),...
 fullfile(work,'V35_R1_INITIAL_GEOMETRY.csv'));
end

function v35CompareV1DerivativeModes(work,rows)
% Full-loop equality is only expected in the *degenerate* vertical state.
% Each comparison is on common discrete sample timestamps.
inputs={'POST_V1_T','V1_VALUE','V1_D1','V1_D2','V1_D3','V1_JET'};
ids=cell(size(inputs));
for k=1:numel(inputs)
 ix=find(strcmp(rows(:,3),inputs{k}),1);
 if isempty(ix),return;end
 ids{k}=lower(rows{ix,1});
end
cols={'leftMode','rightMode','nSamples',...
 'maxAppliedThrustDifference_N','maxAppliedTorqueDifference_Nm',...
 'maxLoadPositionDifference_m','maxRawHlcTorqueDifference_Nm',...
 'interpretation'};
R=cell(0,numel(cols));
for k=2:numel(inputs)
 a=readtable(fullfile(work,['v32_trace_' ids{k-1} '.csv']));
 b=readtable(fullfile(work,['v32_trace_' ids{k} '.csv']));
 n=min(height(a),height(b));
 assert(all(abs(a.time_s(1:n)-b.time_s(1:n))<1e-10),...
  'CBF:HLCV35TimeAlign','V1 mode timestamps differ');
 dT=max(abs(a.appliedT_N(1:n)-b.appliedT_N(1:n)));
 dTau=max([abs(a.appliedTauX_Nm(1:n)-b.appliedTauX_Nm(1:n));...
  abs(a.appliedTauY_Nm(1:n)-b.appliedTauY_Nm(1:n));...
  abs(a.appliedTauZ_Nm(1:n)-b.appliedTauZ_Nm(1:n))]);
 dP=max(sqrt((a.loadX_m(1:n)-b.loadX_m(1:n)).^2+...
  (a.loadY_m(1:n)-b.loadY_m(1:n)).^2+...
  (a.loadZ_m(1:n)-b.loadZ_m(1:n)).^2));
 dRaw=max(abs(a.HLC_rawTauInf_Nm(1:n)-b.HLC_rawTauInf_Nm(1:n)));
 R(end+1,:)={inputs{k-1},inputs{k},n,dT,dTau,dP,dRaw,...
  'SAME_OR_DIFFERENT_PHYSICAL_INPUT_CHECK_NOT_SAFETY_OR_CONSISTENCY_PROOF'}; %#ok<AGROW>
end
writetable(cell2table(R,'VariableNames',cols),...
 fullfile(work,'V35_V1_DERIVATIVE_CLOSED_LOOP_DIFFERENCES.csv'));
end

% =========================================================================
% V37: TIME-CONSISTENT INCREMENTAL VIRTUAL COMMANDS, CONTINUOUS CLOSED LOOP
% =========================================================================
function out=v37ConfigureMode(opts,mode)
out=opts;
u=upper(char(mode));
if endsWith(u,'_LOW')
 out.continuousV1Amplitude=.25*opts.continuousV1Amplitude;
 out.continuousTorqueAmplitudeNm=.25*opts.continuousTorqueAmplitudeNm;
 out.v37DeltaVs=.25*opts.v37DeltaVs(:);
elseif contains(u,'_HIGH')
 out.continuousV1Amplitude=2.0*opts.continuousV1Amplitude;
 out.continuousTorqueAmplitudeNm=2.0*opts.continuousTorqueAmplitudeNm;
 out.v37DeltaVs=2.0*opts.v37DeltaVs(:);
end
if contains(u,'_SLOW')
 out.continuousV1Rise=1.6;
 out.continuousV1Fall=1.6;
end
end

function z=v37VirtualVsWave(t,opts,mode)
% Analytic C7 incremental correction to v2-v4. This is a continuous
% virtual *increment*; it does NOT certify native generated Vfd(t) has
% exact continuous-time jet from the closed-loop state-feedback law.
z=opts.v37DeltaVs(:)*v33TorqueEnvelope(t,opts);
u=upper(char(mode));
if contains(u,'NATIVE_VS_X'),z(2:3)=0;end
if contains(u,'NATIVE_VS_Y') && ~contains(u,'NATIVE_VS_YAW'),z([1 3])=0;end
if contains(u,'NATIVE_VS_YAW'),z(1:2)=0;end
if contains(u,'NATIVE_V1') || strcmp(u,'V37_POST_T') || startsWith(u,'V37_POST_T_')
 z(:)=0;
end
end

function v=v37TargetComponent(u,k)
if all(isfinite(u)),v=u(k);else,v=NaN;end
end
function v=v37TargetTau(u)
if all(isfinite(u)),v=norm(u(2:4),Inf);else,v=NaN;end
end
function v=v37TargetDiff(target,u,which)
if all(isfinite(target))
 if which==1,v=abs(target(1)-u(1));
 else,v=norm(target(2:4)-u(2:4),Inf);end
else,v=NaN;end
end
function v=v37Rcond(beta)
if isequal(size(beta),[3,3]),v=rcond(beta);else,v=NaN;end
end

function v37WriteDetailedResults(work,R,opts)
% Compare common time intervals AND report censoring due to early stops.
% A small raw HLC torque is not equivalent to a safe, feasible trajectory.
n=size(R,1);
cols={'caseID','mode','status','tEnd_s','nSamples',...
 'maxHLCRawTau_Nm','maxDesiredTau_Nm','maxAppliedTau_Nm',...
 'maxDesiredThrust_N','maxAppliedThrust_N','maxPositionError_m',...
 'maxVirtualTResidualAfterClip_N','maxVirtualTauResidualAfterClip_Nm',...
 'maxTargetTResidualBeforeClip_N','maxTargetTauResidualBeforeClip_Nm',...
 'minAlteredBetaRcond','maxDeltaVs','nDesiredClipSteps',...
 'minCableH','minSubstepH','minSubstepTension_N',...
 'nUnsafeSamples','nNonpositiveTensionSamples','inputChangeDutyFraction',...
 'maxHLCvsNorm','maxHLCAlpha2Norm','v1Amplitude','v1Rise_s',...
 'v1Fall_s','torqueAmplitude_Nm','deltaVsNorm'};
M=cell(0,numel(cols));
for j=1:n
 id=R{j,1};mode=R{j,3};p=fullfile(work,['v32_trace_' lower(id) '.csv']);
 if ~isfile(p),continue;end
 t=readtable(p);
 if isempty(t),continue;end
 op=v37ConfigureMode(opts,mode);
 B=[t.appliedTauX_Nm,t.appliedTauY_Nm,t.appliedTauZ_Nm];
 maxAp=max(max(abs(B),[],2));
 minH=min(t.minCableH);
 subH=t.minSubstepCableH;
 subTen=t.minSubstepTensionN;
 M(end+1,:)={id,mode,R{j,5},R{j,7},height(t),...
 max(t.HLC_rawTauInf_Nm),max(t.desiredTauInf_Nm),maxAp,...
 max(t.desiredT_N),max(t.appliedT_N),max(t.posError_m),...
 v37MaxFinite(t.afterClipTargetThrustMismatch_N),...
 v37MaxFinite(t.afterClipTargetTorqueMismatch_Nm),...
 v37MaxFinite(t.beforeClipTargetThrustMismatch_N),...
 v37MaxFinite(t.beforeClipTargetTorqueMismatch_Nm),...
 v37MinFinite(t.alteredBetaRcond),max(t.incrementalVsCommandInf),...
 sum(t.desiredToAppliedClipInf>1e-9),minH,v37MinFinite(subH),...
 v37MinFinite(subTen),sum(t.minCableH<0),...
 sum(t.appliedTension_N<=0),...
 mean(t.rawToAppliedClipInf>1e-9),...
 max(t.VsNorm),max(t.alpha2Norm),...
 op.continuousV1Amplitude,op.continuousV1Rise,...
 op.continuousV1Fall,op.continuousTorqueAmplitudeNm,...
 norm(op.v37DeltaVs(:),Inf)}; %#ok<AGROW>
end
assert(size(M,2)==numel(cols),'CBF:HLCV37MetricCols',...
    'V37 metric schema mismatch');
writetable(cell2table(M,'VariableNames',cols),...
 fullfile(work,'V37_CONTINUOUS_CORRECTION_METRICS.csv'));
P={'C02','C03','post_thrust_only_vs_native_v1_jet';...
   'C03','C04','native_v1_vs_v1_v2_v3_v4';...
   'C04','C05','same_4D_physical_input_virtual_vs_direct_identity';...
   'C04','C06','native_4D_vs_independent_post_4D';...
   'C07','C08','post_torque_vs_native_virtual_vs';...
   'C02','C23','two_implementations_same_post_thrust';...
   'C03','C28','full_six_component_v1_jet_vs_legacy_orders0to4'};
col={'caseA','caseB','purpose','nCommonSamples','bothFullHorizon',...
    'maxAppliedThrustDifference_N','maxAppliedTorqueDifference_Nm',...
    'maxLoadPositionDifference_m','maxHLCrawTorqueDifference_Nm',...
    'samePhysicalInputToleranceMet'};
Q=cell(0,numel(col));
for k=1:size(P,1)
 ia=P{k,1};ib=P{k,2};
 pa=fullfile(work,['v32_trace_' lower(ia) '.csv']);
 pb=fullfile(work,['v32_trace_' lower(ib) '.csv']);
 if ~isfile(pa)||~isfile(pb),continue;end
 a=readtable(pa);b=readtable(pb);
 nCommon=min(height(a),height(b));
 if nCommon<1,continue;end
 ta=a.time_s(1:nCommon);tb=b.time_s(1:nCommon);
 assert(max(abs(ta-tb))<1e-10,'CBF:HLCV37TimeAlignment',...
      'V37 pairing needs matching time grids');
 dt=max(abs(a.appliedT_N(1:nCommon)-b.appliedT_N(1:nCommon)));
 x=[a.appliedTauX_Nm(1:nCommon)-b.appliedTauX_Nm(1:nCommon),...
 a.appliedTauY_Nm(1:nCommon)-b.appliedTauY_Nm(1:nCommon),...
 a.appliedTauZ_Nm(1:nCommon)-b.appliedTauZ_Nm(1:nCommon)];
 dTau=max(abs(x(:)));
 p1=[a.loadX_m(1:nCommon)-b.loadX_m(1:nCommon),...
 a.loadY_m(1:nCommon)-b.loadY_m(1:nCommon),...
 a.loadZ_m(1:nCommon)-b.loadZ_m(1:nCommon)];
 dp=max(sqrt(sum(p1.^2,2)));
 dr=max(abs(a.HLC_rawTauInf_Nm(1:nCommon)-...
          b.HLC_rawTauInf_Nm(1:nCommon)));
 bothFull=(height(a)==height(b)) &&...
    abs(a.time_s(end)-opts.continuousDuration)<1e-8;
 same=(dt<1e-9&&dTau<1e-9&&dp<1e-7);
 Q(end+1,:)={ia,ib,P{k,3},nCommon,double(bothFull),dt,dTau,...
    dp,dr,double(same)}; %#ok<AGROW>
end
writetable(cell2table(Q,'VariableNames',col),...
 fullfile(work,'V37_MATCHED_CLOSED_LOOP_PAIRS.csv'));
% The following identity is a mandatory numerical self-audit rather than
% a criterion that virtual feedback synthesis is beneficial.
k=find(strcmp(Q(:,3),'same_4D_physical_input_virtual_vs_direct_identity'),1);
if ~isempty(k) && ~Q{k,end}
 v23WriteText(fullfile(work,'V37_PHYSICAL_IDENTITY_WARNING.txt'),...
 'C04/C05 should match when both apply the same real 4-input; inspect truncation and MATLAB errors.');
end
notes={...
 'V37: ORIGINAL 0..6 Flight reference never modified. 25ms zero-order hold and 4 RK substeps; all closed-loop states feed back into the next HLC call.';...
 'Each case uses the SAME initially tilted physical state (or user supplied real snapshot), NOT a single frozen-state evaluation. For causal grouping only virtual incremental commands and timing change.';...
 'Native v1 is modified as an analytic S7 function with derivatives 0..4. Native v2,v3,v4 are altered smoothly by S7(deltaVs). Modified thrust and torque are recomputed with original HLC Uf, Beta2, V2_alpha2 in the SAME state/tick.';...
 'The original Vfd state-feedback outputs have NOT been shown to represent a continuous-time derivative jet. Only the inserted incremental delta v1 has analytic time derivatives. No formal closed-loop virtual-exactness theorem follows.';...
 'POST_T applies exactly the altered-native virtual thrust, but uses baseline HLC torques; POST_INDEPENDENT also modifies torque independently. NATIVE_ALL regenerates torque from altered v1 jet and deltaVs. C04/C05 apply same real 4D u and MUST have same physical evolution.';...
 'T and tau physical constraints are still applied. A 4D virtual map may hold for the requested input but FAIL for the actually applied saturated input. Demand mismatches and post-clip map residuals distinguish these.';...
 'R1_EXACT can stop at time zero due to zero input authority. That is a genuine R1 feasibility result, NOT a test of continuously feasible CBF action or a success of HLC virtual CBF.';...
 'Results are diagnostic only: use min cable h, min substep h/tension and case stops. Sampling inside 25ms does not provide a mathematical intersample invariance guarantee.';...
 'Magnitude and ramp speed are varied in coupled_full. Changes in resultant torques are not a matched-force experiment unless explicitly paired and measured. Inference about high-order coupling needs physical input and HLC residual logs.';...
 'No full Flight sensor/EKF/mode transition, no hardware-derived actuator limits, no actuator motor dynamics. Estimated load mass 0.01 is fixed initial EKF by default, not true 0.14 and not live EKF.'};
v23WriteText(fullfile(work,'V37_PROTOCOL_AND_LIMITS.txt'),strjoin(notes,newline));
end
function v=v37MaxFinite(x)
y=x(isfinite(x));if isempty(y),v=NaN;else,v=max(y);end
end
function v=v37MinFinite(x)
y=x(isfinite(x));if isempty(y),v=NaN;else,v=min(y);end
end

