function out=v40ResearchSuite(work,opts)
% This is an investigation, NOT a safety certified flight controller.
% All "normal Flight" comparisons use the original 0..6 R193 generator;
% no altered target curve, replan, or external saved trajectory is inserted.
assert(strcmpi(opts.parameterSet,'R193'),'CBF:HLCV40R193Only',...
    'V40 works with the R193 physical/control parameter set');
assert(opts.dt>0 && abs(opts.dt-.025)<1e-10,...
    'CBF:HLCV40Dt','V19 matching requires the original 25-ms controller period');
sc=v40OriginalReferenceScenario(opts);
caseRows=cell(0,16);
% Position offsets preserve the physical 19-state manifold, unlike modifying
% q, cable angular rate, or adding an inconsistent reference. The user asked
% to isolate 10 m and 20 m tracking errors, keeping the source reference.
offsets={... 
 'BASE_0',[0;0;0];...
 'PX_10',[10;0;0];...
 'NX_10',[-10;0;0];...
 'PY_10',[0;10;0];...
 'NY_10',[0;-10;0];...
 'PX_20',[20;0;0];...
 'NX_20',[-20;0;0];...
 'PX_30',[30;0;0];...
 'NX_30',[-30;0;0];...
 'PZ_10',[0;0;10]};
for j=1:size(offsets,1)
    tag=offsets{j,1};delta=offsets{j,2};
    modes={'NOMINAL'};
    if any(strcmp(tag,{'BASE_0','PX_10','PY_10','PX_20'}))
       modes={'NOMINAL','V37_POST_T','V37_NATIVE_V1',...
              'V40_EQUAL_POST','V40_EQUAL_VIRTUAL'};
    end
    for k=1:numel(modes)
       scCase=sc;scCase.x0(8:10)=sc.x0(8:10)+delta;
       local=opts;local.v40StartTime=0;local.continuousDuration=opts.v40FarDuration;
       local.plant='R193_24';
       [caseRows,~]=v40OneCase(work,caseRows,scCase,local,...
          ['F_' tag '_' modes{k}], 'NORMAL_REFERENCE',modes{k},norm(delta),...
          'STATE_OFFSET_NOT_TARGET_CHANGE');
    end
end
% V19 is a SEPARATE original scenario/trajectory, used ONLY to reproduce
% the documented 135-Nm intervention mechanism. Do not relabel it as the
% R193 normal-Flight straight-reference trial above.
if opts.v40ComputeV19
 try
    sc19=CBF_V19_Scenarios('straight_single','R193');sc19.dt=opts.dt;
    [startState,initInfo]=v40GetV19PreInterventionState(sc19,opts,1.75);
    v23WriteText(fullfile(work,'V40_V19_BRANCH_PROVENANCE.txt'),initInfo);
    if all(isfinite(startState))
       sc19.x0=startState;
       modes={'NOMINAL','R1_EXACT','V41_R1_MATCH_T_V1_ZERO',...
            'V37_POST_T','V37_NATIVE_V1',...
            'V37_NATIVE_ALL','V37_POST_INDEPENDENT',...
            'V40_EQUAL_POST','V40_EQUAL_VIRTUAL',...
            'V37_POST_SAME_ALL'};
       for k=1:numel(modes)
          local=opts;local.plant='V11_19';local.v40StartTime=1.75;
          local.continuousDuration=opts.v40V19Duration;
          % A smooth analytic wave itself is defined for t>=1.75; the
          % branch starts at 1.75 with ZERO wave value and derivatives;
          % no exogenous wave history is skipped and branch is continuous.
          local.continuousV1Start=1.75;
          local.continuousV1Rise=.8;
          local.continuousV1Hold=.25;
          local.continuousV1Fall=.8;
          local.continuousV1Amplitude=8;
          local.continuousTorqueAmplitudeNm=.05;
          [caseRows,~]=v40OneCase(work,caseRows,sc19,local,...
              ['V19_' modes{k}],'V19_PRECBF_SNAPSHOT_1P75',modes{k},NaN,...
              'BRANCH_AT_1P75_ORIGINAL_V19_NOT_NORMAL_FLIGHT_REFERENCE');
       end
    end
 catch MEv19
  v23WriteText(fullfile(work,'V40_V19_BRANCH_SETUP_ERROR.txt'),...
      getReport(MEv19,'extended','hyperlinks','off'));
 end
end
names={'caseID','referenceKind','mode','offsetPositionNorm_m',...
 'initialStateProvenance','status','lastTime_s','rawHlcTauMax_Nm',...
 'positionErrorMax_m','minCableH','minTension_N','nClipped',...
 'nUnsafeSample','firstClip_s','maxPhysicalMapResidual','maxRefJetNorm'};
assert(size(caseRows,2)==numel(names),'CBF:HLCV40SummaryShape',...
 'V40 summary columns mismatch');
summary=cell2table(caseRows,'VariableNames',names);
writetable(summary,fullfile(work,'V40_CONTINUOUS_CASE_SUMMARY.csv'));
% V42: separate true sampled collision/tension/ground observations,
% raw HLC saturation, desired-input saturation, and tracking recovery.
% These audits NEVER imply a continuous-time CBF certificate.
try
    v42FlightSurvivalAudit(work,summary,opts,sc.settings.physical.cableLength);
catch MEflight
    v23WriteText(fullfile(work,'V42_FLIGHT_AUDIT_WARNING.txt'),...
        getReport(MEflight,'extended','hyperlinks','off'));
end
statuses=string(summary.status);
out=struct('nCases',height(summary),...
 'nFailedCases',sum(statuses~='COMPLETED_DIAGNOSTIC_NOT_SAFETY_CERTIFIED'),...
 'nRuntimeErrors',sum(startsWith(statuses,'MATLAB_ERROR_')),...
 'nR1FilterStops',sum(startsWith(statuses,'R1_FILTER_STOP_')));
% Timing of generated Vfd derivatives: evaluate along SAME physical plant
% vector field, held input for epsilon, and check multiple epsilon sizes.
try
 v40VfdDerivativeAudit(sc,opts,work);
catch ME
 v23WriteText(fullfile(work,'V40_VFD_AUDIT_ERROR.txt'),...
    getReport(ME,'extended','hyperlinks','off'));
end
v23WriteText(fullfile(work,'V40_VALIDITY_AND_DESIGN.txt'),...
 strjoin({... 
 'REFERENCE: normal Flight sweep uses unchanged R193 gen_ref_line 1.5m/s +y, 0..6. 10m/20m refer to shifted PHYSICAL initial payload position, not changed target trajectories.';...
 'The origin-aligned straight flight has special q vertical symmetry and cannot establish general high-order virtual-input compatibility. V19 diagnostic uses its ORIGINAL distinct reference/plant.';...
 'RESULT STATUS: all numerical cases monitor physical saturation, cable geometry and tension but are not safe flight certificates. Stopping early is a meaningful region-of-attraction/feasibility warning.';...
 'VFD: original Vfd returns columns based on a discrete-time gain/e_z construction. Derivative audit compares d/dt(Vfd column k) along the actual nonlinear plant to column k+1 with constant applied physical input over epsilon, not a closed-loop gain derivation or safety proof.';...
 'R1 exact branch uses actual original rectified CBF evaluated every 25ms, stops on infeasibility. V1/Vs diagnostic wave uses an EXOGENOUS smooth analytic signal, NOT the actual R1 thrust command and NOT a proved CBF safety replacement.';...
 'MATHEMATICAL DISTINCTION: pointwise virtual inverse consistency does not guarantee native Vfd derivative coherence, causal actuator response, physical bounds, or future target tracking. Equal torque-change magnitudes are a direction comparison, not an objective equivalence proof.';...
 'Controller mass estimate fixed at supplied value, NOT live EKF unless massTimes/massEstimates are supplied. 4 substeps are numerical monitors only, no intersample invariance theorem.'},newline));
end

function sc=v40OriginalReferenceScenario(opts)
% Match v32 generation exactly; source reference remains fixed.
assert(exist('gen_ref_line','file')==2 && ...
       exist('gen_ref_for_rigid_body','file')==2,...
       'CBF:HLCV40ReferenceMissing','Original Flight reference generators unavailable');
raw=gen_ref_line('p0',[0,0,3],'velocity',1.5,'direction',[0,1,0]);
z=gen_ref_for_rigid_body(raw,6);
assert(isstruct(z) && isfield(z,'pYaw') && ...
       isa(z.pYaw,'function_handle'),...
       'CBF:HLCV40ReferenceJet','Source 6-jet structurally invalid');
sc=CBF_V19_Scenarios('straight_single','R193');
sc.dt=opts.dt;L=sc.settings.physical.cableLength;
sc.refFull=@(t)v32FlightLoadJet(z.pYaw,t,L);
sc.ref=@(t,k)v32XYZJet(sc.refFull,t,k);
x=sc.x0(:);ref=sc.refFull(0);
x(8:10)=ref(1:3);x(11:13)=ref(5:7);
x(1:4)=[cos(ref(4)/2);0;0;sin(ref(4)/2)];
x(14:16)=[0;0;-1];x(17:19)=zeros(3,1);
sc.x0=x;
o=struct();o.type='ellipsoid';
o.center=[ref(1)+.28;ref(2)+2.5;ref(3)+L/2];
o.axes=[.28;.36;.55];r=pi/5;
o.R=[cos(r) -sin(r) 0;sin(r) cos(r) 0;0 0 1];
sc.obstacles={o};
end

function [rows,pass]=v40OneCase(work,rows,sc,opts,id,refKind,mode,offset,origin)
pass=false;
fprintf('[HLC V40] %s / %s / start=%.4g / T=%.3g\n',...
       id,mode,opts.v40StartTime,opts.continuousDuration);
try
 [T,S]=v32RunContinuousOne(sc,mode,opts);
 if opts.v40StoreTraces
     writetable(T,fullfile(work,['v40_trace_' lower(id) '.csv']));
 end
 rows(end+1,:)={id,refKind,mode,offset,origin,S.status,...
       S.tEnd,S.maxRawTau,S.maxPosErr,S.minH,S.minTension,...
       S.nClip,S.nHnegative,S.firstClip,S.maxMapResidual,S.maxJetDemand};
 pass=strcmp(S.status,'COMPLETED_DIAGNOSTIC_NOT_SAFETY_CERTIFIED');
catch ME
 v23WriteText(fullfile(work,['V40_ERROR_' id '.txt']),...
     getReport(ME,'extended','hyperlinks','off'));
 rows(end+1,:)={id,refKind,mode,offset,origin,...
     ['MATLAB_ERROR_' ME.identifier],NaN,NaN,NaN,NaN,...
     NaN,NaN,NaN,NaN,NaN,NaN};
end
end

function [x,info]=v40GetV19PreInterventionState(sc,opts,tStop)
% Reintegrate ORIGINAL V19 R1 at each 25ms from t=0 to tStop.
% If R1 first acts after 2.125, this is the exact original pre-CBF state;
% otherwise explicitly record the first R1 action (not a fabricated match).
s=sc.settings;x=sc.x0(:);H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
q=round(tStop/opts.dt);first=NaN;status='OK';
for i=0:q-1
 t=i*opts.dt;mhat=v23EstimatedMass(opts,t);
 a=v23HLC(x,t,sc,H,mhat);
 baseline=min(hi,max(lo,a.raw));
 [u,msg]=v25R1ExactFilter(x,s,sc.obstacles,baseline);
 if ~strcmp(msg,'OK')
    status=['STOP_' msg];x(:)=NaN;break;
 end
 if isnan(first) && norm(u-baseline,Inf)>1e-8,first=t;end
 local=opts;local.plant='V11_19';
 x=v25StepOnce(x,u,s,local);
end
info=sprintf(['V19 EXACT R1 PRE-INTERVENTION STATE FROM ORIGINAL V11_19 PLANT\n',...
 'target_t=%.9g s, first_input_change=%.9g s, status=%s\n',...
 'This is not the user ordinary R193 Flight trajectory; no automatic live EKF.\n'],...
 tStop,first,status);
end

function v40VfdDerivativeAudit(scNormal,opts,work)
% Necessary condition for a physical time-derivative chain:
% d/dt of each generated vf column must equal the following column.
% We use actual nonlinear dx=f(x,u), apply the SAME u for epsilon time,
% and refine epsilon. The k=0 analytic chain rule is recorded separately.
scV19=CBF_V19_Scenarios('straight_single','R193');
scV19.dt=opts.dt;
[xV19,provenance]=v40GetV19PreInterventionState(scV19,opts,2.125);
rows=cell(0,13);
labels={'R193_NOMINAL','R193_FAR_X10','V19_PRECBF'};
for j=1:numel(labels)
 lab=labels{j};sco=scNormal;x=sco.x0(:);t=0;
 if strcmp(lab,'R193_FAR_X10'),x(8)=x(8)+10;end
 if strcmp(lab,'V19_PRECBF')
    if any(~isfinite(xV19)),continue;end
    sco=scV19;x=xV19;t=2.125;
 end
 H=v23MakeHLC(sco.settings,opts.dt);
 a=v23HLC(x,t,sco,H,v23EstimatedMass(opts,t));
 lo=[sco.settings.input.thrustMin;sco.settings.input.torqueMin(:)];
 hi=[sco.settings.input.thrustMax;sco.settings.input.torqueMax(:)];
 u=min(hi,max(lo,a.raw));
 if strcmp(lab,'V19_PRECBF')
  [uR1,msg]=v25R1ExactFilter(x,sco.settings,sco.obstacles,u);
  if strcmp(msg,'OK'),u=uR1;end
 end
 vv=a.vfRaw(:).';
 for dte=[.0125 .00625 .003125 .0015625]
   p=opts;p.dt=dte;p.substeps=4;
   if strcmp(lab,'V19_PRECBF'),p.plant='V11_19';else,p.plant='R193_24';end
   xx=v25StepOnce(x,u,sco.settings,p);
   anew=v23HLC(xx,t+dte,sco,H,v23EstimatedMass(opts,t));
   vv2=anew.vfRaw(:).';
   % Chain rule for Vfd value: F1*[zdot - vz; zddot - actual a_z]
   % Actual ddot z is taken from the ORIGINAL NONLINEAR plant vector field.
   if strcmp(lab,'V19_PRECBF')
       dx=v23RHS(x,u,sco.settings);
   else
       dtiny=1e-5;p2=opts;p2.dt=dtiny;p2.substeps=2;p2.plant='R193_24';
       xx2=v25StepOnce(x,u,sco.settings,p2);
       dx=(xx2-x)/dtiny; % R193 adapter, converges as dtiny is refined
   end
   dz_exact=H.F1(1)*(a.refVel(3)-x(13)) +...
            H.F1(2)*(a.refAcc(3)-dx(13));
   for kk=0:4
      observed=(vv2(kk+1)-vv(kk+1))/dte;
      claimed=vv(kk+2);
      ana=NaN;if kk==0,ana=dz_exact;end
      rows(end+1,:)={lab,t,dte,kk,vv(kk+1),claimed,...
           observed,observed-claimed,ana,ana-claimed,...
           u(1),norm(u(2:4),Inf),a.betaRcond};
   end
 end
end
cols={'sourceState','time_s','step_s','VfdColumnOrder',...
      'VfdValue','claimedNextColumn','finiteForwardDerivative',...
      'forwardMinusClaimed','chainRuleDerivativeOrder0',...
      'chainRuleMinusClaimed','appliedThrust_N','appliedTauInf_Nm',...
      'Beta2Rcond'};
assert(size(rows,2)==numel(cols),'CBF:HLCV40VfdShape','Vfd audit columns mismatch');
writetable(cell2table(rows,'VariableNames',cols),...
  fullfile(work,'V40_VFD_ACTUAL_DERIVATIVE_REFINEMENT.csv'));
v23WriteText(fullfile(work,'V40_V19_VFD_SNAPSHOT_NOTE.txt'),provenance);
end

