function v36StartManifest(work,opts)
% Non-blocking metadata: the core original-reference simulation is the goal.
info=sprintf(['V36 CONTINUOUS CLOSED-LOOP TEST CONFIGURATION\n',...
 'Reference: ORIGINAL R193 gen_ref_line 1.5 m/s +Y; original 0..6 jet.\n',...
 'No replanning, no C7 lane unless explicitly opted in.\n',...
 'Plant: %s; dt=%.12g s; substeps=%d; duration=%.12g s.\n',...
 'Case profile=%s; synthetic initial tilt=%.12g deg; roll=%.12g deg; cable angular speed=%.12g rad/s; lateral velocity=%.12g m/s.\n',...
 'Controller mass estimate provenance=%s.\n',...
 'V35 failure was an ADMINISTRATIVE handover character-count assert.\n',...
 'A completed simulation is NOT a CBF safety guarantee.\n'],...
 char(opts.plant),opts.dt,opts.substeps,opts.continuousDuration,...
 char(opts.continuousProfile),opts.continuousDiagnosticCableTiltDeg,...
 opts.continuousDiagnosticBodyRollDeg,opts.continuousDiagnosticCableOmegaRadps,...
 opts.continuousDiagnosticLateralVelocityMps,char(opts.massEstimateLabel));
try
 v23WriteText(fullfile(work,'V36_RUN_CONFIGURATION.txt'),info);
catch ME
 warning('CBF:HLCV36Manifest','Could not write optional configuration: %s',ME.message);
end
end

function v36ExecutionManifest(work,result)
% Always written after completed trace loops if possible; all interpretation
% is based on statuses in the archived V33_CONTINUOUS_CASES_SUMMARY.csv.
info=sprintf(['V36 execution result (before archiving)\n',...
 'nCases=%g\nnFailedCases=%g\nnRuntimeErrors=%g\nnR1FilterStops=%g\n',...
 'Compare per-case CSV timestamps and individual trace termination.\n',...
 'R1 filtering stop is NOT a MATLAB runtime error.\n',...
 'Clipped real input is NOT equal to raw/virtual mapped controller input.\n',...
 'No measured Flight EKF snapshot was supplied automatically.\n'],...
 result.nCases,result.nFailedCases,result.nRuntimeErrors,result.nR1FilterStops);
try
 v23WriteText(fullfile(work,'V36_EXECUTION_COUNTS.txt'),info);
catch ME
 warning('CBF:HLCV36Manifest','Could not write optional counts: %s',ME.message);
end
end

