function v34SmoothstepAudit(work,opts)
% Independent endpoint + mirror identity audit for the S7 jet.
% Uses strict absolute endpoint tolerance. No tolerance inflation.
R=cell(0,6);
Dlist=unique([opts.continuousFastRamp,opts.continuousSlowRamp,...
    opts.continuousV1Rise,opts.continuousV1Fall]);
ss=[0,.01,.125,.25,.5,.75,.875,.99,1];
for D=Dlist
  for s=ss
    for k=0:7
      val=v32S7(D*s,D,k);
      mirror=v32S7(D*(1-s),D,k);
      if k==0, symerr=abs(val+mirror-1);
      else, symerr=abs(val-(-1)^(k+1)*mirror);end
      isEndpoint=(s==0 || s==1);
      endpointErr=0;
      if isEndpoint
        expected=double(k==0 && s==1);
        endpointErr=abs(val-expected);
      end
      R(end+1,:)={D,s,k,val,symerr,endpointErr}; %#ok<AGROW>
    end
  end
end
n={'rampDuration_s','normalizedTime','derivativeOrder','value',...
   'mirrorIdentityError','endpointError'};
writetable(cell2table(R,'VariableNames',n),...
 fullfile(work,'V34_S7_STABLE_DERIVATIVES_SELF_AUDIT.csv'));
assert(all(isfinite(cell2mat(R(:,4)))) &&...
       all(cell2mat(R(:,6))<1e-12) &&...
       all(cell2mat(R(:,5))<1e-7),...
 'CBF:HLCV34S7Audit','Stable S7 endpoint or mirror identity failure');
end

