fid=fopen(p,'ab');
assert(fid>0,'CBF:HLCV51HistoryOpen','Cannot append original V50 history');
fwrite(fid,bytes,'uint8');
extra=sprintf([ ...
  '\n\n============================================================\n', ...
  'V51 2026-11-17: HLC validity mechanism (thrust and torque, not arbitrary caps)\n', ...
  '============================================================\n', ...
  'V49 actual R1 data: z error -0.00371m, upward speed +0.361m/s at t=2.300; ', ...
  'raw thrust +0.415N, applied thrust +13.502N, body thrust-axis tilt 5.58deg, ', ...
  'cable tilt 4.17deg, raw torque 135.229Nm.\n', ...
  'v1=F11*(zd-z)+F12*(vzd-vz) with F11 about 82.34, F12 about 24.83. ', ...
  'At same state raw-thrust-zero vertical-velocity threshold is approx ', ...
  '+0.383m/s at 2.300 and +0.347m/s at 2.325; measured speeds ', ...
  '+0.361 and +0.489m/s respectively. These are time-varying algebraic ', ...
  'zero-thrust thresholds, NOT allowable speed bounds nor CBF constraints.\n', ...
  'Generated Beta2 depends on V1+target z acceleration+g. In V19 R1 ', ...
  'the beta singular spectrum and Vs/alpha2 vary rapidly as raw thrust ', ...
  'drops. A small condition number does not guarantee adequate absolute ', ...
  'torque authority. At 2.300 sigmaMin about 4.949 and Vs norm about 657.\n', ...
  'V51 retains original 6-derivative reference, original nonlinear plant, ', ...
  'original R1 CBF and HLC with EKF initial mass 0.01kg held; ', ...
  'it is NOT the real live EKF Flight loop.\n', ...
  'V51 outputs exact R1 replay history, matched-state z/vz counterfactuals, ', ...
  'algebraic v1-only authority sweep (higher v1 columns held fixed), ', ...
  'and CURRENT-R1-constrained 25ms nonlinear 4-input one-step tests. ', ...
  'Last two audits are NOT full-time coherent virtual CBF or certified ', ...
  'forward invariant safety control.\n', ...
  'Hypothesis: a small upward velocity can collapse original raw thrust ', ...
  'while required R1 applied thrust remains high, and high-order Vs ', ...
  'couples to reduced effective Beta2 control authority. Measure relative ', ...
  'order of causation, distinguish algebraic from propagated interventions.\n', ...
  'No arbitrary torque upper bound or reference modification added. ', ...
  'Compare nonfinite and inverse degeneracy separately from ordinary ', ...
  'input saturation, cable h, tension, altitude, and trajectory recovery.\n']);
fwrite(fid,unicode2native(extra,'UTF-8'),'uint8');
fclose(fid);
movefile(p,fullfile(work,'CBF_CUMULATIVE_HANDOVER_V51.txt'));
end


% =========================================================================
% V53: original V19 exact R1 with causal HLC TORQUE origin breakdown.
% New controls are DIAGNOSTIC trials only, not certified safety designs.
% Original HLC, R1, plant, sixth-derivative reference are UNCHANGED.
% =========================================================================
function out=v53TorqueOriginSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
    abs(opts.dt-0.025)<1e-12, 'CBF:HLCV53Protocol', ...
    'V53 exact V19 replication requires V11_19/R193/dt=0.025');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,provenance]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(all(isfinite(x0)),'CBF:HLCV53Start','V19 pre-CBF state unavailable');
v23WriteText(fullfile(work,'V53_SOURCE_AND_INITIAL_STATE.txt'),provenance);
s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
modes={'R1_EXACT','EARLY_PITCH_PLUS','EARLY_PITCH_MINUS', ...
       'EARLY_ROLL_PLUS','EARLY_ROLL_MINUS','EARLY_YAW_PLUS', ...
       'EARLY_YAW_MINUS'};
cols={'mode','status','lastTime_s','peakRawThrustAbs_N', ...
      'minimumRawThrust_N','peakAppliedThrust_N','peakRawTauInf_Nm', ...
      'peakAppliedTauInf_Nm','minimumBetaSigma','peakAlphaNorm', ...
      'peakVsNorm','minimumCableH','minimumTension_N', ...
      'firstR1Active_s','numberOfRows','notes'};
rows=cell(numel(modes),numel(cols)); failures=0;runtime=0;r1stop=0;
for j=1:numel(modes)
    mode=modes{j};
    fprintf('[HLC V53] V19 continuous %s\n',mode);
    try
        [tr,meta]=v53Flight(sc,H,opts,x0,mode,s,lo,hi,work);
        writetable(tr,fullfile(work,['V53_CONTINUOUS_' mode '.csv']));
        rows(j,:)={mode,meta.status,meta.tEnd,meta.peakAbsT, ...
            meta.minT,meta.maxAppliedT,meta.maxRawTau,meta.maxAppliedTau, ...
            meta.minSigma,meta.maxAlpha,meta.maxVs,meta.minCableH, ...
            meta.minTension,meta.firstActive,height(tr), ...
            'V19_R1_ORIGINAL_HLC_FIXED_REFERENCE_DIAGNOSTIC_TORQUE_PULSE'};
        if ~strcmp(meta.status,'COMPLETE_DIAGNOSTIC')
            failures=failures+1;
            if strncmp(meta.status,'R1_FILTER_STOP_',15),r1stop=r1stop+1;end
        end
    catch ME
        failures=failures+1;runtime=runtime+1;
        rows(j,:)={mode,['MATLAB_ERROR_' ME.identifier],NaN,NaN,NaN, ...
             NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,0,ME.message};
        v23WriteText(fullfile(work,['V53_ERROR_' mode '.txt']), ...
            getReport(ME,'extended','hyperlinks','off'));
    end
end
writetable(cell2table(rows,'VariableNames',cols), ...
    fullfile(work,'V53_CONTINUOUS_SUMMARY.csv'));
interp=strjoin({ ...
 'V53 is causal analysis, NOT a new CBF or certified stable controller.'; ...
 'V19 original straight_single 6th-derivative reference and actual R1 thrust constraint stay unchanged.'; ...
 'Seven modes share same 2.125-s initial 19-state, mass estimate, R1 recomputation each 25ms.'; ...
 'Early pulses are physical TORQUE offsets, 0.2Nm for 2.150 <=t<2.250 ONLY; physical saturation applied.'; ...
 'R1 may stop if no feasible thrust exists; never equate solver continuation to proven forward safety.'; ...
 'HLC RAW torque is distinct from HLC saturated and physical applied torque.'; ...
 'Original HLC beta and alpha computed at actual state, ORIGINAL nominal v1: not recalculated with applied R1 thrust.'; ...
 'V2/3/4 algebraic linearity audit reconstructs alpha2 using each single Vs component, no physical controller implied.'; ...
 'V1 differential audit perturbs V1(0) only with 5 higher V1 columns FROZEN; not a consistent jet.'; ...
 'For derivative of tau=beta^-1 alpha, dTau=beta^-1(dAlpha-dBeta*tau). Check step convergence and residual.'; ...
 'Local 4input probes simulate one true nonlinear 25ms step with CURRENT original R1 feasible thrust.'; ...
 'No measured new MATLAB results are claimed until executing source on MATLAB.'},newline);
v23WriteText(fullfile(work,'V53_PROTOCOL_AND_LIMITATIONS.txt'),interp);
out=struct('nCases',numel(modes),'nFailedCases',failures, ...
    'nRuntimeErrors',runtime,'nR1FilterStops',r1stop);
end

function [trace,meta]=v53Flight(sc,H,opts,x,mode,s,lo,hi,work)
cols={'time_s','rawThrust_N','baseClippedThrust_N','r1AppliedThrust_N', ...
 'rawMinusAppliedThrust_N','rawTauX_Nm','rawTauY_Nm','rawTauZ_Nm', ...
 'appliedTauX_Nm','appliedTauY_Nm','appliedTauZ_Nm', ...
 'rawTauInf_Nm','appliedTauInf_Nm','vs2','vs3','vs4', ...
 'v1_0','v1_1','v1_2','v1_3','v1_4','v1_5', ...
 'betaSigma1','betaSigma2','betaSigma3','betaCondition', ...
 'alphaNorm','alphaNoVsNorm','alphaVsNorm','rawTauFromVsInf_Nm', ...
 'rawTauNoVsInf_Nm','rawTauFromVs2Inf_Nm','rawTauFromVs3Inf_Nm', ...
 'rawTauFromVs4Inf_Nm','vsDecompositionResidual_Nm', ...
 'torqueChannel1','torqueChannel2','torqueChannel3', ...
 'torqueVsChannel1','torqueVsChannel2','torqueVsChannel3', ...
 'torqueNoVsChannel1','torqueNoVsChannel2','torqueNoVsChannel3', ...
 'alphaProject1','alphaProject2','alphaProject3', ...
 'zError_m','vzError_mps','cableH','tension_N', ...
 'bodyTilt_deg','cableTilt_deg','thrustDenominator', ...
 'r1ConstraintResidual','torqueImpulseAppliedY','inputCorrectionClipped','r1AuditStatus', ...
 'dominantSVDRank','dominantTorqueRightX','dominantTorqueRightY', ...
 'dominantTorqueRightZ','dominantAlphaLeftX','dominantAlphaLeftY', ...
 'dominantAlphaLeftZ','dominantRightOverlapPreviousAbs'};
N=round(opts.v46Duration/opts.dt);t0=2.125;
R=cell(N+1,numel(cols));n=0;
prevDomRight=nan(3,1);
meta=struct('status','COMPLETE_DIAGNOSTIC','tEnd',t0, ...
 'peakAbsT',0,'minT',Inf,'maxAppliedT',0,'maxRawTau',0, ...
 'maxAppliedTau',0,'minSigma',Inf,'maxAlpha',0,'maxVs',0, ...
 'minCableH',Inf,'minTension',Inf,'firstActive',NaN);
for k=0:N
    t=t0+k*opts.dt;
    try
        a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
    catch ME
        meta.status=['HLC_EVALUATION_ERROR_' ME.identifier];meta.tEnd=t;break;
    end
    if any(~isfinite([a.raw;a.alpha(:);a.beta(:)])) || a.betaRcond<1e-14
        meta.status='HLC_NONFINITE_OR_SINGULAR';meta.tEnd=t;break;
    end
    base=min(hi,max(lo,a.raw));
    % V55, diagnostic only: trace per-obstacle thrust bound before R1 may stop.
    % No modification of any candidate control, CBF, plant, or reference.
    if opts.v54CouplingAudit && strcmp(mode,'R1_EXACT') && ...
            t>=2.125-1e-8 && t<=2.375+1e-8
        try
            v55R1IntervalAudit(work,x,t,a,s,sc.obstacles,base);
        catch ME55
            v23WriteText(fullfile(work,sprintf( ...
                'V55_INTERVAL_ERROR_T%04d.txt',round(t*1000))), ...
                getReport(ME55,'extended','hyperlinks','off'));
        end
    end
    [u,msg]=v25R1ExactFilter(x,s,sc.obstacles,base);
    if ~strcmp(msg,'OK')
        meta.status=['R1_FILTER_STOP_' msg];meta.tEnd=t;break;
    end
    [~,res,~,r1status]=v28R1Audit(x,s,sc.obstacles,u(1));
    if res < -1e-7 || ~strcmp(r1status,'OK')
        meta.status='R1_RESIDUAL_FAIL';meta.tEnd=t;break;
    end
    nominal=u;
    if t>=2.15-1e-10 && t<2.25-1e-10
       switch mode
           case 'EARLY_PITCH_PLUS',u(3)=u(3)+.2;
           case 'EARLY_PITCH_MINUS',u(3)=u(3)-.2;
           case 'EARLY_ROLL_PLUS',u(2)=u(2)+.2;
           case 'EARLY_ROLL_MINUS',u(2)=u(2)-.2;
           case 'EARLY_YAW_PLUS',u(4)=u(4)+.2;
           case 'EARLY_YAW_MINUS',u(4)=u(4)-.2;
       end
    end
    preSaturation=u;
    u=min(hi,max(lo,u));
    [U,D,V]=svd(a.beta); sig=diag(D);
    al0=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
       x,a.XD,a.vfRaw,zeros(3,1),a.HLCparam);al0=al0(:);
    tav0=a.beta\al0; tav=a.beta\(a.alpha(:)-al0);
    channels=(U.'*a.alpha(:))./sig;
    channels0=(U.'*al0)./sig;
    [~,domRank]=max(abs(channels));
    if all(isfinite(prevDomRight))
        domOverlap=abs(dot(prevDomRight,V(:,domRank)));
    else
        domOverlap=NaN;
    end
    prevDomRight=V(:,domRank);
    channelsv=(U.'*(a.alpha(:)-al0))./sig;
    components=zeros(3,3);linearPart=zeros(3,1);
    for i=1:3
        vsOne=zeros(3,1);vsOne(i)=a.vsRaw(i);
        aOne=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
            x,a.XD,a.vfRaw,vsOne,a.HLCparam);
        components(:,i)=a.beta\(aOne(:)-al0);
    end
    linearPart=sum(components,2);
    torErr=norm(tav-linearPart,Inf);
    h=v23CableSafety(x,sc);ten=v23Tension(x,s,u(1));
    ez=a.XD(3)-x(10);ev=a.XD(7)-x(13);
    r={t,a.raw(1),base(1),u(1),u(1)-a.raw(1), ...
        a.tau(1),a.tau(2),a.tau(3),u(2),u(3),u(4), ...
        norm(a.tau,Inf),norm(u(2:4),Inf), ...
        a.vsRaw(1),a.vsRaw(2),a.vsRaw(3), ...
        a.vfRaw(1),a.vfRaw(2),a.vfRaw(3),a.vfRaw(4), ...
        a.vfRaw(5),a.vfRaw(6), ...
        sig(1),sig(2),sig(3),sig(1)/sig(3), ...
        a.alphaNorm,norm(al0),norm(a.alpha(:)-al0), ...
        norm(tav,Inf),norm(tav0,Inf), ...
        norm(components(:,1),Inf),norm(components(:,2),Inf), ...
        norm(components(:,3),Inf),torErr, ...
        channels(1),channels(2),channels(3), ...
        channelsv(1),channelsv(2),channelsv(3), ...
        channels0(1),channels0(2),channels0(3), ...
        U(:,1).'*a.alpha(:),U(:,2).'*a.alpha(:),U(:,3).'*a.alpha(:), ...
        ez,ev,h,ten,aBodyTilt(x),a.cableTilt*180/pi, ...
        a.thrustDenominator,res,u(3)-nominal(3), ...
        norm(u-preSaturation,Inf),r1status,domRank, ...
        V(1,domRank),V(2,domRank),V(3,domRank), ...
        U(1,domRank),U(2,domRank),U(3,domRank),domOverlap};
    assert(numel(r)==numel(cols),'CBF:HLCV53TraceWidth');
    n=n+1;R(n,:)=r;
    meta.tEnd=t;
    meta.peakAbsT=max(meta.peakAbsT,abs(a.raw(1)));
    meta.minT=min(meta.minT,a.raw(1));
    meta.maxAppliedT=max(meta.maxAppliedT,u(1));
    meta.maxRawTau=max(meta.maxRawTau,norm(a.tau,Inf));
    meta.maxAppliedTau=max(meta.maxAppliedTau,norm(u(2:4),Inf));
    meta.minSigma=min(meta.minSigma,sig(3));
    meta.maxAlpha=max(meta.maxAlpha,a.alphaNorm);
    meta.maxVs=max(meta.maxVs,a.vsNorm);
    meta.minCableH=min(meta.minCableH,h);
    meta.minTension=min(meta.minTension,ten);
    if isnan(meta.firstActive) && abs(u(1)-base(1))>1e-8
        meta.firstActive=t;
    end
    if strcmp(mode,'R1_EXACT') && any(abs(t-[2.15 2.225 2.275 2.3 2.325])<1e-7)
        v53AlgebraicV1Audit(work,x,t,a,H);
        v53OneStepTorqueAudit(work,x,t,u,sc,H,opts,s,lo,hi);
        if opts.v54CouplingAudit
            try
                v54PhysicalMapAudit(work,x,t,a,u,H);
            catch ME54map
                v23WriteText(fullfile(work,sprintf( ...
                    'V54_MAP_ERROR_T%04d.txt',round(t*1000))), ...
                    getReport(ME54map,'extended','hyperlinks','off'));
            end
            try
                v54NextR1Feasibility(work,x,t,u,sc,H,opts,s,lo,hi);
            catch ME54next
                v23WriteText(fullfile(work,sprintf( ...
                    'V54_FUTURE_ERROR_T%04d.txt',round(t*1000))), ...
                    getReport(ME54next,'extended','hyperlinks','off'));
            end
        end
    end
    if k==N,break;end
    if ten<=0,meta.status='TENSION_NONPOSITIVE';break;end
    x=v25StepOnce(x,u,s,opts);
    if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
       abs(norm(x(14:16))-1)>1e-3
       meta.status='PLANT_NONFINITE_OR_MANIFOLD_FAIL';break;
    end
end
trace=cell2table(R(1:n,:),'VariableNames',cols);
end

function v53AlgebraicV1Audit(work,x,t,a,H)
% Fixed state, original reference, ONLY V1(0) changed. Higher 5 held fixed.
cols={'time_s','deltaV1','v1Original','rawThrustPerturbed_N', ...
    'tauFullX','tauFullY','tauFullZ','tauAlphaOnlyX', ...
    'tauAlphaOnlyY','tauAlphaOnlyZ','tauBetaOnlyX', ...
    'tauBetaOnlyY','tauBetaOnlyZ','tauOriginalX', ...
    'tauOriginalY','tauOriginalZ','sigmaMinBetaPerturbed', ...
    'alphaNormPerturbed','dAlphaNorm','dBetaNorm', ...
    'betaPartInf_Nm','alphaPartInf_Nm','fullDeltaInf_Nm', ...
    'decompositionCrossInf_Nm','status'};
R=cell(0,numel(cols));
for d=[-.5 -.2 -.05 -.01 .01 .05 .2 .5]
   vf=a.vfRaw;vf(1)=vf(1)+d;
   try
     uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
     bb=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
     vv=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam, ...
         H.F2,H.F3,H.F4);
     al=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
         x,a.XD,vf,vv(:),a.HLCparam);al=al(:);
     sig=svd(bb); ok=rcond(bb)>1e-14 && ...
          all(isfinite([bb(:);al(:)]));
     if ok
        full=bb\al;
        onlyAlpha=a.beta\al;
        onlyBeta=bb\a.alpha(:);
        % Finite delta = alpha-at-fixed-beta + beta-at-fixed-alpha
        % plus cross interaction (NOT assumed negligible near degeneracy).
        cross=full-a.tau-(onlyAlpha-a.tau)-(onlyBeta-a.tau);
        status='FINITE_ALGEBRAIC_AUDIT';
     else
        full=nan(3,1);onlyAlpha=full;onlyBeta=full;
        cross=full;status='BETA_NONINVERTIBLE';
     end
     rr={t,d,a.vfRaw(1),uf(1),full(1),full(2),full(3), ...
      onlyAlpha(1),onlyAlpha(2),onlyAlpha(3), ...
      onlyBeta(1),onlyBeta(2),onlyBeta(3), ...
      a.tau(1),a.tau(2),a.tau(3),min(sig),norm(al), ...
      norm(al-a.alpha(:)),norm(bb-a.beta,'fro'), ...
      norm(onlyBeta-a.tau,Inf),norm(onlyAlpha-a.tau,Inf), ...
      norm(full-a.tau,Inf),norm(cross,Inf),status};
   catch ME
     rr=cell(1,numel(cols));rr(:)={NaN};
     rr{1}=t;rr{2}=d;rr{end}=['EVALUATION_ERROR_' ME.identifier];
   end
   assert(numel(rr)==numel(cols),'CBF:HLCV53V1RowWidth');
   R(end+1,:)=rr; %#ok<AGROW>
end
writetable(cell2table(R,'VariableNames',cols), ...
    fullfile(work,sprintf('V53_V1_FIXED_STATE_T%04d.csv',round(t*1000))));
% Differential identity: dTau/dv1 = B^-1 [dAlpha/dv1 - dB/dv1*tau]
cols2={'time_s','finiteDiffStep','betaDerivativeNorm', ...
 'alphaDerivativeNorm','tauDerivativeAlphaPartInf', ...
 'tauDerivativeBetaPartInf','tauDerivativeTotalInf', ...
 'finiteDifferenceTauDerivativeInf','derivativeReconstructionErrorInf', ...
 'tauDerivativeAlphaX','tauDerivativeAlphaY','tauDerivativeAlphaZ', ...
 'tauDerivativeBetaX','tauDerivativeBetaY','tauDerivativeBetaZ','status'};
rrs=cell(0,numel(cols2));
for h=[0.02,0.01,0.005,0.001]
 try
    bpair=cell(1,2);apair=cell(1,2);tpair=cell(1,2);
    for j=1:2
       vf=a.vfRaw;vf(1)=vf(1)+(2*j-3)*h;
       b=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
       vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf, ...
                             a.HLCparam,H.F2,H.F3,H.F4);
       al=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
                             x,a.XD,vf,vs(:),a.HLCparam);
       assert(all(isfinite([b(:);al(:)])) && rcond(b)>1e-12, ...
                          'CBF:HLCV53DiffSingularity');
       bpair{j}=b;apair{j}=al(:);tpair{j}=b\al(:);
    end
    db=(bpair{2}-bpair{1})/(2*h);
    da=(apair{2}-apair{1})/(2*h);
    partA=a.beta\da;
    partB=-a.beta\(db*a.tau);
    df=(tpair{2}-tpair{1})/(2*h);
    r={t,h,norm(db,'fro'),norm(da),norm(partA,Inf), ...
       norm(partB,Inf),norm(partA+partB,Inf),norm(df,Inf), ...
       norm(partA+partB-df,Inf), ...
       partA(1),partA(2),partA(3),partB(1),partB(2),partB(3), ...
       'FINITE_ALGEBRAIC_DERIVATIVE'};
 catch ME
    r=cell(1,numel(cols2));r(:)={NaN};
    r{1}=t;r{2}=h;r{end}=['FAILED_' ME.identifier];
 end
 assert(numel(r)==numel(cols2),'CBF:HLCV53DiffRowWidth');
 rrs(end+1,:)=r; %#ok<AGROW>
end
writetable(cell2table(rrs,'VariableNames',cols2), ...
    fullfile(work,sprintf('V53_DTAU_DV1_T%04d.csv',round(t*1000))));
end

function v53OneStepTorqueAudit(work,x,t,u,sc,H,opts,s,lo,hi)
cols={'time_s','variant','actualDeltaThrust_N', ...
      'actualDeltaTauX_Nm','actualDeltaTauY_Nm', ...
      'actualDeltaTauZ_Nm','cbfResidual','cbfStatus', ...
      'nextRawThrust_N','nextRawTauX_Nm','nextRawTauY_Nm', ...
      'nextRawTauZ_Nm','nextRawTauInf_Nm','nextVsNorm', ...
      'nextAlphaNorm','nextBetaSigmaMin','nextVz_mps', ...
      'nextCableH','nextTension_N','status'};
rows=cell(0,numel(cols));
tests={'R1_ORIGINAL',zeros(4,1); ...
       'T_PLUS_05',[0.5;0;0;0]; ...
       'T_MINUS_05',[-0.5;0;0;0]; ...
       'ROLL_PLUS_02',[0;.2;0;0]; ...
       'ROLL_MINUS_02',[0;-.2;0;0]; ...
       'PITCH_PLUS_02',[0;0;.2;0]; ...
       'PITCH_MINUS_02',[0;0;-.2;0]; ...
       'YAW_PLUS_02',[0;0;0;.2]; ...
       'YAW_MINUS_02',[0;0;0;-.2]};
for j=1:size(tests,1)
   candidate=min(hi,max(lo,u+tests{j,2}));
   [~,res,~,audit]=v28R1Audit(x,s,sc.obstacles,candidate(1));
   status='25MS_CAUSAL_PREDICTION_ONLY';
   nx=NaN; y=nan(3,1); rawtau=NaN;
   ns=NaN; na=NaN; bs=NaN;nvz=NaN;nh=NaN;nt=NaN;
   try
      xp=v25StepOnce(x,candidate,s,opts);
      a2=v23HLC(xp,t+opts.dt,sc,H, ...
                         v23EstimatedMass(opts,t+opts.dt));
      nx=a2.raw(1);y=a2.tau(:);rawtau=norm(y,Inf);
      ns=a2.vsNorm;na=a2.alphaNorm;bs=a2.sigmaMin;
      nvz=xp(13);nh=v23CableSafety(xp,sc);
      nt=v23Tension(xp,s,candidate(1));
   catch ME
      status=['PREDICTION_FAILED_' ME.identifier];
   end
   if res < -1e-7 || ~strcmp(audit,'OK')
      status=['CURRENT_R1_VIOLATED_' status];
   end
   vals={t,tests{j,1},candidate(1)-u(1), ...
       candidate(2)-u(2),candidate(3)-u(3),candidate(4)-u(4), ...
       res,audit,nx,y(1),y(2),y(3),rawtau,ns,na,bs,nvz,nh,nt,status};
   assert(numel(vals)==numel(cols),'CBF:HLCV53OneStepWidth');
   rows(end+1,:)=vals; %#ok<AGROW>
end
writetable(cell2table(rows,'VariableNames',cols), ...
    fullfile(work,sprintf('V53_ONE_STEP_4U_T%04d.csv',round(t*1000))));
end

