assert(fid>0,'CBF:HLCV53HistoryWrite');
fwrite(fid,bytes,'uint8');
extra=sprintf([ ...
 '\n\n============================================================\n', ...
 'V53: original HLC torque amplification (2026-11-17)\n', ...
 '============================================================\n', ...
 'V51/V52 measured t=2.275 to 2.300: raw tau max 1.6795 to 135.2294 Nm; ', ...
 'active alpha projection -389.605 to -669.215, active beta singular ', ...
 '231.974 to 4.949; ratio about 80.5. SVD rank indices switch; track ', ...
 'projected active channel instead of only sigmaMin or cond.\n', ...
 'V53 mode: seven original-V19 R1 nonlinear continuous closures, ', ...
 'torque-only +/-0.2 Nm 0.100s early diagnostic pulses on three axes ', ...
 't=2.150...2.225; thrust determined by ORIGINAL R1 every sample. ', ...
 'Existing HLC/Vfd/Vs/Uf/Beta2/V2_alpha2 untouched.\n', ...
 'V53 decomposes HLC raw tau with singular value channels, ', ...
 'V2_alpha2 at Vs=0 and each of its 3 isolated components. ', ...
 'Checks reconstruction residual to detect nonlinear in Vs.\n', ...
 'At SAME physical state changes only v1(0), freezes higher columns; ', ...
 'evaluate alpha-only/beta-only/full changes and interaction, plus ', ...
 'central difference tau derivative identity beta^-1*(dAlpha-dBeta*tau). ', ...
 'These are algebraic counterfactuals, not physical admissible virtual inputs.\n', ...
 'One-step 4U causal branches maintain original current R1 thrust audit ', ...
 'and physical input limits, but are not guaranteed future-safe. ', ...
 'Raw HLC thrust, actual thrust, 3 raw torques, 3 actual torques, ', ...
 'cable H, tension and next 25ms HLC demand recorded.\n', ...
 'NO claim of controller improvement until MATLAB runs and proves ', ...
 'sustained behavior. R1 original uses V11_19 19-state plant; ', ...
 '0.01kg fixed initial EKF mass estimate, NOT live EKF. ', ...
 'No obstacle CBF redesign, reference change, or hardware validation.\n']);
fwrite(fid,unicode2native(extra,'UTF-8'),'uint8');
fclose(fid);
movefile(p,fullfile(work,'CBF_CUMULATIVE_HANDOVER_V53.txt'));
end


% =========================================================================
% V54: EXACT actual-R1-thrust vs original nominal-HLC mapping, and next-R1
% feasibility of causal physical-input probes. Algebraic remapping is NEVER
% inserted into the plant.  It freezes Vfd columns 2..6 and therefore is
% explicitly NOT a time-consistent higher-order virtual controller.
% =========================================================================
function v54PhysicalMapAudit(work,x,t,a,u,H)
cols={'time_s','rawNominalThrust_N','actualR1Thrust_N', ...
 'actualMinusNominal_N','thrustDenominator', ...
 'nominalV1','algebraicEquivalentV1', ...
 'equivalentThrustReconstruction_N','thrustReconstructionResidual_N', ...
 'nativeSigmaMin','equivalentSigmaMin','nativeRawTauInf_Nm', ...
 'equivalentRawTauX_Nm','equivalentRawTauY_Nm', ...
 'equivalentRawTauZ_Nm','equivalentRawTauInf_Nm', ...
 'nativeVsNorm','equivalentVsNorm','nativeAlphaNorm', ...
 'equivalentAlphaNorm','vfHigherSlotsFrozen','status'};
mm=a.HLCparam(1)+a.HLCparam(6);
assert(mm>0 && isfinite(mm) && isfinite(a.thrustDenominator), ...
       'CBF:HLCV54MassAndDenominator');
dv=(u(1)-a.raw(1))*a.thrustDenominator/mm;
vfEq=a.vfRaw;vfEq(1)=vfEq(1)+dv;
tauEq=nan(3,1);tauEqInf=NaN;betaSig=NaN;eqAlphaNorm=NaN;
eqVsNorm=NaN;ufReconstruction=NaN;status='OK_ALGEBRAIC_ONLY';
try
    uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vfEq,a.HLCparam);
    ufReconstruction=uf(1);
    if abs(ufReconstruction-u(1))>1e-8*max(1,abs(u(1)))
        status='THRUST_RECONSTRUCTION_MISMATCH';
    end
    be=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vfEq,a.HLCparam);
    sv=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vfEq, ...
          a.HLCparam,H.F2,H.F3,H.F4);
    ae=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vfEq, ...
          sv(:),a.HLCparam);
    betaSig=min(svd(be));eqAlphaNorm=norm(ae(:));eqVsNorm=norm(sv(:));
    if all(isfinite([be(:);ae(:);ufReconstruction])) && rcond(be)>1e-14
        tauEq=be\ae(:);tauEqInf=norm(tauEq,Inf);
    else
        status='ALTERNATE_BETA_SINGULAR_OR_NONFINITE';
    end
catch ME
    status=['ALGEBRAIC_EVALUATION_FAILED_' ME.identifier];
end
r={t,a.raw(1),u(1),u(1)-a.raw(1),a.thrustDenominator, ...
 a.vfRaw(1),vfEq(1),ufReconstruction,ufReconstruction-u(1), ...
 a.sigmaMin,betaSig,norm(a.tau,Inf), ...
 tauEq(1),tauEq(2),tauEq(3),tauEqInf, ...
 a.vsNorm,eqVsNorm,a.alphaNorm,eqAlphaNorm,true,status};
assert(numel(r)==numel(cols),'CBF:HLCV54MapWidth');
writetable(cell2table(r,'VariableNames',cols), ...
 fullfile(work,sprintf('V54_NOMINAL_VS_ACTUAL_THRUST_MAP_T%04d.csv',round(t*1000))));
end

function v54NextR1Feasibility(work,x,t,u,sc,H,opts,s,lo,hi)
% Same physical state, original target and original R1 constraint; predict
% true physical plant one 25ms then compute both HLC & next-cycle R1.
cols={'time_s','variant','deltaT_actual_N','deltaRoll_actual_Nm', ...
 'deltaPitch_actual_Nm','deltaYaw_actual_Nm','currentR1Residual', ...
 'currentR1AuditStatus','nextRawThrust_N','nextRawTauInf_Nm', ...
 'nextBetaSigmaMin','nextVerticalVelocity_mps','nextCableH', ...
 'nextTensionCurrentInput_N','nextR1Status', ...
 'nextR1RequestedThrust_N','nextR1DeltaFromRaw_N', ...
 'nextR1Residual','nextR1Tension_N','status'};
tests={'R1_ORIGINAL',zeros(4,1);'T_PLUS_05',[.5;0;0;0]; ...
 'T_MINUS_05',[-.5;0;0;0];'ROLL_PLUS_02',[0;.2;0;0]; ...
 'ROLL_MINUS_02',[0;-.2;0;0];'PITCH_PLUS_02',[0;0;.2;0]; ...
 'PITCH_MINUS_02',[0;0;-.2;0];'YAW_PLUS_02',[0;0;0;.2]; ...
 'YAW_MINUS_02',[0;0;0;-.2]};
rows=cell(size(tests,1),numel(cols));
for j=1:size(tests,1)
    up=min(hi,max(lo,u+tests{j,2}));
    [~,cr,~,cs]=v28R1Audit(x,s,sc.obstacles,up(1));
    status='25MS_BRANCH_NOT_CLOSED_LOOP';nextStatus='NOT_EVALUATED';
    nextRawT=NaN;nextRawTau=NaN;nextSigma=NaN;
    nextVz=NaN;nextH=NaN;nextTen=NaN;nextReqT=NaN;
    nextDeltaT=NaN;nextResidual=NaN;nextAppliedTen=NaN;
    try
       xp=v25StepOnce(x,up,s,opts);
       a2=v23HLC(xp,t+opts.dt,sc,H, ...
            v23EstimatedMass(opts,t+opts.dt));
       nextRawT=a2.raw(1);nextRawTau=norm(a2.tau,Inf);
       nextSigma=a2.sigmaMin;nextVz=xp(13);
       nextH=v23CableSafety(xp,sc);nextTen=v23Tension(xp,s,up(1));
       nextBase=min(hi,max(lo,a2.raw));
       [unext,nextStatus]=v25R1ExactFilter(xp,s,sc.obstacles,nextBase);
       if strcmp(nextStatus,'OK')
           nextReqT=unext(1);nextDeltaT=unext(1)-a2.raw(1);
           [~,nextResidual,~,aud]=v28R1Audit( ...
                xp,s,sc.obstacles,unext(1));
           nextAppliedTen=v23Tension(xp,s,unext(1));
           if ~strcmp(aud,'OK') || nextResidual < -1e-7
               nextStatus=['AUDIT_FAIL_' aud];
           end
       end
    catch ME
       status=['PREDICTION_FAILED_' ME.identifier];
    end
    if cr < -1e-7 || ~strcmp(cs,'OK')
       status=['CURRENT_R1_VIOLATED_' status];
    end
    rr={t,tests{j,1},up(1)-u(1),up(2)-u(2),up(3)-u(3), ...
        up(4)-u(4),cr,cs,nextRawT,nextRawTau,nextSigma,nextVz, ...
        nextH,nextTen,nextStatus,nextReqT,nextDeltaT, ...
        nextResidual,nextAppliedTen,status};
    assert(numel(rr)==numel(cols),'CBF:HLCV54NextRowWidth');
    rows(j,:)=rr;
end
writetable(cell2table(rows,'VariableNames',cols), ...
 fullfile(work,sprintf('V54_NEXT_R1_FEASIBILITY_T%04d.csv',round(t*1000))));
end

function v54WriteHandover(work,root,opts)
v53WriteHandover(work,root,opts);
p=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V53.txt');
fid=fopen(p,'ab');assert(fid>0,'CBF:HLCV54HandoverWrite');
extra=sprintf([ ...
 '\n\n============================================================\n', ...
 'V54: source-supported V53 RESULT REVIEW + next-step feasibility ', ...
 'and actual-thrust mapping audits (2026-11-17)\n', ...
 '============================================================\n', ...
 'V53 seven modes all stop on original R1 infeasible-shared-thrust: ', ...
 'R1_EXACT at 2.350s; early pitch minus at 2.375s but minimum ', ...
 'tension 0.0001019N and applied thrust 0N at t=2.325s. ', ...
 'Early pitch +0.2 reduces peak raw torque 135.23 to 49.98 Nm ', ...
 'but decreases min nominal thrust -2.72 to -4.70 N and ', ...
 'increases applied thrust peak 16.45 to 19.39N; no success. ', ...
 'Early pitch -0.2 lowers peak raw torque to 23.60Nm but ', ...
 'does NOT preserve positive cable tension or R1 feasibility.\n', ...
 'At t=2.300, exact R1: v1=-9.2710; Traw=.41539N; ', ...
 'Tactual=13.50173N; Vs2=657.373; ', ...
 'tau raw pitch=135.229Nm, beta sigmaMin=4.94874; ', ...
 'body tilt about 5.58deg. No 10m position deviation.\n', ...
 'Fixed-state algebraic v1 sensitivity dTauY/dv1 about -514.837 ', ...
 'Nm/(m/s^2), decomposed alpha contribution -11.87095 and ', ...
 'beta contribution -502.9661; derivative central difference at ', ...
 'h=.001 agrees within .0036. The large CURRENT tau (135.229) ', ...
 'is mostly Vs-related (132.8365), whereas sensitivity to v1 ', ...
 'is mostly beta-related. Do not conflate.\n', ...
 'At t=2.275 candidate T+0.5N respects CURRENT R1 and predicts ', ...
 'Traw_next=.13863N, betaSigmaMin_next=.55631, raw ', ...
 'pitch tau_next=1247.78Nm; T-0.5N predicts next ', ...
 'raw pitch tau=46.72Nm but VIOLATES current R1 inequality. ', ...
 'This proves CURRENT R1 feasibility alone does not preserve ', ...
 'HLC inversion authority one step later.\n', ...
 'V54 NEW MATLAB audits only when opts.v54CouplingAudit=true ', ...
 '(implicitly enables V53): same-state replace ONLY v1(0) ', ...
 'to obtain EXACT applied R1 thrust by algebraic linear Uf ', ...
 'mapping, and recompute Beta2/Vs/alpha2 while holding ', ...
 'higher v1 jet columns frozen. This is NOT a realizable or ', ...
 'time-consistent controller, only a diagnostic to distinguish ', ...
 'nominal vs applied input maps. Also test next R1 feasibility ', ...
 'after each ORIGINAL-plant 25ms physical input branch. ', ...
 'No CBF, HLC, obstacle, reference, parameter, plant changes. ', ...
 'V54 MATLAB EXECUTION NOT YET VERIFIED.\n']);
fwrite(fid,unicode2native(extra,'UTF-8'),'uint8');fclose(fid);
movefile(p,fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt'));
end


% =========================================================================
% V55 per-obstacle, per-timestep exact current R1 thrust interval audit.
% Run only in V54 mode, diagnostic only. Includes 2.350 STOP state.
% Outputs one CSV for each time, including zero-input/invalid flags.
% Does not enforce additional constraints or change physical applied input.
% =========================================================================
function v55R1IntervalAudit(work,x,t,a,s,obs,base,outName)
cols={'time_s','obstacleIndex','hRectified','rectifiedCoefficient', ...
 'rectifiedRHS','nonAffineH2','earlyTorqueEffect','boundKind', ...
 'rowThrustBoundary_N','cumulativeLower_N','cumulativeUpper_N', ...
 'activeLowerObstacle','activeUpperObstacle','physicalTmin_N','physicalTmax_N', ...
 'rawHLCThrust_N','clippedHLCThrust_N','intervalGapLowerMinusUpper_N', ...
 'status'};
lo=s.input.thrustMin; hi=s.input.thrustMax;
loID=0; hiID=0;
rows=cell(numel(obs)+1,numel(cols));
for jj=1:numel(obs)
    kind='NO_BOUND'; bnd=NaN; note='OK';
    hr=NaN; A=NaN; rhs=NaN; nonaff=NaN; early=NaN;
    try
        z=CBF_V18_R1_RectifiedCable(x,s,obs{jj});
        hr=z.hR; A=z.rectifiedCoefficient;
        rhs=z.rectifiedRHS; nonaff=z.nonAffineH2;
        early=z.earlyTorqueEffect;
        if hr < -1e-9, note='INITIAL_RECTIFIED_SET_INVALID';end
        if nonaff>1e-7 || early>1e-8
            note='NONAFFINE_OR_EARLY_TORQUE';
        end
        if abs(A)<1e-10
            kind='ZERO_INPUT';
            if rhs>1e-9,note='ZERO_INPUT_AUTHORITY_POSITIVE_RHS';end
        elseif A>0
            kind='LOWER';bnd=rhs/A;
            if bnd>lo,lo=bnd;loID=jj;end
        else
            kind='UPPER';bnd=rhs/A;
            if bnd<hi,hi=bnd;hiID=jj;end
        end
        if lo>hi+1e-8
            note='INFEASIBLE_SHARED_THRUST';
        end
    catch ME
        kind='EVAL_ERROR'; note=['CBF_EVAL_ERROR_' ME.identifier];
    end
    rows(jj,:)={t,jj,hr,A,rhs,nonaff,early,kind,bnd,lo,hi, ...
        loID,hiID,s.input.thrustMin,s.input.thrustMax, ...
        a.raw(1),base(1),lo-hi,note};
end
% Reconfirm the original R1 algorithm's authoritative outcome.
[~,reason]=v25R1ExactFilter(x,s,obs,base);
rows(end,:)={t,0,NaN,NaN,NaN,NaN,NaN,'ALL_ROWS',NaN, ...
    lo,hi,loID,hiID,s.input.thrustMin,s.input.thrustMax, ...
    a.raw(1),base(1),lo-hi,reason};
if nargin<8 || isempty(outName)
    outName=sprintf('V55_R1_INTERVAL_T%04d.csv',round(t*1000));
end
writetable(cell2table(rows,'VariableNames',cols),fullfile(work,outName));
end


% =======================================================================
% V56: ORIGINAL HLC vs R1 after an independently specified DESCENDING goal.
% Comparison is causal diagnostic ONLY. Never replace HLC/CBF/physical laws.
% An authentic user-supplied saddle source is optional. No synthetic
% trajectory can be relabeled as the user's actual saddle trajectory.
% =======================================================================
function out=v56DownwardAndSaddleSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193'), ...
    'CBF:HLCV56Source','Requires R193 19-state plant');
assert(exist('gen_ref_line','file')==2 && ...
    exist('gen_ref_for_rigid_body','file')==2, ...
    'CBF:HLCV56ReferenceMissing', ...
    'The actual R193 gen_ref_line and gen_ref_for_rigid_body are required');
source=gen_ref_line('p0',[0,0,3],'velocity',1.5, ...
    'direction',[0,1,0]);
generated=gen_ref_for_rigid_body(source,6);
assert(isstruct(generated) && isfield(generated,'pYaw') && ...
    isa(generated.pYaw,'function_handle') && isfield(generated,'order') && ...
    generated.order>=6,'CBF:HLCV56FlightJet', ...
    'Original R193 sixth-derivative reference is unavailable');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
L=sc.settings.physical.cableLength;
base=@(t)v32FlightLoadJet(generated.pYaw,t,L);
sc.refFull=base;sc.ref=@(t,k)v32XYZJet(base,t,k);
sc.x0=v56MatchedInitialState(sc.x0,base(0));
% Use the same flight-path-relative fixed ellipsoid as V32, rather than
% silently reusing V19's obstacle placed along a different reference path.
p0=base(0);ob=struct();ob.type='ellipsoid';
ob.center=[p0(1)+.28;p0(2)+2.5;p0(3)+L/2];
ob.axes=[.28;.36;.55];angle=pi/5;
ob.R=[cos(angle) -sin(angle) 0;sin(angle) cos(angle) 0;0 0 1];
sc.obstacles={ob};
assert(v23CableSafety(sc.x0,sc)>0, ...
    'CBF:HLCV56InitialGeometry','Initial flight geometry is unsafe');
v56AuditJet(base,0,opts.v56Duration,'STRAIGHT_ORIGINAL');
% Cases from a single identical physical initial state. STATIC offsets are
% present at t=0 (no discontinuous high-order reference derivatives),
% while SMOOTH offsets use the analytically differentiated S7(t) 0..6 jet.
% R1 uses the same V32 flight-path-relative geometry for every V56 pair.
caseNames={'B00_BASE_NOMINAL','B01_BASE_R1'};
refs={base,base};modes={'NOMINAL','R1_EXACT'};
drops=[0 0];kinds={'ORIGINAL','ORIGINAL'};
for ii=1:numel(opts.v56DropAmounts)
    d=opts.v56DropAmounts(ii);
    rstatic=@(t)v56ShiftJet(base,t,d,'STATIC',opts);
    rsmooth=@(t)v56ShiftJet(base,t,d,'SMOOTH',opts);
    caseNames{end+1}=sprintf('D%02d_STATIC_NOMINAL',ii);
    refs{end+1}=rstatic;modes{end+1}='NOMINAL';
    kinds{end+1}='STATIC';drops(end+1)=d;
    caseNames{end+1}=sprintf('D%02d_STATIC_R1',ii);
    refs{end+1}=rstatic;modes{end+1}='R1_EXACT';
    kinds{end+1}='STATIC';drops(end+1)=d;
    caseNames{end+1}=sprintf('D%02d_SMOOTH_NOMINAL',ii);
    refs{end+1}=rsmooth;modes{end+1}='NOMINAL';
    kinds{end+1}='SMOOTH';drops(end+1)=d;
    caseNames{end+1}=sprintf('D%02d_SMOOTH_R1',ii);
    refs{end+1}=rsmooth;modes{end+1}='R1_EXACT';
    kinds{end+1}='SMOOTH';drops(end+1)=d;
end
% Saddle is supplied in *payload* 28-element [x,y,z,yaw] 0..6 layout,
% or drone location with explicit v56SaddleIsDronePosition=true. The
% original generator itself is NOT included in uploaded R193 archive.
hasSaddle=~isempty(opts.v56SaddleJet);
if hasSaddle
    assert(isa(opts.v56SaddleJet,'function_handle'), ...
        'CBF:HLCV56SaddleHandle','v56SaddleJet must be a function handle');
    saddle=@(t)v56AuthenticSaddleJet(opts.v56SaddleJet,t,L, ...
        opts.v56SaddleIsDronePosition);
    v56AuditJet(saddle,0,opts.v56Duration,'EXTERNAL_AUTHENTIC_SADDLE');
    caseNames(end+1:end+2)={'S00_SADDLE_NOMINAL','S01_SADDLE_R1'};
    refs(end+1:end+2)={saddle,saddle};
    modes(end+1:end+2)={'NOMINAL','R1_EXACT'};
    kinds(end+1:end+2)={'SADDLE_EXTERNAL','SADDLE_EXTERNAL'};
    drops(end+1:end+2)=[0 0];
end
cols={'caseID','refType','descent_m','mode','status','lastTime_s', ...
    'numberOfSamples','minimumRawThrust_N','maximumRawThrust_N', ...
    'maximumRawTorqueInf_Nm','maximumAppliedTorqueInf_Nm', ...
    'maximumRawToAppliedThrust_N','maximumLoadZErrorAbs_m', ...
    'startLoadZ_m','endLoadZ_m','startTargetZ_m','endTargetZ_m', ...
    'minimumLoadZ_m','minimumDroneZ_m','minimumTension_N', ...
    'minimumBetaSigma','firstRawThrustNegative_s', ...
    'firstTorqueAboveLimit_s','firstR1ChangedThrust_s', ...
    'numberTorqueClipped','numberThrustClipped','minimumCableH', ...
    'saddleSource','runtimeError'};
row=cell(numel(caseNames),numel(cols));bad=0;nruntime=0;r1stops=0;
for ii=1:numel(caseNames)
    id=caseNames{ii};c=sc;
    c.refFull=refs{ii};c.ref=@(t,k)v32XYZJet(c.refFull,t,k);
    if strcmp(kinds{ii},'SADDLE_EXTERNAL')
        if isempty(opts.v56SaddleInitialState19)
            c.x0=v56MatchedInitialState(sc.x0,c.refFull(0));
        else
            x=double(opts.v56SaddleInitialState19(:));
            assert(numel(x)==19 && all(isfinite(x)), ...
                'CBF:HLCV56SaddleState','Saddle 19-state snapshot required');
            c.x0=x;
        end
    end
    try
        fprintf('[HLC V56] %s %s down=%g m\n', ...
            id,modes{ii},drops(ii));
        [trace,info]=v56RunOne(c,opts,modes{ii},id,work);
        writetable(trace,fullfile(work,['V56_TRACE_' id '.csv']));
        row(ii,:)=v56SummaryRow(id,kinds{ii},drops(ii),modes{ii}, ...
             trace,info,hasSaddle);
        if ~strcmp(info.status,'COMPLETE_DIAGNOSTIC')
            bad=bad+1;
            if startsWith(info.status,'R1_FILTER_STOP_'),r1stops=r1stops+1;end
        end
    catch ME
        bad=bad+1;nruntime=nruntime+1;
        row(ii,:)={id,kinds{ii},drops(ii),modes{ii}, ...
            ['MATLAB_ERROR_' ME.identifier],nan,0, ...
            nan,nan,nan,nan,nan,nan,nan,nan,nan,nan,nan, ...
            nan,nan,nan,nan,nan,nan,0,0,nan, ...
            v56SaddleSourceLabel(hasSaddle),ME.message};
        v23WriteText(fullfile(work,['V56_ERROR_' id '.txt']), ...
            getReport(ME,'extended','hyperlinks','off'));
    end
end
writetable(cell2table(row,'VariableNames',cols), ...
    fullfile(work,'V56_DOWNWARD_SADDLE_SUMMARY.csv'));
out=struct('nCases',numel(caseNames),'nFailedCases',bad, ...
    'nRuntimeErrors',nruntime,'nR1FilterStops',r1stops);
end

function x=v56MatchedInitialState(x,jet0)
% The same mathematical flight-phase initializer as V32, not an R193
% takeoff/EKF snapshot. Used only to compare a reference change fairly.
r=jet0(:);
assert(numel(r)==28 && all(isfinite(r)),'CBF:HLCV56InitJet');
x=x(:);
x(8:10)=r(1:3);x(11:13)=r(5:7);
x(1:4)=[cos(r(4)/2);0;0;sin(r(4)/2)];
x(14:16)=[0;0;-1];x(17:19)=[0;0;0];
end

function r=v56ShiftJet(base,t,descent,kind,opts)
r=double(base(t));r=r(:);
for order=0:6
    if strcmp(kind,'STATIC')
        shift=double(order==0);
    else
        shift=v32S7(t-opts.v56SmoothStart,opts.v56SmoothDuration,order);
    end
    r(3+4*order)=r(3+4*order)-descent*shift;
end
end

function y=v56AuthenticSaddleJet(f,t,L,isDronePosition)
y=double(f(t));y=y(:);
assert(numel(y)==28 && all(isfinite(y)), ...
    'CBF:HLCV56SaddleJetLayout', ...
    'External saddle must return 28 finite entries: x,y,z,yaw derivatives 0..6');
if isDronePosition,y(3)=y(3)-L;end
end

function v56AuditJet(f,t0,tend,tag)
% Shape and finiteness checks; this is NOT a finite-difference
% derivative coherence audit nor a realizability certificate.
for t=[t0,0.5*(t0+tend),tend]
    raw=double(f(t));raw=raw(:);
    assert(numel(raw)==28 && all(isfinite(raw)), ...
        'CBF:HLCV56ReferenceShape','Reference invalid at t=%g %s',t,tag);
end
end

function [T,S]=v56RunOne(sc,opts,mode,id,work)
s=sc.settings;H=v23MakeHLC(s,opts.dt);x=sc.x0(:);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
if startsWith(id,'V57_')
    K=round(opts.v57Horizon/opts.dt); tBegin=opts.v57TStart;
else
    K=round(opts.v56Duration/opts.dt); tBegin=0;
end
cols={'time_s','refZ_m','refVz_mps','loadZ_m','loadVz_mps', ...
 'droneZ_m','refMinusLoadZ_m','refMinusLoadVz_mps', ...
 'rawThrust_N','clippedNominalThrust_N','appliedThrust_N', ...
 'rawTauX_Nm','rawTauY_Nm','rawTauZ_Nm', ...
 'rawTauInf_Nm','appliedTauInf_Nm','rawThrustMinusApplied_N', ...
 'rawTauMinusAppliedInf_Nm','v1_0','VsNorm','alphaNorm', ...
 'betaSigmaMin','betaCondition','thrustDenominator','cableH', ...
 'appliedTension_N','obstacleIndexLower','obstacleIndexUpper', ...
 'r1Status','stepApplied','referenceSixthNorm','inputThrustClipped', ...
 'inputTorqueClipped','rawTorqueOverPhysicalMax','loadBelowZero', ...
 'droneBelowZero'};
rows=cell(K+1,numel(cols));n=0;
S=struct('status','COMPLETE_DIAGNOSTIC','lastTime',NaN);
firstR1Logged=false;
for k=0:K
    t=tBegin+k*opts.dt;
    a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
    if ~all(isfinite([a.raw;a.beta(:);a.alpha(:)])) || a.betaRcond<1e-14
        S.status='HLC_INVERSION_NONFINITE_OR_SINGULAR';S.lastTime=t;break;
    end
    nominal=min(hi,max(lo,a.raw));applied=nominal;msg='NOT_USED';
    if strcmp(mode,'R1_EXACT')
        [candidate,msg]=v25R1ExactFilter(x,s,sc.obstacles,nominal);
        if strcmp(msg,'OK'),applied=candidate;
        else,applied=nan(4,1);S.status=['R1_FILTER_STOP_' msg];end
        if (~firstR1Logged && (any(isnan(applied)) || ...
                 abs(applied(1)-nominal(1))>1e-8))
            firstR1Logged=true;
            v56IntervalSnapshot(work,x,t,a,s,sc.obstacles,nominal,id);
        elseif ~strcmp(msg,'OK')
            v56IntervalSnapshot(work,x,t,a,s,sc.obstacles,nominal,id);
        end
    end
    hasAction=all(isfinite(applied));
    if hasAction
        tension=v23Tension(x,s,applied(1));
        tauApplied=norm(applied(2:4),Inf);
        deltaTau=norm(a.raw(2:4)-applied(2:4),Inf);
        deltaThrust=a.raw(1)-applied(1);
    else
        tension=nan;tauApplied=nan;deltaTau=nan;deltaThrust=nan;
    end
    droneZ=x(10)-s.physical.cableLength*x(16);
    h=v23CableSafety(x,sc);
    clipT=abs(a.raw(1)-nominal(1))>1e-9;
    clipTau=norm(a.raw(2:4)-nominal(2:4),Inf)>1e-9;
    physicalMaxTau=max(abs([lo(2:4);hi(2:4)]));
    tr={t,a.refPos(3),a.refVel(3),x(10),x(13), ...
        droneZ,a.refPos(3)-x(10),a.refVel(3)-x(13), ...
        a.raw(1),nominal(1),applied(1), ...
        a.raw(2),a.raw(3),a.raw(4),a.rawTorqueInf, ...
        tauApplied,deltaThrust,deltaTau,a.vfRaw(1),a.vsNorm, ...
        a.alphaNorm,a.sigmaMin,a.betaCond,a.thrustDenominator, ...
        h,tension,nan,nan,msg,false,norm(a.ref6),clipT,clipTau, ...
        a.rawTorqueInf>physicalMaxTau+1e-9,x(10)<0,droneZ<0};
    assert(numel(tr)==numel(cols),'CBF:HLCV56RowWidth');
    n=n+1;rows(n,:)=tr;S.lastTime=t;
    if ~hasAction,break;end
    if tension<=0
        S.status='NONPOSITIVE_CABLE_TENSION_BEFORE_STEP';break;
    end
    % Ground reference: load/drone altitude sign is measured ONLY.
    % No ground CBF is invented, no claim about real safe operation.
    if x(10)<0 || droneZ<0
        S.status='GROUND_ZERO_HEIGHT_CROSSED_SAMPLED';break;
    end
    if k==K,break;end
    x=v25StepOnce(x,applied,s,opts);
    rows{n,find(strcmp(cols,'stepApplied'))}=true;
    if ~all(isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
            abs(norm(x(14:16))-1)>1e-3
        S.status='PLANT_NONFINITE_OR_MANIFOLD_FAIL';break;
    end
end
T=cell2table(rows(1:n,:),'VariableNames',cols);
end

function v56IntervalSnapshot(work,x,t,a,s,obs,nominal,id)
try
    % Write to case-specific CSV; DO NOT overwrite original V55 snapshots.
    fname=sprintf('%s_R1_INTERVAL_T%04d.csv',id,round(t*1000));
    v55R1IntervalAudit(work,x,t,a,s,obs,nominal,fname);
catch ME
    v23WriteText(fullfile(work,['V56_INTERVAL_WARNING_' id '.txt']), ...
        getReport(ME,'extended','hyperlinks','off'));
end
end

function row=v56SummaryRow(id,kind,drop,mode,T,S,hasSaddle)
firstNeg=v56First(T.time_s,T.rawThrust_N<0);
firstOver=v56First(T.time_s,T.rawTorqueOverPhysicalMax>0);
firstR1=v56First(T.time_s,abs(T.appliedThrust_N- ...
    T.clippedNominalThrust_N)>1e-8);
valid=isfinite(T.appliedThrust_N);
D=abs(T.rawThrust_N-T.appliedThrust_N);
if any(valid)
    m=max(D(valid));
else
    m=nan;
end
row={id,kind,drop,mode,S.status,S.lastTime,height(T), ...
  min(T.rawThrust_N),max(T.rawThrust_N), ...
  max(T.rawTauInf_Nm),v56FiniteMax(T.appliedTauInf_Nm), ...
  m,max(abs(T.refMinusLoadZ_m)), ...
  T.loadZ_m(1),T.loadZ_m(end),T.refZ_m(1),T.refZ_m(end), ...
  min(T.loadZ_m),min(T.droneZ_m), ...
  v56FiniteMin(T.appliedTension_N), ...
  min(T.betaSigmaMin),firstNeg,firstOver,firstR1, ...
  sum(T.inputTorqueClipped),sum(T.inputThrustClipped), ...
  min(T.cableH),v56SaddleSourceLabel(hasSaddle),''};
assert(numel(row)==29,'CBF:HLCV56SummaryWidth');
end

function val=v56FiniteMax(x)
x=x(isfinite(x));if isempty(x),val=nan;else,val=max(x);end
end
function val=v56FiniteMin(x)
x=x(isfinite(x));if isempty(x),val=nan;else,val=min(x);end
end
function t=v56First(ts,m)
i=find(m,1,'first');if isempty(i),t=nan;else,t=ts(i);end
end

function str=v56SaddleSourceLabel(hasSaddle)
if hasSaddle,str='USER_EXTERNAL_REFERENCE_HANDLE';
else,str='NOT_SUPPLIED_NO_SADDLE_EXECUTED';end
end

function v56WriteHandover(work,opts)
lines={ ...
 'CBF HLC V56 - DESCENT / SADDLE CAUSAL DIAGNOSTIC (not a new HLC or CBF)'; ...
 'The unchanged HLC remains the reference controller: not assumed to be a design error.'; ...
 'Purpose: isolate downward reference error from original R1 thrust intervention.'; ...
 'R193 original gen_ref_line + gen_ref_for_rigid_body order6; payload z=drone z-cable length, position order0 only.'; ...
 'The initial diagnostic physical state is matched to original R193 straight flight; it is NOT a live Flight EKF snapshot.'; ...
 'STATIC: target z decreased at t0 by drop (derivative orders 1..6 unchanged); it is not a new moving step at t=0.'; ...
 'SMOOTH: S7=beta(8,8) C7 finite-time vertical retarget from t=0.5, over configured duration, all derivatives 0..6 exact.'; ...
 'Both NOMINAL/R1_EXACT use same physical initial conditions, goal, 19-state V11 plant, 25ms samples, actual hard [T,tau] limits.'; ...
 'New V56 R193-line tests use the V32 path-relative diagnostic stationary ellipsoid, NOT the V19 straight_single x-path obstacle; old V55 uses untouched original V19 geometry.'; ...
 'R1 hard-stop has NaN applied force, and no plant transition on an infeasible step; STOP ROW IS NOT A PHYSICAL ZERO-THRUST ACTION.'; ...
 'Zero ground altitude is only a crude sampled sign flag; no floor radius, load geometry or ground CBF is implemented.'; ...
 'No special saddle model was fabricated. For actual saddle, supply opts.v56SaddleJet=@(t) 28x1 payload target jet including yaw derivatives 0..6.'; ...
 'If the true saddle returns DRONE position, explicitly set opts.v56SaddleIsDronePosition=true. Only 0-order Z gets -cableLength.'; ...
 'Saddle nominal and saddle R1 share the same saddle-matched initial physical state; their initial state differs from straight initial state.'; ...
 'Failure of a new descending target does not disprove the validity of the original HLC; it can exceed actuator capability or reach a nonphysical goal.'; ...
 'A nominal HLC working with a downward target does not imply a CBF-modified thrust is consistent with native HLC high-order inverse.'; ...
 'The R193 archive includes saddle references in comments, but the actual saddle generator was not present in uploaded source.'; ...
 'V55 R1 interval diagnosis remains separate and is run first by default (opts.v56IncludeV55=true).'; ...
 'V56 one-file workflow: overwrite common_matlab/test_CBF_HLC_RootCause.m only; run test_CBF_HLC_RootCause() without opts.'; ...
 'Output: common_matlab/_CBF_TEST_OUTPUT/CBF_HLC_ROOTCAUSE_V56_<timestamp>.zip ONLY, with past ZIPs retained.'; ...
 sprintf('Run duration %g s, drop array %s, smooth start %g s, duration %g s', ...
     opts.v56Duration,mat2str(opts.v56DropAmounts),opts.v56SmoothStart,opts.v56SmoothDuration); ...
 'Status, trace and V56_*_R1_INTERVAL files contain MATLAB-observed values ONLY after an actual MATLAB run.'; ...
 'No claim of a verified MATLAB run, or nonlinear recursive safety, is made from source packaging alone.'};
v23WriteText(fullfile(work,'V56_HANDOVER_README.txt'),strjoin(lines,newline));
end


% ========================================================================
% V57: V19 obstacle/pre-intervention matched comparison. NO CHANGE to HLC,
% R1 inequality, physics, gains, estimator, or physical actuator limits.
% V56 R193 reference geometry had zero thrust input authority and positive
% RHS at t=0, so it never tested an actual CBF intervention. V57 evaluates
% the historical V19 collision geometry where R1 first acts at t=2.150.
% This is a deliberately isolated V19 validation, NOT normal Flight/EKF.
% ========================================================================
function out=v57V19MatchedComparison(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') ...
    && abs(opts.dt-0.025)<1e-12, 'CBF:HLCV57Protocol');
assert(isfinite(opts.v57TStart) && abs(opts.v57TStart-2.125)<1e-10 ...
    && opts.v57Horizon>0 && ...
    abs(round(opts.v57Horizon/opts.dt)*opts.dt-opts.v57Horizon)<1e-10 ...
    && opts.v57SmoothDuration>0, 'CBF:HLCV57TScale');
assert(all(isfinite([opts.v57StaticDrops(:);opts.v57SmoothDrops(:)])) ...
    && all([opts.v57StaticDrops(:);opts.v57SmoothDrops(:)]>0), ...
    'CBF:HLCV57Drops');
sc=CBF_V19_Scenarios('straight_single','R193'); sc.dt=opts.dt;
[x0,source]=v40GetV19PreInterventionState(sc,opts,opts.v57TStart);
assert(numel(x0)==19 && all(isfinite(x0)), 'CBF:HLCV57X0');
sc.x0=x0(:);
v23WriteText(fullfile(work,'V57_INITIAL_STATE_PROVENANCE.txt'),source);
base=@(t)v57V19OriginalJet(sc,t);
% In contrast to V56, keep the historical obstacle geometry EXACT.
% Constant-down references are present at the first measurement; smooth
% references have C7 0..6 derivatives and start at t=2.125 (NOT a step).
labels={'V57_B00_ORIGINAL_NOMINAL','V57_B01_ORIGINAL_R1'};
refs={[],[]}; drops=[0,0]; types={'ORIGINAL','ORIGINAL'};
modes={'NOMINAL','R1_EXACT'};
for j=1:numel(opts.v57StaticDrops)
    d=opts.v57StaticDrops(j);
    r=@(t)v57V19Shift(base,t,d,false,opts);
    labels{end+1}=sprintf('V57_S%02d_STATIC_NOMINAL',j);
    labels{end+1}=sprintf('V57_S%02d_STATIC_R1',j);
    refs(end+1:end+2)={r,r}; drops(end+1:end+2)=[d d];
    types(end+1:end+2)={'STATIC','STATIC'};
    modes(end+1:end+2)={'NOMINAL','R1_EXACT'};
end
for j=1:numel(opts.v57SmoothDrops)
    d=opts.v57SmoothDrops(j);
    r=@(t)v57V19Shift(base,t,d,true,opts);
    labels{end+1}=sprintf('V57_M%02d_SMOOTH_NOMINAL',j);
    labels{end+1}=sprintf('V57_M%02d_SMOOTH_R1',j);
    refs(end+1:end+2)={r,r}; drops(end+1:end+2)=[d d];
    types(end+1:end+2)={'SMOOTH','SMOOTH'};
    modes(end+1:end+2)={'NOMINAL','R1_EXACT'};
end
cols={'caseID','refType','descent_m','mode','status','lastTime_s', ...
    'nSamples','firstR1Change_s','minRawThrust_N','maxRawThrust_N', ...
    'maxRawTorqueInf_Nm','maxAppliedTorqueInf_Nm','minTension_N', ...
    'minCableH','minBetaSigma','maxAbsVerticalError_m', ...
    'firstRawNegativeThrust_s','firstRawTorqueAboveLimit_s', ...
    'nThrustSaturated','nTorqueSaturated','peakReferenceSixthNorm', ...
    'startRefZ_m','endRefZ_m','maxRawAppliedThrustGap_N','runtimeError'};
rows=cell(numel(labels),numel(cols));
bad=0;runtime=0;r1stop=0;
for i=1:numel(labels)
    id=labels{i};c=sc;
    if ~isempty(refs{i})
        jet=refs{i};
        c.refFull=jet;
        c.ref=@(t,k)v32XYZJet(jet,t,k);
    end
    fprintf('[HLC V57] %s type=%s drop=%.4g mode=%s\n', ...
        id,types{i},drops(i),modes{i});
    try
        [T,S]=v56RunOne(c,opts,modes{i},id,work);
        writetable(T,fullfile(work,['V57_TRACE_' id '.csv']));
        change=v56First(T.time_s,abs(T.appliedThrust_N- ...
            T.clippedNominalThrust_N)>1e-8);
        gap=abs(T.rawThrust_N-T.appliedThrust_N);
        rows(i,:)={id,types{i},drops(i),modes{i},S.status, ...
            S.lastTime,height(T),change,min(T.rawThrust_N), ...
            max(T.rawThrust_N),max(T.rawTauInf_Nm), ...
            v56FiniteMax(T.appliedTauInf_Nm), ...
            v56FiniteMin(T.appliedTension_N),min(T.cableH), ...
            min(T.betaSigmaMin),max(abs(T.refMinusLoadZ_m)), ...
            v56First(T.time_s,T.rawThrust_N<0), ...
            v56First(T.time_s,T.rawTorqueOverPhysicalMax), ...
            sum(T.inputThrustClipped),sum(T.inputTorqueClipped), ...
            max(T.referenceSixthNorm),T.refZ_m(1),T.refZ_m(end), ...
            v56FiniteMax(gap),''};
        if ~strcmp(S.status,'COMPLETE_DIAGNOSTIC')
            bad=bad+1;
            if startsWith(S.status,'R1_FILTER_STOP_'),r1stop=r1stop+1;end
        end
    catch ME
        bad=bad+1;runtime=runtime+1;
        rows(i,:)={id,types{i},drops(i),modes{i}, ...
            ['MATLAB_ERROR_' ME.identifier],nan,0,nan,nan,nan,nan, ...
            nan,nan,nan,nan,nan,nan,nan,0,0,nan,nan,nan,nan,ME.message};
        v23WriteText(fullfile(work,['V57_ERROR_' id '.txt']), ...
            getReport(ME,'extended','hyperlinks','off'));
    end
end
writetable(cell2table(rows,'VariableNames',cols), ...
    fullfile(work,'V57_V19_DESCENT_COMPARISON_SUMMARY.csv'));
out=struct('nCases',numel(labels),'nFailedCases',bad, ...
    'nRuntimeErrors',runtime,'nR1FilterStops',r1stop);
end

function r=v57V19OriginalJet(sc,t)
r=zeros(28,1);
for j=0:6
    v=double(sc.ref(t,j));v=v(:);
    assert(numel(v)==3 && all(isfinite(v)), 'CBF:HLCV57OriginalJet');
    r(4*j+(1:3))=v;
end
% The original V19 HLC sets yaw and all yaw derivatives to zero.
end

function r=v57V19Shift(base,t,drop,smooth,opts)
r=base(t);
for k=0:6
    if smooth
        delta=v32S7(t-opts.v57TStart,opts.v57SmoothDuration,k);
    else
        delta=double(k==0);
    end
    r(4*k+3)=r(4*k+3)-drop*delta;
end
end

function v57WriteHandover(work,opts)
report={ ...
 'V57 handover: same V19 straight_single obstacle and same 2.125s pre-R1 actual state for every reference/mode'; ...
 'Results MUST be interpreted with V57_V19_DESCENT_COMPARISON_SUMMARY and V57_TRACE*. No simulated data was filled in by code generation.'; ...
 'V56 prior result: 9 R193-line R1 cases all stopped at t0 due to A=0, RHS=2.82733096945477; these never applied CBF thrust.'; ...
 'V56 smooth 0.75 m downward ORIGINAL HLC completed 4s, 2.20cm max vertical error; no saturation; nominal may violate cable obstacle h; not certified.'; ...
 'V56 static 0.75m target at t0: initial raw thrust -40.1007486 N, clipped 0, slack tension and stopped. That step is not an attainable smooth descent.'; ...
 'V55/V19 exact original R1 failure t2.350: A=0.00776805097083529, rhs=0.216961372677405, T>=27.929962546844>20N; raw HLC thrust -7.71566108869428N at stopped state.'; ...
 'V57 preserves original HLC, R1 inequality, nonlinear 19-state V11 plant, actuator limits, initial estimated mass 0.01kg.'; ...
 'V57 pairs ORIGINAL, STATIC offsets, exact C7 SMOOTH offsets at original V19 reference; each pair starts same state at t=2.125.'; ...
 'STATIC offsets are constant targets that differ already at t=2.125; not a continuous retarget operation. SMOOTH offsets start at t2.125 and are not fully reached within the short window.'; ...
 'All V57 V19 test obstacles are UNMODIFIED original V19 straight_single; no geometry repositioning to manufacture feasibility.'; ...
 'Ground check only sign of payload/drone z; zero crossing is not a safety certified ground CBF.'; ...
 'CBF stop rows carry NaN applied input and do not advance physical state. Never read them as physical 0N commands.'; ...
 'If all R1 tests fail at the same time but nominal survives, evaluate thrust interval bounds and higher-order virtual-input mismatch.'; ...
 'Actual saddle generator was not supplied. V57 makes NO claim to simulate saddle; previous optional saddle hook remains available via opts.v57V19Comparison=false.'; ...
 'User workflow: overwrite ONLY common_matlab/test_CBF_HLC_RootCause.m; MATLAB command clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath);'; ...
 'Output is ONLY ZIP under common_matlab/_CBF_TEST_OUTPUT; previous ZIPs preserved. Embedded cumulative V54 handover remains archived in same ZIP.'; ...
 sprintf('V57 time start=%.3f, horizon=%.3f, smooth duration=%.3f, static drops=%s, smooth drops=%s', ...
   opts.v57TStart,opts.v57Horizon,opts.v57SmoothDuration, ...
   mat2str(opts.v57StaticDrops),mat2str(opts.v57SmoothDrops))};
v23WriteText(fullfile(work,'V57_HANDOVER_README.txt'),strjoin(report,newline));
end


% ========================================================================
% V58: AT MATCHED CLOSED-LOOP STATES, WHAT HAPPENS IF R1 STOPS?
% NO application to flight, NO change to HLC/CBF/plant/actuator limits.
% Crucially, an R1-OFF trajectory may violate obstacle safety immediately.
% This is a CAUSAL COUNTERFACTUAL, not a suggested controller switch.
% ========================================================================
function out=v58ReleaseAndRecoverSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') ...
    && abs(opts.dt-0.025)<1e-12,'CBF:HLCV58Protocol');
assert(all(isfinite(opts.v58ReleaseTimes)) && ...
    all(opts.v58ReleaseTimes>=2.125-1e-10) && ...
    all(opts.v58ReleaseTimes<=2.325+1e-10) && ...
    all(abs(round((opts.v58ReleaseTimes-2.125)/opts.dt)*opts.dt ...
     -(opts.v58ReleaseTimes-2.125))<1e-8) && ...
    opts.v58BranchHorizon>=opts.dt && ...
    abs(round(opts.v58BranchHorizon/opts.dt)*opts.dt ...
    -opts.v58BranchHorizon)<1e-8, 'CBF:HLCV58TimeGrid');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,source]=v40GetV19PreInterventionState(sc,opts,2.125);
v23WriteText(fullfile(work,'V58_START_STATE_SOURCE.txt'),source);
x=x0(:);s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
check=unique(sort(opts.v58ReleaseTimes(:).'));
K=round((max(check)-2.125)/opts.dt);
cols0={'time_s','loadZ_m','loadVz_mps','rawThrust_N', ...
 'clippedThrust_N','appliedR1Thrust_N','rawTauInf_Nm', ...
 'appliedTauInf_Nm','betaSigmaMin','v1_0','inputGap_N', ...
 'referenceVerticalError_m','r1FilterStatus','actuatorClippedTorque'};
rows0=cell(K+1,numel(cols0));n0=0;
states=cell(1,numel(check));recorded=false(size(check));
for k=0:K
    t=2.125+k*opts.dt;
    a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
    nom=min(hi,max(lo,a.raw));
    [u,msg]=v25R1ExactFilter(x,s,sc.obstacles,nom);
    assert(strcmp(msg,'OK'),'CBF:HLCV58ReplayR1', ...
        'Original R1 failed before release checkpoint t=%.4f status=%s',t,msg);
    n0=n0+1;
    rows0(n0,:)={t,x(10),x(13),a.raw(1),nom(1),u(1), ...
      a.rawTorqueInf,norm(u(2:4),Inf),a.sigmaMin,a.vfRaw(1), ...
      u(1)-a.raw(1),a.refPos(3)-x(10),msg, ...
      norm(a.raw(2:4)-nom(2:4),Inf)>1e-8};
    z=find(abs(check-t)<1e-8);
    for jj=z
        states{jj}=x;recorded(jj)=true;
        v55R1IntervalAudit(work,x,t,a,s,sc.obstacles,nom, ...
            sprintf('V58_RELEASE_CBF_INTERVAL_T%04d.csv',round(1000*t)));
    end
    if k<K
        assert(v23Tension(x,s,u(1))>0, ...
            'CBF:HLCV58Tension','Original R1 replay slack before checkpoint');
        x=v25StepOnce(x,u,s,opts);
        assert(all(isfinite(x)),'CBF:HLCV58Nonfinite');
    end
end
assert(all(recorded),'CBF:HLCV58Checkpoint');
writetable(cell2table(rows0(1:n0,:),'VariableNames',cols0), ...
    fullfile(work,'V58_ACTUAL_R1_CHECKPOINT_TIMELINE.csv'));

cols={'releaseTime_s','mode','status','lastTime_s','nSamples', ...
 'releaseRawThrust_N','releaseRawTorqueInf_Nm','releaseBetaSigmaMin', ...
 'releaseV1','releaseR1Thrust_N','releaseNominalThrust_N', ...
 'releaseCBFDelta_N','minRawThrust_N','maxRawThrust_N', ...
 'maxRawTorqueInf_Nm','maxAppliedTorqueInf_Nm', ...
 'maxRawAppliedThrustGap_N','minTension_N','minCableH', ...
 'firstRawNegative_s','firstTorqueAboveLimit_s', ...
 'nThrustSaturated','nTorqueSaturated','runtimeError'};
rows=cell(numel(check)*2,numel(cols));n=0;bad=0;runtime=0;r1stop=0;
for j=1:numel(check)
    t=check(j); xx=states{j};
    a=v23HLC(xx,t,sc,H,v23EstimatedMass(opts,t));
    nominal=min(hi,max(lo,a.raw));
    [r1,reason]=v25R1ExactFilter(xx,s,sc.obstacles,nominal);
    assert(strcmp(reason,'OK'),'CBF:HLCV58AtReleaseCBF');
    for modeID=1:2
        n=n+1;
        if modeID==1, mode='OFF_NOMINAL'; alg='NOMINAL';
        else, mode='CONTINUE_R1'; alg='R1_EXACT'; end
        ident=sprintf('V57_V58_T%04d_%s',round(1000*t),mode);
        fprintf('[HLC V58] release %.3f %s\n',t,mode);
        cc=sc;cc.x0=xx;
        op=opts;op.v57TStart=t;op.v57Horizon=opts.v58BranchHorizon;
        try
            [T,S]=v56RunOne(cc,op,alg,ident,work);
            writetable(T,fullfile(work,['V58_TRACE_' ident '.csv']));
            rows(n,:)={t,mode,S.status,S.lastTime,height(T), ...
                a.raw(1),a.rawTorqueInf,a.sigmaMin,a.vfRaw(1),r1(1), ...
                nominal(1),r1(1)-nominal(1), ...
                min(T.rawThrust_N),max(T.rawThrust_N), ...
                max(T.rawTauInf_Nm),v56FiniteMax(T.appliedTauInf_Nm), ...
                v56FiniteMax(abs(T.rawThrustMinusApplied_N)), ...
                v56FiniteMin(T.appliedTension_N),min(T.cableH), ...
                v56First(T.time_s,T.rawThrust_N<0), ...
                v56First(T.time_s,T.rawTorqueOverPhysicalMax), ...
                sum(T.inputThrustClipped),sum(T.inputTorqueClipped),''};
            if ~strcmp(S.status,'COMPLETE_DIAGNOSTIC')
                bad=bad+1;
                if startsWith(S.status,'R1_FILTER_STOP_'),r1stop=r1stop+1;end
            end
        catch ME
            bad=bad+1;runtime=runtime+1;
            rows(n,:)={t,mode,['MATLAB_ERROR_' ME.identifier], ...
                 NaN,0,a.raw(1),a.rawTorqueInf,a.sigmaMin,a.vfRaw(1), ...
                 r1(1),nominal(1),r1(1)-nominal(1), ...
                 NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,0,0,ME.message};
            v23WriteText(fullfile(work,['V58_ERROR_' ident '.txt']), ...
                getReport(ME,'extended','hyperlinks','off'));
        end
    end
end
writetable(cell2table(rows,'VariableNames',cols), ...
    fullfile(work,'V58_RELEASE_BRANCH_SUMMARY.csv'));
out=struct('nCases',n,'nFailedCases',bad, ...
    'nRuntimeErrors',runtime,'nR1FilterStops',r1stop);
end

function v58WriteHandover(work,opts)
textLines={ ...
'V58 HLC-CBF SWITCHING CAUSAL INVESTIGATION; all numbers must be read from MATLAB-produced CSV'; ...
'V57 observation: original nominal thrust 8.8666..8.8764N, nominal raw torque ~0.00213Nm, R1 first changes thrust t2.150.'; ...
'V57 R1 original at t2.300: raw T0.41539N, applied R1 T13.50173N, raw pitch torque 135.22944Nm, applied torque 1Nm.'; ...
'V57 R1 t2.325: raw T-2.72272N but applied R1 16.44754N; t2.350 R1 asks >=27.92996N >20N, hence stops, applied is NaN not zero.'; ...
'V53 V1 derivative audit at t2.300: torque sensitivity dominated beta2 inverse component (~502.97 vs alpha component ~11.87 Nm per unit v1).'; ...
'V54 algebraically reassigning v1 to actual thrust drops same-state computed torque from 135.229Nm to 0.708Nm, BUT higher V1 derivatives are frozen and time consistency is NOT established.'; ...
'V58 replays ORIGINAL V19 exact R1 from real pre-R1 t2.125 x0 and saves checkpoints. At EACH checkpoint, fork from IDENTICAL x into OFF_NOMINAL or CONTINUE_R1, 25ms real nonlinear plant/physical actuator saturation.'; ...
'OFF_NOMINAL is a hypothetical diagnostic (CBF disabled). It may violate the same obstacle CBF instantly and must NOT be interpreted as a safe release policy.'; ...
'No HLC gains or formulas, nominal reference, R1 inequality, V11_19 nonlinear plant or actuator limits changed. No antiwindup or new controller implemented.'; ...
'Compare V58_ACTUAL_R1_CHECKPOINT_TIMELINE, V58_RELEASE_BRANCH_SUMMARY, paired V58_TRACE_* and per-release V58_RELEASE_CBF_INTERVAL_* to assess hazard of transition.'; ...
'Conclusions about safe disengagement, viability or persistent feasibility require a redesigned input-constrained supervisor and future-state verification, not 25ms pointwise R1 alone.'; ...
'Historical R193 initial estimated mass=0.01kg, not real-time Flight EKF. Original saddle generator not provided. Results are diagnostic, not hardware certified.'; ...
'Workflow: overwrite one test_CBF_HLC_RootCause.m in common_matlab; clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath).'; ...
'Only result ZIP under common_matlab/_CBF_TEST_OUTPUT, previous result ZIPs preserved.'; ...
sprintf('Release times=%s, branch horizon %.3fs', ...
    mat2str(opts.v58ReleaseTimes),opts.v58BranchHorizon)};
v23WriteText(fullfile(work,'V58_HANDOVER_README.txt'), ...
    strjoin(textLines,newline));
end


% ========================================================================
% V59: PHYSICAL FOUR-INPUT PREDICTIVE SAFETY FILTER (RESEARCH PROTOTYPE).
% Uses real 19-state V11_19 nonlinear RK4, unchanged generated HLC,
% simultaneous [thrust,roll,pitch,yaw torque] optimization with fmincon.
% Hard SAMPLE constraints: 3-D cable/drone/load ellipsoid, ground, cable
% tension, 4 actuator bounds and terminal safety slope + HLC re-entry.
% Sampling + finite horizon DOES NOT establish continuous or recursive
% CBF invariance. Any nonlinear-program failure means STOP, not safe.
% ========================================================================
function out=v59FourInputSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') ...
 && abs(opts.dt-0.025)<1e-12 && opts.substeps>=1, 'CBF:V59Protocol');
assert(opts.v59Horizon>=opts.dt*4 && ...
 abs(opts.v59Horizon/opts.dt-round(opts.v59Horizon/opts.dt))<1e-8, ...
 'CBF:V59Horizon');
assert(opts.v59End>opts.v59Start && opts.v59MinTension>0 && ...
 opts.v59TerminalRate>0,'CBF:V59Settings');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x,provenance]=v40GetV19PreInterventionState(sc,opts,opts.v59Start);
assert(all(isfinite(x)) && numel(x)==19,'CBF:V59InitialState');
v23WriteText(fullfile(work,'V59_INITIAL_STATE.txt'),provenance);
s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
cols={'time_s','decision','exitflag','predictionMaxConstraint', ...
 'solveTime_s','rawT_N','nomT_N','appliedT_N', ...
 'rawTauX_Nm','rawTauY_Nm','rawTauZ_Nm', ...
 'appliedTauX_Nm','appliedTauY_Nm','appliedTauZ_Nm', ...
 'rawTauInf_Nm','appliedTauInf_Nm','betaSigmaMin', ...
 'loadX_m','loadY_m','loadZ_m','loadVz_mps', ...
 'cableH','minShapeH','droneGroundClearance_m', ...
 'loadGroundClearance_m','tension_N','predTerminalMinH', ...
 'predTerminalMinSlope','initialNominalMaxViolation', ...
 'appliedInputMismatchScaled','solverMessage'};
rows=cell(ceil((opts.v59End-opts.v59Start)/opts.dt)+1,numel(cols));
n=0;status='COMPLETED_FINITE_HORIZON_NOT_CERTIFIED';zWarm=zeros(12,1);
if exist('fmincon','file')~=2
 status='STOP_NO_FMINCON_OPTIMIZATION_TOOLBOX';
else
 for k=0:round((opts.v59End-opts.v59Start)/opts.dt)
  t=opts.v59Start+k*opts.dt;
  try
   a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
   base=min(hi,max(lo,a.raw));
   [gg,gLabels]=v59Geometry(x,sc);
   if any(~isfinite([a.raw;gg])) || any(gg < -1e-7)
      status='STOP_INVALID_HLC_OR_ALREADY_UNSAFE';break;
   end
   clock=tic;
   [u,zWarm,info]=v59Solve(x,t,sc,H,opts,lo,hi,zWarm);
   elapsed=toc(clock);
   if ~info.ok
     status=['STOP_PREDICTIVE_INFEASIBLE_' info.label];
     u=nan(4,1);
   end
   if all(isfinite(u)),tn=v23Tension(x,s,u(1));else,tn=nan;end
   if all(isfinite(u)),apTau=norm(u(2:4),Inf);else,apTau=nan;end
   gd=gg(end-1:end);
   n=n+1;
   rows(n,:)={t,info.mode,info.exitflag,info.maxC,elapsed, ...
      a.raw(1),base(1),u(1),a.raw(2),a.raw(3),a.raw(4), ...
      u(2),u(3),u(4),a.rawTorqueInf,apTau,a.sigmaMin, ...
      x(8),x(9),x(10),x(13),v23CableSafety(x,sc), ...
      min(gg),gd(1),gd(2),tn,info.terminalH,info.terminalSlope, ...
      info.baseMaxC,norm((u-base)./[10;1;1;1]),info.label};
   if ~info.ok,break;end
   if tn<opts.v59MinTension-1e-7
      status='STOP_ACTUAL_TENSION_BELOW_MINIMUM';break;
   end
   if k==round((opts.v59End-opts.v59Start)/opts.dt),break;end
   x=v25StepOnce(x,u,s,opts);
   if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
       abs(norm(x(14:16))-1)>1e-3
      status='STOP_NONFINITE_OR_MANIFOLD_ERROR';break;
   end
  catch ME
   status=['MATLAB_ERROR_' ME.identifier];
   v23WriteText(fullfile(work,'V59_ERROR.txt'), ...
      getReport(ME,'extended','hyperlinks','off'));
   break;
  end
 end
end
T=cell2table(rows(1:n,:),'VariableNames',cols);
writetable(T,fullfile(work,'V59_FOUR_INPUT_TRACE.csv'));
v23WriteText(fullfile(work,'V59_RUN_STATUS.txt'),sprintf( ...
 ['status=%s\nsteps=%d\nlast_t=%.4f\n', ...
 'The constraints hold only at sampled predicted states, not between samples.\n', ...
 'Terminal slope and raw HLC reentry are necessary-style heuristics, not a certified invariant set.\n', ...
 'NO hardware claims and NO safe fallback assumed.\n'], ...
 status,n,opts.v59Start+max(0,n-1)*opts.dt));
if startsWith(status,'MATLAB_ERROR_'),err=1;else,err=0;end
out=struct('nCases',1,'nFailedCases',~startsWith(status,'COMPLETED'), ...
 'nRuntimeErrors',err,'nR1FilterStops',0);
end

function [u,zout,info]=v59Solve(x,t,sc,H,opts,lo,hi,zWarm)
% Parameterization: 3 smooth, linearly interpolated four-input correction
% knots over N future 25ms intervals. Recompute nominal HLC at every
% predicted state; optimize deviations around ACTUAL four physical inputs.
z0=zeros(12,1);N=round(opts.v59Horizon/opts.dt);
[h0,~]=v59Geometry(x,sc);
nh=numel(h0);
info=struct('ok',false,'label','UNKNOWN','mode','NONE', ...
 'exitflag',nan,'maxC',nan,'baseMaxC',nan, ...
 'terminalH',nan,'terminalSlope',nan);
[~,c0,p0]=v59Roll(x,t,z0,sc,H,opts,lo,hi,N,nh);
info.baseMaxC=max(c0);
if all(isfinite(c0)) && max(c0)<=1e-7
  u=p0.uFirst;zout=zeros(12,1);info.ok=true;
  info.label='NOMINAL_PREVIEW_FEASIBLE';info.mode='NOMINAL';
  info.exitflag=1;info.maxC=max(c0);
  info.terminalH=min(p0.terminalH);
  info.terminalSlope=min(p0.terminalSlope);return;
end
if any(~isfinite(c0))
 u=nan(4,1);zout=z0;info.label='BASE_PREVIEW_NONFINITE';return;
end
cachedZ=[];cachedObj=[];cachedC=[];cachedP=[];
    function evaluate(z)
      if isempty(cachedZ) || ~isequal(z(:),cachedZ)
       [cachedObj,cachedC,cachedP]=v59Roll(x,t,z(:),sc,H,opts,lo,hi,N,nh);
       cachedZ=z(:);
      end
    end
    function y=objective(z)
       evaluate(z);y=cachedObj;
    end
    function [c,ceq]=nonlin(z)
       evaluate(z);c=cachedC;ceq=[];
    end
try
  o=optimoptions('fmincon','Algorithm','sqp','Display','off', ...
    'MaxIterations',opts.v59MaxIterations, ...
    'MaxFunctionEvaluations',opts.v59MaxEvals, ...
    'ConstraintTolerance',1e-6,'StepTolerance',1e-6, ...
    'OptimalityTolerance',1e-3);
  % Bounded normalized search domain; physical input bounds remain HARD
  % constraints in v59Roll, never replaced by optimizer search bounds.
  z0=min(2,max(-2,zWarm(:)));
  [zsol,~,flag,output]=fmincon(@objective,z0,[],[],[],[], ...
     -2*ones(12,1),2*ones(12,1),@nonlin,o);
  evaluate(zsol);
  pp=cachedP;cc=cachedC;
  info.exitflag=flag;info.maxC=max(cc);
  info.terminalH=min(pp.terminalH);
  info.terminalSlope=min(pp.terminalSlope);
  if isfinite(info.maxC) && info.maxC<=1e-5 && ...
      all(isfinite(pp.uFirst)) && ...
      all(pp.uFirst>=lo-1e-6 & pp.uFirst<=hi+1e-6)
    info.ok=true;info.mode='4U_PREDICTIVE';
    info.label=sprintf('SAMPLED_FEASIBLE_EXITFLAG_%d',flag);
    u=pp.uFirst;
    zz=reshape(zsol,4,3);
    shift=opts.dt;grid=[0,opts.v59Horizon/2,opts.v59Horizon];
    zout=interp1(grid,zz.',min(opts.v59Horizon,grid+shift),'linear').';
    zout=zout(:);
  else
    info.mode='STOP';
    info.label=sprintf('NLP_NOT_FEASIBLE_EXITFLAG_%d_%s', ...
       flag,regexprep(output.message,'\s+',' '));
    u=nan(4,1);zout=zsol;
  end
catch ME
 info.mode='STOP';info.label=['SOLVER_ERROR_' ME.identifier];
 u=nan(4,1);zout=z0;
end
end

function [J,c,p]=v59Roll(x,t,z,sc,H,opts,lo,hi,N,nh)
% Physically applied u is clipped ONLY FOR NUMERICAL TRIAL propagation;
% un-clipped u is constrained independently and is REJECTED if invalid.
% Equality of input effects in translation is never assumed.
s=sc.settings;dt=opts.dt;gg=zeros(nh,N+1);
[gg(:,1),~]=v59Geometry(x,sc);
C=zeros(N*(nh+9)+nh+8,1);aoff=0;
U=zeros(4,N);rawMismatch=0;J=0;
zk=reshape(z,4,3);scale=[10;1;1;1];
grid=[0,opts.v59Horizon/2,opts.v59Horizon];
valid=true;p=struct('uFirst',nan(4,1),'terminalH',nan(nh,1), ...
 'terminalSlope',nan(nh,1));
for j=1:N
 try
    aa=v23HLC(x,t+(j-1)*dt,sc,H, ...
        v23EstimatedMass(opts,t+(j-1)*dt));
    if ~all(isfinite(aa.raw)) || aa.betaRcond<1e-13
       valid=false;break;
    end
    unc=min(hi,max(lo,aa.raw));
    tt=(j-1)*dt;
    delta=interp1(grid,zk.',tt,'linear').';
    cmd=unc+scale.*delta;
    u=max(lo,min(hi,cmd));
    if j==1,p.uFirst=cmd;end
    U(:,j)=cmd;
    % Hard input box constraints for all 4 channels at ALL future nodes.
    C(aoff+(1:8))=[lo-cmd;cmd-hi];aoff=aoff+8;
    tn=v23Tension(x,s,u(1));
    C(aoff+1)=opts.v59MinTension-tn;aoff=aoff+1;
    x=v25StepOnce(x,u,s,opts);
    if ~all(isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
        abs(norm(x(14:16))-1)>1e-3
       valid=false;break;
    end
    [h,~]=v59Geometry(x,sc);gg(:,j+1)=h;
    C(aoff+(1:nh))=-h;aoff=aoff+nh;
    gap=(aa.raw-min(hi,max(lo,aa.raw)))./scale;
    rawMismatch=rawMismatch+sum(gap.^2);
    J=J+sum(delta.^2)+0.05*sum(((cmd-unc)./scale).^2);
 catch
    valid=false;break;
 end
end
if valid
 try
   last=v23HLC(x,t+N*dt,sc,H,v23EstimatedMass(opts,t+N*dt));
   if ~all(isfinite(last.raw)),valid=false;end
 catch
   valid=false;
 end
end
if ~valid
 J=1e9+sum(z(:).^2);
 C=1e3*ones(size(C));return;
end
hdot=(gg(:,end)-gg(:,end-1))/dt;
terminalSlope=hdot+opts.v59TerminalRate*gg(:,end);
C(aoff+(1:nh))=-terminalSlope;aoff=aoff+nh;
% An approximated HLC reentry guard: raw nominal physical inputs bounded
% at terminal state. Not a terminal control-invariant set.
C(aoff+(1:8))=[lo-last.raw;last.raw-hi];aoff=aoff+8;
assert(aoff==numel(C),'CBF:V59ConstraintSize');
J=J+3*rawMismatch+0.3*sum(diff(zk,1,2).^2,'all');
p.terminalH=gg(:,end);p.terminalSlope=terminalSlope;
c=C;
end

function [h,labels]=v59Geometry(x,sc)
% Exact V19 smooth cable-ellipsoid geometry; extra conservative
% bounding-sphere geometry for drone and load (conservative).
% Thus physical 3D obstacle avoidance is checked for ALL three components.
s=sc.settings;L=s.physical.cableLength;
q=x(14:16);loadP=x(8:10);droneP=loadP-L*q;
rc=s.shape.cableRadius;dm=s.cbf.safetyMargin;
a=L/2+rc;b=sqrt(a*rc);cableC=loadP-L*q/2;
nh=3*numel(sc.obstacles)+2;h=zeros(nh,1);
labels=cell(nh,1);idx=0;
for i=1:numel(sc.obstacles)
 o=sc.obstacles{i};d=o.center(:)-cableC;
 sca=sqrt(b^2*(d.'*d)+(a*a-b*b)*(d.'*q)^2+s.cbf.smoothEpsilon^2);
 so=sqrt(sum((o.axes(:).*(o.R.'*d)).^2)+s.cbf.smoothEpsilon^2);
 hc=d.'*d-sca-so-dm*sqrt(d.'*d+s.cbf.smoothEpsilon^2);
 idx=idx+1;h(idx)=hc;labels{idx}=sprintf('CABLE_OBS_%d',i);
 for component=1:2
  if component==1,p=droneP;r=s.shape.droneRadius;nm='DRONE';
  else,p=loadP;r=s.shape.loadRadius;nm='LOAD';end
  % A circumscribed sphere is CONSERVATIVE for an ellipsoid+sphere;
  % coordinatewise axes inflation is NOT generally conservative.
  hbody=norm(p-o.center(:))-(max(o.axes(:))+r+dm);
  idx=idx+1;h(idx)=hbody;labels{idx}=sprintf('%s_OBS_%d',nm,i);
 end
end
idx=idx+1;h(idx)=droneP(3)-s.shape.droneRadius-dm;
labels{idx}='DRONE_GROUND';
idx=idx+1;h(idx)=loadP(3)-s.shape.loadRadius-dm;
labels{idx}='LOAD_GROUND';
end

function v59WriteHandover(work,opts)
lines={ ...
 'V59 DESIGN: nonlinear four-physical-input predictive safety filter, not scalar-thrust R1.'; ...
 'All four inputs optimized simultaneously over 3 linearly interpolated correction knots (12 normalized variables).'; ...
 'Predictions use nonlinear 19-state V11_19 plant, actual HLC on predicted states, 25ms intervals, RK4.'; ...
 'Constraints: 3D smooth cable obstacle geometry copied from V19; added conservative bounding-sphere drone/load obstacle checks and ground geometries; physical 4-input bounds; tension lower bound; terminal hdot+rate*h; terminal raw-HLC inside bounds.'; ...
 'Ground/sphere checks are experimental extra constraints, NOT previously certified shape CBFs.'; ...
 'Terminal slope + nominal HLC input feasibility is not a terminal invariant set. No theorem of recursive feasibility or guaranteed safety is claimed.'; ...
 'Nonlinear constraints at discrete nodes alone do NOT guarantee continuous-time or intersample collision avoidance; model and estimation uncertainty omitted.'; ...
 'All optimizer constraints must pass with <=1e-5 residual; if not, STOP. Never substitute thrust-only R1 or unconstrained nominal as a fake safe control.'; ...
 'HLC generated formulas, gains, original reference, plant, actuator bounds unchanged; modifies only physical applied input in experimental test.'; ...
 'fmincon and Optimization Toolbox REQUIRED; no silent fallback. Total nonlinear evaluation budget is limited; result may be solver failure, not physical impossibility.'; ...
 'R193 initial historical mass estimate 0.01 kg, NOT live EKF. No flight/hardware code modified.'; ...
 'V58 confirmed at t2.325 raw HLC thrust -2.72N, R1 physical 16.45N, OFF raw saturates 0N, tension can fall near 0.00049N.'; ...
 'V57 confirmed R1 infeasibility at t2.350: thrust >=27.93N vs maximum 20N.'; ...
 'Use current common_matlab / test_CBF_HLC_RootCause.m single file overwrite; run test_CBF_HLC_RootCause(); zip only under _CBF_TEST_OUTPUT.'; ...
 sprintf('V59 t=[%.3f, %.3f], horizon %.3f, terminal rate %.3f 1/s, minimum tension %.4f N', ...
 opts.v59Start,opts.v59End,opts.v59Horizon,opts.v59TerminalRate,opts.v59MinTension)};
v23WriteText(fullfile(work,'V59_FULL_DESIGN_HANDOVER.txt'),strjoin(lines,newline));
end


% ========================================================================
% V61: NO MPC, NO FUTURE-STATE OPTIMIZATION, NO MODIFICATION OF SOURCE HLC.
% Side-by-side physical nonlinear closed-loop experiments, identical x0.
%
% A. ORIGINAL_R1: post-HLC R1 thrust, old HLC torque.
% B. R1_REMAP0: same R1 thrust and correctly remapped torque via Vfd(1),
%    but original higher virtual-input components left unchanged.
% C. R1_D1_DELTA: correct only derivative of R1 additive virtual-input
%    change along the CURRENT physical vector field. Nominal Vfd(2:6)
%    remain source-generated and are not incorrectly overwritten with
%    physical Lie derivatives (V60 D1_LIE flaw).
% All branches are diagnostics, NOT certified 4-input CBF controls.
% ========================================================================
function out=v60InputDerivativeSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
    abs(opts.dt-0.025)<1e-12,'CBF:V60Protocol', ...
    'V61 must match V57/V58: V11_19/R193/25ms');
assert(abs(opts.v60StartTime-2.125)<1e-12 && ...
    opts.v60Horizon>0 && ...
    abs(round(opts.v60Horizon/opts.dt)*opts.dt-opts.v60Horizon)<1e-10, ...
    'CBF:V60Times');
assert(all(opts.v60JetOmegas>0) && all(isfinite(opts.v60JetOmegas)), ...
    'CBF:V60JetOmega');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,source]=v40GetV19PreInterventionState(sc,opts,opts.v60StartTime);
assert(numel(x0)==19 && all(isfinite(x0)),'CBF:V61X0');
sc.x0=x0(:);
v23WriteText(fullfile(work,'V61_INITIAL_STATE_PROVENANCE.txt'),source);
s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
% No 4-input fictional simultaneous instantaneous authority; only true
% nonlinear plant applies the four physically bounded inputs.
% JET6 excluded: smooth zero-initialized correction cannot meet a newly
% active hard-R1 constraint instantaneously. Compare three causal approaches
% and a no-CBF reference only; avoid unsupported extra branches.
modes={'NOMINAL','ORIGINAL_R1','R1_REMAP0','R1_D1_DELTA'};
cols={'caseID','mode','status','lastTime_s','nSamples', ...
 'firstCBFIntervention_s','firstRawThrustNegative_s', ...
 'firstRawTorqueExceeds1_s','minHlcRawThrust_N', ...
 'maxHlcRawTorque_Nm','maxCorrectedRawTorque_Nm', ...
 'maxAppliedTorque_Nm','maxRawAppliedGap_N','maxR1AppliedInputGap_N', ...
 'maxBetaCondition','minCorrectedBetaSigma','minTension_N', ...
 'minCableH','maxPositionError_m','minR1Residual', ...
 'nR1Violated','nTorqueSaturated','nThrustSaturated', ...
 'maxD1FixedPointResidual','maxNominalDerivativeMismatch','maxJetDerivative5','runtimeError'};
rows=cell(numel(modes),numel(cols));bad=0;runtime=0;r1stop=0;
for jj=1:numel(modes)
  mode=modes{jj};omega=NaN;
  if startsWith(mode,'JET6_')
     omega=opts.v60JetOmegas(jj-4);
  end
  try
    [T,M]=v60One(sc,opts,H,lo,hi,mode,omega);
    writetable(T,fullfile(work,['V61_TRACE_' mode '.csv']));
    if ~strcmp(M.status,'COMPLETE_DIAGNOSTIC')
       bad=bad+1;
       if startsWith(M.status,'R1_'),r1stop=r1stop+1;end
    end
    rows(jj,:)={mode,mode,M.status,M.lastTime,height(T), ...
      v56First(T.time_s,abs(T.appliedThrust_N-T.nominalClippedThrust_N)>1e-7), ...
      v56First(T.time_s,T.hlcRawThrust_N<0), ...
      v56First(T.time_s,T.hlcRawTorqueInf_Nm>1), ...
      min(T.hlcRawThrust_N),max(T.hlcRawTorqueInf_Nm), ...
      max(T.correctedRawTorqueInf_Nm),max(T.appliedTorqueInf_Nm), ...
      max(abs(T.hlcRawThrust_N-T.appliedThrust_N)), ...
      max(abs(T.r1RequestedThrust_N-T.appliedThrust_N)), ...
      max(T.betaCond),min(T.correctedSigmaMin), ...
      min(T.tension_N),min(T.cableH),max(T.positionError_m), ...
      min(T.r1Residual),sum(T.r1Residual < -1e-7), ...
      sum(T.torqueSaturated),sum(T.thrustSaturated), ...
      v60FiniteMax(abs(T.d1MinusMeasuredLie)), ...
      v60FiniteMax(abs(T.nominalDerivativeMismatch)), ...
      v60FiniteMax(abs(T.jetDerivative5)),''};
  catch ME
    bad=bad+1;runtime=runtime+1;
    v23WriteText(fullfile(work,['V61_ERROR_' mode '.txt']), ...
        getReport(ME,'extended','hyperlinks','off'));
    rows(jj,:)={mode,mode,['MATLAB_ERROR_' ME.identifier], ...
        NaN,0,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN, ...
        NaN,NaN,NaN,NaN,NaN,0,0,0,NaN,NaN,NaN,ME.message};
  end
end
writetable(cell2table(rows,'VariableNames',cols), ...
    fullfile(work,'V61_DELTA_DERIVATIVE_COMPARISON_SUMMARY.csv'));
out=struct('nCases',numel(modes),'nFailedCases',bad, ...
 'nRuntimeErrors',runtime,'nR1FilterStops',r1stop);
end

function [T,M]=v60One(sc,opts,H,lo,hi,mode,omega)
headers={'time_s','loadZ_m','loadVz_mps','hlcRawThrust_N', ...
 'nominalClippedThrust_N','r1RequestedThrust_N','appliedThrust_N', ...
 'hlcRawTorqueInf_Nm','correctedRawTorqueInf_Nm', ...
 'appliedTorqueInf_Nm','betaCond','correctedSigmaMin', ...
 'equivalentV1','nominalV1','equivalentD1', ...
 'localLieD1','d1MinusMeasuredLie','nominalDerivativeMismatch', ...
 'vfDerivative2','vfDerivative3','vfDerivative4','vfDerivative5', ...
 'jetDerivative5', ...
 'r1Residual','r1MinHR','r1Status','cableH','tension_N', ...
 'positionError_m','torqueSaturated','thrustSaturated', ...
 'mappingThrustResidual_N','jetTargetDeltaV1','jetStateZ1', ...
 'referenceVerticalError_m'};
K=round(opts.v60Horizon/opts.dt);R=cell(K+1,numel(headers));n=0;
x=sc.x0(:);z=zeros(6,1);M=struct('status','COMPLETE_DIAGNOSTIC', ...
 'lastTime',opts.v60StartTime);
s=sc.settings;
for k=0:K
  t=opts.v60StartTime+k*opts.dt;
  a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
  if ~all(isfinite([a.raw(:);a.beta(:);a.alpha(:)])) || ...
     a.betaRcond<1e-14
      M.status='HLC_NONFINITE_OR_BETA_SINGULAR';break;
  end
  nominal=min(hi,max(lo,a.raw));
  [r1,r1Status]=v25R1ExactFilter(x,s,sc.obstacles,nominal);
  if ~strcmp(r1Status,'OK') && ~strcmp(mode,'NOMINAL')
     M.status=['R1_FILTER_STOP_' r1Status];
     % Preserve state even at infeasible time: no invented applied input.
     M.lastTime=t;break;
  end
  raw=a.raw;
  vf=a.vfRaw(:).';d1=NaN;localLie=NaN;jetTarget=NaN;
  beta=a.beta;
  if strcmp(mode,'NOMINAL')
      u=nominal;
  elseif strcmp(mode,'ORIGINAL_R1')
      u=r1;
  elseif strcmp(mode,'R1_REMAP0') || strcmp(mode,'R1_D1_DELTA')
      vf=v60EquivalentV1(a,r1(1));
      if strcmp(mode,'R1_D1_DELTA')
          % Torque alters the true vector field used in the Lie derivative.
          % Iterate torque and first derivative until jointly consistent.
          tauGuess=r1(2:4);converged=false;d1=NaN;localLie=NaN;
          for iter=1:8
              [deltaDot,~]=v61LocalLieDelta(x,t,sc,H,opts,[r1(1);tauGuess]);
              if ~isfinite(deltaDot),break;end
              d1=a.vfRaw(2)+deltaDot;
              vf(2)=d1;
              [raw,beta]=v60MappedInput(x,a,vf,H);
              if any(~isfinite(raw)),break;end
              tauNext=max(lo(2:4),min(hi(2:4),raw(2:4)));
              if norm(tauNext-tauGuess,Inf)<1e-7
                  converged=true;tauGuess=tauNext;break;
              end
              tauGuess=tauNext;
          end
          if ~converged
              M.status='DELTA_ACTIVE_SET_OR_TORQUE_FIXED_POINT_FAILED';
              M.lastTime=t;break;
          end
          [localDeltaDot,~]=v61LocalLieDelta(x,t,sc,H,opts,[r1(1);tauGuess]);
          localLie=a.vfRaw(2)+localDeltaDot;
          if ~isfinite(localLie)
              M.status='DELTA_LIE_RECHECK_FAILED';M.lastTime=t;break;
          end
          vf(2)=d1;
      end
      [raw,beta]=v60MappedInput(x,a,vf,H);
      % Physical thrust MUST agree with original EXACT R1, otherwise reject.
      if abs(raw(1)-r1(1))>1e-7*max(1,abs(r1(1)))
         M.status='THRUST_MAP_RECONSTRUCTION_FAILURE';M.lastTime=t;break;
      end
      u=[r1(1);max(lo(2:4),min(hi(2:4),raw(2:4)))];
  else
      % Cascaded integrator z1'=z2,...z5'=z6. Only additive z(t) is
      % jet coherent. This mode does NOT claim full closed-loop HLC jet
      % consistency or R1 safety before the filter can react.
      jetTarget=(r1(1)-a.raw(1))*a.thrustDenominator/ ...
           (a.HLCparam(1)+a.HLCparam(6));
      vf=vf+z.';
      [raw,beta]=v60MappedInput(x,a,vf,H);
      u=max(lo,min(hi,raw));
  end
  if any(~isfinite([u(:);raw(:);vf(:);beta(:)]))
     M.status=sprintf('CORRECTED_NONFINITE_t%.3f',t);M.lastTime=t;break;
  end
  if rcond(beta)<1e-14
     M.status=sprintf('CORRECTED_BETA_SINGULAR_t%.3f',t);M.lastTime=t;break;
  end
  [minHR,res,~,cbfStatus]=v28R1Audit(x,s,sc.obstacles,u(1));
  ten=v23Tension(x,s,u(1));h=v23CableSafety(x,sc);
  dx=v23RHS(x,u,s);
  physicalD1=H.F1(1)*(a.refVel(3)-x(13))+ ...
             H.F1(2)*(a.refAcc(3)-dx(13));
  nominalDerivativeMismatch=a.vfRaw(2)-physicalD1;
  n=n+1;
  sig=min(svd(beta));
  if ~strcmp(mode,'R1_D1_DELTA'),d1=NaN;localLie=NaN;end
  if startsWith(mode,'JET6_'),jet5=z(6);else,jet5=NaN;end
  if strcmp(r1Status,'OK'),r1T=r1(1);else,r1T=NaN;end
  R(n,:)={t,x(10),x(13),a.raw(1),nominal(1),r1T,u(1), ...
     norm(a.tau,Inf),norm(raw(2:4),Inf),norm(u(2:4),Inf), ...
     a.betaCond,sig,vf(1),a.vfRaw(1),vf(2),localLie, ...
     d1-localLie,nominalDerivativeMismatch,vf(3),vf(4),vf(5), ...
     vf(6),jet5,res,minHR,cbfStatus,h,ten,a.posErr, ...
     any(abs(raw(2:4))>hi(2:4)+1e-9), ...
     abs(raw(1)-u(1))>1e-9,raw(1)-u(1),jetTarget,z(1), ...
     a.refPos(3)-x(10)};
  M.lastTime=t;
  if ~isfinite(res) || ~strcmp(cbfStatus,'OK')
    M.status=['R1_AUDIT_ERROR_' cbfStatus];break;
  end
  if strcmp(mode,'ORIGINAL_R1') || strcmp(mode,'R1_REMAP0') || ...
     strcmp(mode,'R1_D1_DELTA')
      if res < -1e-7, M.status='R1_RESIDUAL_FAIL';break;end
  elseif startsWith(mode,'JET6_')
      if res < -1e-7
          M.status='JET6_CBF_VIOLATED_BEFORE_ACTUATION';break;
      end
  end
  if ten<=0, M.status='TENSION_NONPOSITIVE';break;end
  if k==K,break;end
  if startsWith(mode,'JET6_')
      z=v60JetStep(z,jetTarget,omega,opts.dt);
      if any(~isfinite(z)) || any(abs(z)>1e14)
          M.status='JET6_DERIVATIVE_STATE_DIVERGED';break;
      end
  end
  x=v25StepOnce(x,u,s,opts);
  if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
       abs(norm(x(14:16))-1)>1e-3
      M.status='PLANT_NONFINITE_OR_MANIFOLD_FAIL';break;
  end
end
T=cell2table(R(1:n,:),'VariableNames',headers);
end

function vf=v60EquivalentV1(a,T)
mm=a.HLCparam(1)+a.HLCparam(6);
assert(isfinite(mm) && mm>0 && abs(a.thrustDenominator)>1e-8, ...
    'CBF:V60Denominator');
vf=a.vfRaw(:).';
vf(1)=vf(1)+(T-a.raw(1))*a.thrustDenominator/mm;
end

function [raw,beta]=v60MappedInput(x,a,vf,H)
uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf, ...
                       a.HLCparam,H.F2,H.F3,H.F4);
beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
alpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,vs(:),a.HLCparam);
assert(isequal(size(beta),[3 3]) && numel(alpha)==3, ...
 'CBF:V60MappingDimension');
if rcond(beta)<1e-14,raw=nan(4,1);return;end
raw=[uf(1);beta\alpha(:)];
end

function [d1,localD1]=v60LocalLieD1(x,t,sc,H,opts,u)
% Directional derivative of the ACTUAL R1-equivalent virtual scalar
% F(x,t) = Vfd1(x,t) + D(x,t)/(m+mL) (T_R1(x,t)-T_HLC(x,t)).
% Perturb x in +/- direction f(x,u), t in +/- eps. This evaluates local
% Lie derivative at current time, NOT a multistep predicted trajectory.
% At an active-set switch or if R1 becomes infeasible one side, derivative
% is undefined/unusable: explicit stop, no silent substitution.
f=v23RHS(x,u,sc.settings);
eps=1e-4;
vals=zeros(1,2);
for j=1:2
  h=(2*j-3)*eps;
  xx=x+h*f;
  % Keep quaternion and cable unit vector on manifold to O(eps^2).
  xx(1:4)=xx(1:4)/norm(xx(1:4));
  xx(14:16)=xx(14:16)/norm(xx(14:16));
  aa=v23HLC(xx,t+h,sc,H,v23EstimatedMass(opts,t+h));
  nom=min([sc.settings.input.thrustMax;sc.settings.input.torqueMax(:)], ...
          max([sc.settings.input.thrustMin;sc.settings.input.torqueMin(:)],aa.raw));
  [ur,reason]=v25R1ExactFilter(xx,sc.settings,sc.obstacles,nom);
  if ~strcmp(reason,'OK')
      d1=NaN;localD1=NaN;return;
  end
  % The projection onto R1 is only differentiable if the same nominal
  % versus active-constraint regime occurs on BOTH sides of the point.
  regimes(j)=(abs(ur(1)-nom(1))>1e-7); %#ok<AGROW>
  vv=v60EquivalentV1(aa,ur(1));
  vals(j)=vv(1);
end
if regimes(1)~=regimes(2)
    d1=NaN;localD1=NaN;return;
end
localD1=(vals(2)-vals(1))/(2*eps);
d1=localD1;
end

function zNext=v60JetStep(z,target,omega,dt)
% V63 FIX1: Keep the 6-state jet a COLUMN vector through every RK4 stage.
% The ODE coefficients and integration method are unchanged.
z=z(:);
k1=v60JetRHS(z,target,omega);
k2=v60JetRHS(z+dt*k1/2,target,omega);
k3=v60JetRHS(z+dt*k2/2,target,omega);
k4=v60JetRHS(z+dt*k3,target,omega);
zNext=z+dt*(k1+2*k2+2*k3+k4)/6;
end

function dz=v60JetRHS(z,target,omega)
% V63 FIX1: Avoid vertical concatenation of a potentially row-shaped jet.
% No change to the mathematical sixth-order correction dynamics.
z=z(:);
if numel(z)~=6 || ~isscalar(target) || ~isscalar(omega)
    error('CBF:V63JetDimension', ...
      'V63 jet requires six states and scalar target and omega.');
end
dz=zeros(6,1);
dz(1:5)=z(2:6);
dz(6)=omega^6*(target-z(1)) ...
 -6*omega^5*z(2)-15*omega^4*z(3) ...
 -20*omega^3*z(4)-15*omega^2*z(5)-6*omega*z(6);
end

function [deltaDot,regime]=v61LocalLieDelta(x,t,sc,H,opts,u)
% IMPORTANT: derivative of the *ADDITIVE CBF CORRECTION ONLY*, not
% derivative of source Vfd(1). The nominal source Vfd(2:6) remains intact.
% delta(x,t) = D(x)/(m+m_L) * [T_R1(x,t)-T_HLC(x,t)].
% At inactive, interior R1 states delta=0 and dot(delta)=0, exactly.
% R1 hard projection is nonsmooth at active-set switches; abort at kinks.
% Directional derivative uses CURRENT vector field, not predicted trajectory.
f=v23RHS(x,u,sc.settings);
eps=1e-4;
values=zeros(2,1);active=false(2,1);
for j=1:2
    h=(2*j-3)*eps;
    xx=x+h*f;
    xx(1:4)=xx(1:4)/norm(xx(1:4));
    xx(14:16)=xx(14:16)/norm(xx(14:16));
    aa=v23HLC(xx,t+h,sc,H,v23EstimatedMass(opts,t+h));
    lo=[sc.settings.input.thrustMin;sc.settings.input.torqueMin(:)];
    hi=[sc.settings.input.thrustMax;sc.settings.input.torqueMax(:)];
    baseline=max(lo,min(hi,aa.raw));
    [ur,reason]=v25R1ExactFilter(xx,sc.settings,sc.obstacles,baseline);
    if ~strcmp(reason,'OK') || ~isfinite(ur(1))
        deltaDot=NaN;regime='R1_INFEASIBLE_OR_INVALID';return;
    end
    active(j)=(abs(ur(1)-baseline(1))>1e-7);
    equiv=v60EquivalentV1(aa,ur(1));
    values(j)=equiv(1)-aa.vfRaw(1);
end
if active(1)~=active(2)
    deltaDot=NaN;regime='NONDIFFERENTIABLE_ACTIVE_SET';return;
end
regime='DIFFERENTIABLE_LOCAL';
deltaDot=(values(2)-values(1))/(2*eps);
end

function v=v60FiniteMax(z)
z=z(isfinite(z));if isempty(z),v=NaN;else,v=max(z);end
end

function v60WriteHandover(work,opts)
s=sprintf(['V60 INPUT-JET AND HIGHER-DERIVATIVE INTEGRITY STUDY\n', ...
 'R193 source HLC / gains / V19 R1 inequality / V11 19-state plant / physical input limits UNCHANGED.\n', ...
 'Non-predictive; local, current-state operations. NO MPC.\n', ...
 'Baseline: ORIGINAL_R1 post-HLC thrust with nominal torque.\n', ...
 'R1_REMAP0: input coupling through Uf/Beta2/Vs/alpha2 with physical R1 thrust. Higher Vfd slots frozen; NOT a consistent time jet.\n', ...
 'R1_D1_LIE: replace first two Vfd entries by equivalent active R1 virtual scalar and LOCAL physical Lie derivative. Iterate actual torque and f(x,u) to fixed point; if active R1 kink or fixed point fails, STOP.\n', ...
 'Derivatives of orders 2..5 in R1_D1_LIE are still nominal; NOT full high-order consistency. Nondifferentiable active-set boundary reported.\n', ...
 'JET6: six-state critically damped dynamic correction, mathematically dz_i/dt=z_{i+1}; the correction alone is C5.\n', ...
 'JET6 cannot instantaneously achieve hard R1 thrust at activation; its R1 violations are recorded then STOPPED. It is NOT a proposed safety controller.\n', ...
 'Crucial: nominal generated Vfd(2..6) is derived from nominal error dynamics, which need not equal actual time derivatives under CBF. A jet-consistent additive z does NOT cure that.\n', ...
 'Do not mistake a reduced algebraic torque for a feasible/safe closed-loop; inspect R1 residual, tau saturation, tension, raw-vs-actual thrust and all stored Vfd derivatives, every 25 ms.\n', ...
 'Initial V19 R1 pre-intervention state at t2.125, estimated mass=0.01 kg fixed historical R193 value; NOT live flight EKF.\n', ...
 'This V60 does not implement certified 4-input CBF. It isolates the mapping defect before undertaking exact Lie high-order design.\n', ...
 'Input: overwrite one test_CBF_HLC_RootCause.m under common_matlab; run clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath).\n', ...
 'Only timestamped result ZIP in common_matlab/_CBF_TEST_OUTPUT; old results remain.\n', ...
 'V60 start t=%g; horizon=%g; omega=%s\n'], ...
 opts.v60StartTime,opts.v60Horizon,mat2str(opts.v60JetOmegas));
v23WriteText(fullfile(work,'V60_HANDOVER_AND_LIMITATIONS.txt'),s);
end

function v61WriteHandover(work,opts)
lines={ ...
 'V61 NON-PREDICTIVE INCREMENTAL INPUT-COUPLING EXPERIMENT.'; ...
 'Source R193 HLC math and gains, R1 CBF, V11 19-state plant, input limits unchanged.'; ...
 'ORIGINAL_R1: old post-output scalar thrust insertion.'; ...
 'R1_REMAP0: exact applied thrust equivalent in Vfd(1), source Vfd(2:6) untouched.'; ...
 'R1_D1_DELTA: source Vfd(2:6) retained EXCEPT vf(2)=Vfd(2)+Lie(deltaV1).'; ...
 'Lie(deltaV1) finite-differenced locally along physical vector field with actual saturated torque fixed point; nonsmooth active-set boundaries are STOP conditions.'; ...
 'This specifically corrects V60 D1_LIE protocol error: overwriting source Vfd(2) with actual time derivative modified original HLC even without CBF.'; ...
 'Vfd_SuspendedLoadxyDst generated columns are discrete nominal error-dynamics based quantities, not guaranteed actual time derivatives under applied CBF.'; ...
 'Do not treat the derivative of delta only as a full continuous 6-jet: derivatives 2..5 NOT corrected; discontinuity of hard R1 remains.'; ...
 'JET6 intentionally NOT RUN: smooth correction beginning from zero cannot satisfy instant hard R1 step at t2.150 and previous V60 JET code had MATLAB dimensional error.'; ...
 'COMPARE full nonlinear closed-loop, torque saturation, actual thrust, filter feasibility, tension, active-set stop, raw HLC thrust. No safety guarantee.'; ...
 'Single-file overwrite common_matlab/test_CBF_HLC_RootCause.m. Execute clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath);'; ...
 'Results ZIP only in common_matlab/_CBF_TEST_OUTPUT; historical ZIPs preserved.'; ...
 sprintf('initial t=%.3f sec, horizon=%.3f sec, dt=%.3f sec',opts.v60StartTime,opts.v60Horizon,opts.dt)};
v23WriteText(fullfile(work,'V61_METHOD_AND_FULL_HANDOVER.txt'),strjoin(lines,newline));
end


% ========================================================================
% V62.  HARD R1 CBF FORCE => EQUIVALENT DELTA V1 => CAUSAL FD JET AUDIT.
%
% R193 HLC and original scalar R1 law are NOT MODIFIED.  No MPC, no
% prediction, no artificial constraint relaxation or different gain.
%
% For the hard projection, deltaV1(t_k) is not generally differentiable;
% backward differences are DISCRETE-TIME estimates, NOT exact derivatives.
% At an active-set jump of the R1 solution, exact smooth jet is undefined.
% SHADOW = all orders run the SAME original-R1 physical states; recomputed
% torque is observed only. CLOSED = physically applied mapped torque clipped
% to +/-1 Nm while the EXACT hard-R1 thrust is applied. Logs must not
% call these modes safe until an independently valid 4-input CBF exists.
% ========================================================================
function out=v62ThrustDerivativeSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
    abs(opts.dt-0.025)<1e-12,'CBF:V62Protocol', ...
    'V62 requires original V11_19/R193/25ms');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,source]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x0)==19 && all(isfinite(x0)),'CBF:V62State');
sc.x0=x0(:);s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
v23WriteText(fullfile(work,'V62_INITIAL_STATE_PROVENANCE.txt'),source);
modeList={'SHADOW','CLOSED'};kEnd=round(.55/opts.dt);
cols={'mode','order','status','lastTime_s','nSamples','minRawHLCThrust_N',...
 'maxMappedRawTorque_Nm','maxAppliedTorque_Nm','maxDeltaV1',...
 'maxAbsD1','maxAbsD2','maxAbsD3','maxAbsD4',...
 'firstTorqueSaturation_s','firstRawHLCNegative_s','minR1Residual',...
 'minTension_N','maxPositionError_m','minBetaSigma','maxThrustMapError_N',...
 'nTorqueSaturation','nR1Violations','exception'};
rows=cell(numel(modeList)*5,numel(cols));j=0;runtime=0;failed=0;r1Stops=0;
for modeNo=1:2
 for order=0:4
  j=j+1;mode=modeList{modeNo};
  try
   [trace,stat]=v62One(sc,opts,H,lo,hi,mode,order,kEnd);
   writetable(trace,fullfile(work,sprintf('V62_TRACE_%s_D%d.csv',mode,order)));
   failed=failed+~strcmp(stat.status,'COMPLETE_DIAGNOSTIC');
   r1Stops=r1Stops+startsWith(stat.status,'R1_FILTER_STOP');
   rows(j,:)={mode,order,stat.status,stat.lastTime,height(trace),...
    v62ColMin(trace,'hlcRawThrust_N'),v62ColMax(trace,'mappedRawTorque_Nm'),...
    v62ColMax(trace,'appliedTorque_Nm'),v62ColMaxAbs(trace,'deltaV1'),...
    v62ColMaxAbs(trace,'d1'),v62ColMaxAbs(trace,'d2'),...
    v62ColMaxAbs(trace,'d3'),v62ColMaxAbs(trace,'d4'),...
    v62First(trace,'time_s','torqueSaturated'),...
    v62FirstNegative(trace,'time_s','hlcRawThrust_N'),...
    v62ColMin(trace,'r1Residual'),v62ColMin(trace,'tension_N'),...
    v62ColMax(trace,'positionError_m'),v62ColMin(trace,'betaSigma'),...
    v62ColMaxAbs(trace,'mapThrustError_N'),...
    v62Count(trace,'torqueSaturated'),v62CountNegative(trace,'r1Residual'),''};
  catch ME
   runtime=runtime+1;failed=failed+1;
   v23WriteText(fullfile(work,sprintf('V62_ERROR_%s_D%d.txt',mode,order)),...
      getReport(ME,'extended','hyperlinks','off'));
   rows(j,:)={mode,order,['MATLAB_ERROR_' ME.identifier],NaN,0,...
       NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,...
       NaN,NaN,NaN,NaN,NaN,0,0,ME.message};
  end
 end
end
summary=cell2table(rows,'VariableNames',cols);
writetable(summary,fullfile(work,'V62_THRUST_DERIVATIVE_COMPARISON.csv'));
out=struct('nCases',j,'nFailedCases',failed,'nRuntimeErrors',runtime,...
 'nR1FilterStops',r1Stops);
end

function [T,M]=v62One(sc,opts,H,lo,hi,mode,order,K)
headers={'time_s','mode','order','hlcRawThrust_N','r1Thrust_N',...
 'appliedThrust_N','nominalV1','deltaV1','d1','d2','d3','d4',...
 'hlcRawTorque_Nm','mappedRawTorque_Nm','appliedTorque_Nm',...
 'torqueSaturated','betaSigma','mapThrustError_N','r1Residual',...
 'tension_N','positionError_m','loadVz_mps','correctionActive',...
 'activeSetChanged','derivativeFinite','thrustGap_N'};
R=cell(K+1,numel(headers));count=0;x=sc.x0(:);
previousDelta=zeros(1,4);previousActive=false;
M=struct('status','COMPLETE_DIAGNOSTIC','lastTime',2.125);
s=sc.settings;
for k=0:K
  t=2.125+k*opts.dt;
  a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
  if ~all(isfinite([a.raw(:);a.beta(:);a.alpha(:)])) || a.betaRcond<1e-14
      M.status=sprintf('NOMINAL_HLC_INVALID_t%.3f',t);M.lastTime=t;break;
  end
  nominal=min(hi,max(lo,a.raw));
  [r1,r1Status]=v25R1ExactFilter(x,s,sc.obstacles,nominal);
  if ~strcmp(r1Status,'OK')
      M.status=['R1_FILTER_STOP_' r1Status];M.lastTime=t;break;
  end
  equiv=v60EquivalentV1(a,r1(1));
  delta=equiv(1)-a.vfRaw(1);
  active=(abs(r1(1)-nominal(1))>1e-7);
  changed=(k>0 && (active~=previousActive));
  samples=[delta,previousDelta];
  d=nan(1,4);vf=equiv;
  for j=1:order
      coefficients=zeros(1,j+1);
      for q=0:j
         coefficients(q+1)=(-1)^q*nchoosek(j,q);
      end
      d(j)=sum(coefficients.*samples(1:j+1))/opts.dt^j;
      vf(j+1)=a.vfRaw(j+1)+d(j);
  end
  finiteD=d(isfinite(d));
  if isempty(finiteD),largestD=0;else,largestD=max(abs(finiteD));end
  if any(~isfinite(vf)) || largestD>1e11
      M.status=sprintf('DERIVATIVE_NUMERIC_GUARD_t%.3f',t);M.lastTime=t;break;
  end
  [mapped,beta]=v60MappedInput(x,a,vf,H);
  if any(~isfinite(mapped(:))) || any(~isfinite(beta(:))) || rcond(beta)<1e-14
      M.status=sprintf('CORRECTED_MAP_INVALID_t%.3f',t);M.lastTime=t;break;
  end
  mapError=mapped(1)-r1(1);
  if abs(mapError)>1e-7*max(1,abs(r1(1)))
      M.status=sprintf('THRUST_RECONSTRUCTION_FAILURE_t%.3f',t);
      M.lastTime=t;break;
  end
  % SHADOW and CLOSED share the same exact R1 thrust at each timestep.
  % SHADOW uses ORIGINAL-R1 nominal torque for plant propagation.
  if strcmp(mode,'SHADOW')
      u=r1;
  else
      u=[r1(1);max(lo(2:4),min(hi(2:4),mapped(2:4)))];
  end
  [~,res,~,cbfStatus]=v28R1Audit(x,s,sc.obstacles,u(1));
  if ~strcmp(cbfStatus,'OK') || ~isfinite(res)
      M.status=sprintf('R1_AUDIT_ERROR_t%.3f',t);M.lastTime=t;break;
  end
  ten=v23Tension(x,s,u(1));
  count=count+1;
  torqueSaturated=(any(abs(mapped(2:4))>hi(2:4)+1e-9));
  R(count,:)={t,mode,order,a.raw(1),r1(1),u(1),a.vfRaw(1),...
     delta,d(1),d(2),d(3),d(4),norm(a.tau,Inf),...
     norm(mapped(2:4),Inf),norm(u(2:4),Inf),...
     torqueSaturated,min(svd(beta)),mapError,res,ten,a.posErr,...
     x(13),active,changed,all(isfinite(d(1:order))),r1(1)-a.raw(1)};
  M.lastTime=t;
  if res < -1e-7
      M.status=sprintf('R1_CONSTRAINT_VIOLATED_t%.3f',t);break;
  end
  if ~isfinite(ten) || ten<=0
      M.status=sprintf('TENSION_NONPOSITIVE_t%.3f',t);break;
  end
  if k==K,break;end
  % Values recorded prior to stepping.  History is strictly causal.
  previousDelta=[delta,previousDelta(1:3)];
  previousActive=active;
  x=v25StepOnce(x,u,s,opts);
  if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
      abs(norm(x(14:16))-1)>1e-3
      M.status=sprintf('PHYSICAL_PLANT_INVALID_t%.3f',t+opts.dt);break;
  end
end
T=cell2table(R(1:count,:),'VariableNames',headers);
end

function x=v62ColMax(T,name)
if isempty(T) || height(T)==0,x=NaN;return;end
v=T.(name);v=v(isfinite(v));
if isempty(v),x=NaN;else,x=max(v);end
end
function x=v62ColMin(T,name)
if isempty(T) || height(T)==0,x=NaN;return;end
v=T.(name);v=v(isfinite(v));
if isempty(v),x=NaN;else,x=min(v);end
end
function x=v62ColMaxAbs(T,name)
if isempty(T) || height(T)==0,x=NaN;return;end
v=T.(name);v=v(isfinite(v));
if isempty(v),x=NaN;else,x=max(abs(v));end
end
function x=v62First(T,tname,name)
x=NaN;
if isempty(T) || height(T)==0,return;end
ix=find(T.(name),1,'first');if ~isempty(ix),v=T.(tname);x=v(ix);end
end
function x=v62FirstNegative(T,tname,name)
x=NaN;
if isempty(T) || height(T)==0,return;end
ix=find(T.(name)<0,1,'first');if ~isempty(ix),v=T.(tname);x=v(ix);end
end
function x=v62Count(T,name)
if isempty(T),x=0;else,x=sum(T.(name)~=0);end
end
function x=v62CountNegative(T,name)
if isempty(T),x=0;else,x=sum(T.(name)<-1e-7);end
end

function v62WriteHandover(work,opts)
% Compose the historical handover and new experiment records in ONE text.
base=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(base),old=fileread(base);else,old='HISTORICAL HANDOVER NOT FOUND';end
s=fullfile(work,'V62_THRUST_DERIVATIVE_COMPARISON.csv');
if isfile(s),tableText=fileread(s);else,tableText='V62 SUMMARY NOT FOUND';end
add=sprintf(['\n\n===== V60--V62 CONSOLIDATED CURRENT HANDOVER 2026-11-17 =====\n',...
 'SOURCE HLC: R193 generated Vfd(1..6), Uf uses 0, Beta2 uses 0, Vs uses 0..3, alpha2 uses 0..4 of v1. v2..4 separately computed.\n',...
 'PHYSICAL LIMITS T=0..20 N, |tau_j|<=1 Nm. Plant V11_19, dt=0.025, t0=2.125; fixed 0.01 kg historical mass estimate (not live EKF).\n',...
 'V57 ORIGINAL R1 at t2.300: raw T 0.415 N, applied 13.502 N, raw tau 135.229 Nm; at t2.325 raw T -2.723 N, applied 16.448 N; t2.350 R1 asks >=27.93 N >20 N.\n',...
 'V58 withdrawing R1 at t2.325: raw HLC negative thrust clips to zero; cable tension approaches 0.00049 N. Exit from R1 is not safe just because barrier becomes inactive.\n',...
 'V60/V61 REMAP0: replace ONLY v1(0) with exact R1 applied thrust equivalent, recompute Vs/Beta2/alpha2. t2.300 raw tau 33.184 Nm but remapped tau 0.035 Nm, raw T 0.807 N; stopped t2.325 NONFINITE.\n',...
 'V61 D1_DELTA: source Vfd(2) PLUS Lie derivative of additive correction only, source 2..5 unchanged. Max remapped tau 5.824 Nm, first negative HLC T -1.348 N at t2.400, R1 infeasible t2.425. This is NOT full derivative consistency.\n',...
 'V62 NEW: causal backward differences (orders 1..4) of deltaV1=D/(m+mL)*(T_R1-T_HLC), including state-dependent D. All derivative corrections ADDED to original source Vfd(j+1); then recalculate Vs,Beta2,alpha2. Fifth derivative is generated by source but not directly used in present map.\n',...
 'V62 SHADOW: original R1 physical trajectory unchanged; torque of each derivative order is computed but NOT APPLIED. This isolates state-independent algebraic effect.\n',...
 'V62 CLOSED: same R1 thrust; recomputed torque CLIPPED to the same +/-1 Nm physical limits and applied.  All diagnostics stop honestly on infeasible R1, invalid inversion, nonpositive tension.\n',...
 'CRITICAL LIMIT: backward FD at hard R1 switches is NOT the mathematically existing continuous-time derivative; R1 can be non-smooth. Jump at 2.150 creates expected FD d1~170.8, d2~6.83e3, d3~2.73e5, d4~1.09e7. A true C4 correction cannot achieve a nonzero instantaneous jump from zero.\n',...
 'No smoothing, MPC or replacement of source HLC is silently made. High derivatives from 25ms sampling are an intentionally stress-test DIAGNOSTIC, NOT a proposed safe controller or certified HOCBF.\n',...
 'NEXT DESIGN QUESTIONS: smooth actual 4-input CBF correction that respects all physical bounds, input coupling and higher-order differentiability; prevent raw HLC thrust collapse; verify feasibility and termination recovery. Discuss BEFORE program redesign.\n',...
 'RUN: overwrite ONLY common_matlab/test_CBF_HLC_RootCause.m; clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath);\n',...
 'RESULT OUTPUT: only timestamped ZIP in common_matlab/_CBF_TEST_OUTPUT; past ZIPs preserved.\n',...
 '===== V62 RESULTS (read actual executed status; not certified) =====\n%s\n'],tableText);
v23WriteText(fullfile(work,'V62_FULL_UPDATED_HANDOVER.txt'),[old add]);
end


% ========================================================================
% V63: PURELY CAUSAL C5 ADDITIVE JET, NOT A 4-INPUT CBF OR MPC.
% xdot: suspended-load plant; z0..z5=delta v1 and its five derivatives.
% z0'=z1, ..., z4'=z5, z5'=nu.  A bounded-frequency sixth-order
% tracking dynamics supplies nu; NO backward differences and NO reset
% or jump of z0..z5 at CBF activation/deactivation.
%
% IMPORTANT: the nominal source Vfd(2..6) are generated quantities, not
% verified true physical derivatives under CBF; this ensures the ADDITIVE
% jet relationship only. CBF hard thrust target cannot be instantaneously
% matched by a continuous z0.  In SHADOW, exact R1 is applied and smooth
% input map is NOT applied.  In CLOSED_AUDIT, smooth map is applied within
% actuator clipping, and R1 residual is audited/recorded, NEVER asserted
% safe. If the rectified set hR becomes negative, stop and mark UNSAFE.
% ========================================================================
function out=v63SmoothCorrectionSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
 abs(opts.dt-0.025)<1e-12,'CBF:V63Protocol', ...
 'V63 requires V11_19/R193/25ms historical diagnostic');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,origin]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x0)==19 && all(isfinite(x0)),'CBF:V63State');
sc.x0=x0(:);s=sc.settings;H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
v23WriteText(fullfile(work,'V63_INITIAL_STATE_PROVENANCE.txt'),origin);
omegas=opts.v63JetOmegas(:).';
assert(all(isfinite(omegas)) && all(omegas>0) && ...
  numel(omegas)<=8,'CBF:V63Omega');
K=round(opts.v63Horizon/opts.dt);
modes={'SHADOW_R1','CLOSED_UNSAFE_AUDIT'};
cols={'mode','omega','status','nSamples','lastTime_s', ...
 'maxAbsJetD1','maxAbsJetD2','maxAbsJetD3', ...
 'maxAbsJetD4','maxAbsJetD5','maxRawMappedTorque_Nm', ...
 'maxAppliedTorque_Nm','nTorqueSaturations','minNominalHLCThrust_N', ...
 'minAppliedThrust_N','maxAbsR1ThrustGap_N', ...
 'minR1Residual','nR1ViolationSamples','firstR1Violation_s', ...
 'minRectifiedH','minTension_N','maxPositionError_m', ...
 'minMappedBetaSigma','nActuatorClips','exception'};
rows=cell(numel(modes)*numel(omegas),numel(cols));index=0;
errCount=0;failCount=0;filterStops=0;
for m=1:numel(modes)
 for j=1:numel(omegas)
  index=index+1;mode=modes{m};omega=omegas(j);
  try
   [trace,stat]=v63One(sc,opts,H,lo,hi,mode,omega,K);
   writetable(trace,fullfile(work,sprintf('V63_TRACE_%s_W%g.csv',mode,omega)));
   if strcmp(stat.status,'COMPLETE_AUDIT_NOT_CERTIFIED') && ...
      height(trace)>0 && any(trace.r1Violated)
       stat.status='R1_RESIDUAL_VIOLATIONS_UNSAFE';
   end
   failCount=failCount+~strcmp(stat.status,'COMPLETE_AUDIT_NOT_CERTIFIED');
   filterStops=filterStops+startsWith(stat.status,'R1_FILTER_STOP_');
   rows(index,:)={mode,omega,stat.status,height(trace),stat.lastTime, ...
     v62ColMaxAbs(trace,'jetD1'),v62ColMaxAbs(trace,'jetD2'), ...
     v62ColMaxAbs(trace,'jetD3'),v62ColMaxAbs(trace,'jetD4'), ...
     v62ColMaxAbs(trace,'jetD5'),v62ColMax(trace,'mappedTorqueInf_Nm'), ...
     v62ColMax(trace,'appliedTorqueInf_Nm'),v62Count(trace,'torqueSaturated'), ...
     v62ColMin(trace,'rawHLCThrust_N'),v62ColMin(trace,'appliedThrust_N'), ...
     v62ColMaxAbs(trace,'gapToRequiredR1_N'), ...
     v62ColMin(trace,'r1Residual'),v62Count(trace,'r1Violated'), ...
     v62First(trace,'time_s','r1Violated'),v62ColMin(trace,'minRectifiedH'), ...
     v62ColMin(trace,'tension_N'),v62ColMax(trace,'positionError_m'), ...
     v62ColMin(trace,'betaSigma'),v62Count(trace,'actuatorClipped'),''};
  catch ME
   errCount=errCount+1;failCount=failCount+1;
   v23WriteText(fullfile(work,sprintf('V63_ERROR_%s_W%g.txt',mode,omega)), ...
     getReport(ME,'extended','hyperlinks','off'));
   rows(index,:)={mode,omega,['MATLAB_ERROR_' ME.identifier],0,NaN, ...
       NaN,NaN,NaN,NaN,NaN,NaN,NaN,0,NaN,NaN,NaN,NaN,0,NaN,NaN,...
       NaN,NaN,NaN,0,ME.message};
  end
 end
end
summary=cell2table(rows,'VariableNames',cols);
writetable(summary,fullfile(work,'V63_SMOOTH_JET_COMPARISON.csv'));
out=struct('nCases',index,'nFailedCases',failCount, ...
    'nRuntimeErrors',errCount,'nR1FilterStops',filterStops);
end

function [trace,stat]=v63One(sc,opts,H,lo,hi,mode,omega,K)
fields={'time_s','mode','omega','rawHLCThrust_N','requiredR1Thrust_N', ...
 'mappedThrust_N','appliedThrust_N','rawHLCTorqueInf_Nm', ...
 'remap0TorqueInf_Nm','mappedTorqueInf_Nm','appliedTorqueInf_Nm', ...
 'jetTarget','jetD0','jetD1','jetD2','jetD3','jetD4','jetD5', ...
 'jetTargetError','jetDerivativeIdentityResidual', ...
 'gapToRequiredR1_N','r1Residual','minRectifiedH','r1Violated', ...
 'tension_N','positionError_m','loadVz_mps', ...
 'betaSigma','torqueSaturated','actuatorClipped', ...
 'r1Active','mapThrustClip_N'};
record=cell(K+1,numel(fields));n=0;x=sc.x0(:);z=zeros(6,1);
stat=struct('status','COMPLETE_AUDIT_NOT_CERTIFIED','lastTime',2.125);
s=sc.settings;
for k=0:K
 t=2.125+k*opts.dt;
 a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
 if ~all(isfinite([a.raw(:);a.beta(:);a.alpha(:)])) || a.betaRcond<1e-14
   stat.status=sprintf('NOMINAL_HLC_INVALID_t%.3f',t);stat.lastTime=t;break;
 end
 base=max(lo,min(hi,a.raw));
 [required,reason]=v25R1ExactFilter(x,s,sc.obstacles,base);
 if ~strcmp(reason,'OK')
   stat.status=['R1_FILTER_STOP_' reason];stat.lastTime=t;break;
 end
 deltaVF=v60EquivalentV1(a,required(1));
 target=deltaVF(1)-a.vfRaw(1);
 vf=a.vfRaw(:).'+z(:).';
 [mapped,beta]=v60MappedInput(x,a,vf,H);
 if ~all(isfinite([mapped(:);beta(:)])) || rcond(beta)<1e-14
   stat.status=sprintf('JET_MAP_INVALID_t%.3f',t);stat.lastTime=t;break;
 end
 remap=v60EquivalentV1(a,required(1));
 [r0,b0]=v60MappedInput(x,a,remap,H);
 if ~all(isfinite([r0(:);b0(:)]))
    stat.status=sprintf('REMAP0_REFERENCE_INVALID_t%.3f',t);stat.lastTime=t;break;
 end
 % Never inject an inconsistent hard R1 thrust while using smooth-jet torque.
 % SHADOW physically applies the original hard R1 with original HLC torque.
 if strcmp(mode,'SHADOW_R1')
     u=required;
 else
     u=max(lo,min(hi,mapped));
 end
 if ~all(isfinite(u))
   stat.status=sprintf('APPLIED_NONFINITE_t%.3f',t);stat.lastTime=t;break;
 end
 [hR,res,~,audit]=v28R1Audit(x,s,sc.obstacles,u(1));
 if ~strcmp(audit,'OK') || ~all(isfinite([hR;res]))
   stat.status=sprintf('R1_AUDIT_INVALID_t%.3f',t);stat.lastTime=t;break;
 end
 ten=v23Tension(x,s,u(1));
 % The ODE has exact local derivative identities by construction.
 dz=v60JetRHS(z,target,omega);
 identityError=norm(dz(1:5)-z(2:6),Inf);
 n=n+1;
 clipped=~strcmp(mode,'SHADOW_R1') && any(abs(u-mapped)>1e-7);
 saturated=any(abs(mapped(2:4))>hi(2:4)+1e-8);
 violated=(res < -1e-7);
 record(n,:)={t,mode,omega,a.raw(1),required(1),mapped(1),u(1), ...
   norm(a.tau,Inf),norm(r0(2:4),Inf),norm(mapped(2:4),Inf), ...
   norm(u(2:4),Inf),target,z(1),z(2),z(3),z(4),z(5),z(6), ...
   target-z(1),identityError,u(1)-required(1),res,hR,violated, ...
   ten,a.posErr,x(13),min(svd(beta)),saturated,clipped, ...
   (abs(required(1)-base(1))>1e-7),u(1)-mapped(1)};
 stat.lastTime=t;
 if ~isfinite(ten) || ten<=0
   stat.status=sprintf('NONPOSITIVE_TENSION_t%.3f',t);break;
 end
 if hR< -1e-7
   stat.status=sprintf('LEFT_RECTIFIED_SAFE_SET_t%.3f',t);break;
 end
 if k==K,break;end
 % For CLOSED_AUDIT a negative R1 residual is logged explicitly;
 % this is a counterexample, NOT a certified CBF operation.
 zNew=v60JetStep(z,target,omega,opts.dt);
 if ~all(isfinite(zNew)) || any(abs(zNew)>1e12)
     stat.status=sprintf('JET_NUMERIC_GUARD_t%.3f',t);break;
 end
 z=zNew;
 x=v25StepOnce(x,u,s,opts);
 if ~all(isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
       abs(norm(x(14:16))-1)>1e-3
    stat.status=sprintf('PLANT_INVALID_t%.3f',t+opts.dt);break;
 end
end
trace=cell2table(record(1:n,:),'VariableNames',fields);
end

function v63WriteHandover(work,opts)
oldFile=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(oldFile),old=fileread(oldFile);else,old='BASE HISTORY UNAVAILABLE';end
summaryFile=fullfile(work,'V63_SMOOTH_JET_COMPARISON.csv');
if isfile(summaryFile),summary=fileread(summaryFile);else,summary='V63 RESULTS UNAVAILABLE';end
h=[newline newline '===== V63 FULL UPDATE 2026-11-17 =====' newline,...
 'USER DIRECTION: Discuss first, then implement agreed test. Nonpredictive, unchanged R193 source HLC/gains/19-state plant/physical bounds.' newline,...
 'WHY: V60/V61 remap0 reduced R1 torque from ~135 Nm to ~0.035 Nm at 2.300 s, but source raw thrust approached zero and remap closed-loop stopped at 2.325 s.' newline,...
 'V62 SHADOW max torque order D0~1.18 Nm, D1~13.32 Nm, D2~168.71 Nm, D3~844.71 Nm, D4~2001.01 Nm.' newline,...
 'V62 CLOSED maxima D0~0.366 Nm (stopped invalid map t2.325), D1~334.55 Nm, D2~135.44 Nm, D3~657.82 Nm, D4~1921.74 Nm.' newline,...
 'V62 FD derivatives are NOT mathematical derivatives of hard-R1 projection at active-set jumps. True smooth additive corrections cannot jump instantaneously.' newline,...
 'V63 ADDED: Six-state critically damped causal correction jet z0...z5. dz0=z1,dz1=z2,dz2=z3,dz3=z4,dz4=z5,dz5=nu.' newline,...
 'V63 FIX1: Replaced v60JetRHS vertical concatenation with an explicit six-by-one output and normalized z(:) inside RK4. This only repairs a MATLAB dimension mismatch; plant/HLC/CBF/jet dynamics and all gains are unchanged. MATLAB rerun is required.' newline,...
 'nu=omega^6(target-z0)-6 omega^5 z1-15 omega^4 z2-20 omega^3 z3-15 omega^2 z4-6 omega z5.' newline,...
 'target= D(x)/(m+mL)*(T_R1(x)-T_HLC(x)); Vfd_new=Vfd_source+z. Recompute Uf, Vs(v2..4), Beta2, alpha2, 3-torque.' newline,...
 'Target is determined at current sample (causal). RK4 integrates the correction ODE across the sample; no analytic derivative from a sampled step command is claimed.' newline,...
 'SHADOW_R1: physical input = exactly original hard R1, modified mapped torque merely observed; mapped thrust generally differs from applied! No safety claim for the mapped input.' newline,...
 'CLOSED_UNSAFE_AUDIT: smooth mapped four inputs applied and clipped; R1 inequality checked but NOT guaranteed; negative residual is counted as a VIOLATION. Stop when rectified hR<0 or tension nonpositive.' newline,...
 'A C5 smooth correction starting from zero CANNOT meet the abrupt exact R1 intervention at 2.150s; nonzero R1 residual may be a structural infeasibility, NOT a bug.' newline,...
 'MATHEMATICAL LIMIT: Source nominal Vfd(2..6) use generated error dynamics and are not proven true time derivatives along CBF-influenced plant. Only the additive correction jet has guaranteed derivative structure.' newline,...
 'Jet does not itself solve negative raw HLC thrust, hard-R1 feasibility at t2.350 (requires 27.93N>20N), or full four-input high relative degree CBF.' newline,...
 'SHADOW vs CLOSED are counterfactual diagnostics. Neither represents approved flight software or a safety-certified controller.' newline,...
 sprintf('CASE SETTINGS: V11_19 R193, estimated suspended mass 0.01 kg historical initialization, start 2.125 s, dt %.5g s, horizon %.5g s, omegas=%s. No live EKF.',opts.dt,opts.v63Horizon,mat2str(opts.v63JetOmegas)), newline,...
 'DEPLOY: Overwrite one test_CBF_HLC_RootCause.m inside common_matlab; clear test_CBF_HLC_RootCause; rehash; result=test_CBF_HLC_RootCause(); disp(result.status); disp(result.zipPath);' newline,...
 'OUTPUT: timestamped ZIP only in common_matlab/_CBF_TEST_OUTPUT; historical ZIP files preserved.' newline,...
 '===== V63 ACTUAL EXECUTION SUMMARY =====' newline,summary,newline,...
 'NEXT: Interpret the quantitative tradeoff: smooth jet maps vs original REMAP0; raw thrust collapse, actuator clipping, R1 residual. Then discuss feasibility BEFORE a new controller.' newline];
v23WriteText(fullfile(work,'V63_FULL_UPDATED_HANDOVER.txt'),[old h]);
end


% ========================================================================
% V64: LOCAL HIGH-ORDER INPUT STRUCTURE (NONPREDICTIVE)
%
% IMPORTANT: This is an OFFLINE NON-CERTIFIED precondition/audit for a
% 4-input CBF, not a deployed CBF controller. DO NOT apply proposed torques
% or derivative-of-thrust control to flight. No artificial thrust floor,
% thrust smoothing, thrust correction, MPC or future rollout is used.
%
% Plant: x_dot=f19(x,[T; tau]); dynamic thrust extension T_dot=q,
% q_dot=nu.  Extended state y=[x(19);T;q], input w=[nu;tau(3)].
% The obstacle geometric function is identical to v23CableSafety, but
% per-obstacle to avoid a nonsmooth min between obstacles.
%
% Candidate 4th-order CBF for h with verified uniform relative degree 4:
%   c*w + L_F^4 h + 4*l*L_F^3 h + 6*l^2*L_F^2 h
%                    +4*l^3*L_F h + l^4*h >= 0,
%   c_j=L_Gj L_F^3 h.
% THIS INEQUALITY IS NOT VALID if input appears in lower derivatives,
% if numerical convergence fails, or if the needed auxiliary psi_i are
% outside their safe sets. We report authority and *do not apply* w.
% ========================================================================
function out=v64HOCBFStructureSuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
    abs(opts.dt-0.025)<1e-12,'CBF:V64Protocol', ...
    'V64 audit requires original V11_19/R193/25ms conditions');
assert(numel(opts.v64LieSteps)==2 && all(isfinite(opts.v64LieSteps)) ...
   && all(opts.v64LieSteps>0) && ...
   all(isfinite(opts.v64Lambda)) && all(opts.v64Lambda>0), ...
   'CBF:V64Options','Invalid high-order numerical audit configuration');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x,origin]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x)==19 && all(isfinite(x)),'CBF:V64InitialState');
H=v23MakeHLC(sc.settings,opts.dt);s=sc.settings;
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
v23WriteText(fullfile(work,'V64_INITIAL_STATE_PROVENANCE.txt'),origin);
v23WriteText(fullfile(work,'V64_TEST_SCOPE.txt'),[ ...
 'HIGH-ORDER FOUR-CHANNEL INPUT-AUTHORITY AUDIT ONLY. No new thrust policy.' newline ...
 'The source R1 is used ONLY to reach prior historically measured states.' newline ...
 'At snapshots no new controller action is applied; all candidate high-order QP rows are diagnostic.' newline ...
 'The 4th order row is valid ONLY when lower relative-degree input coefficients vanish and finite-difference scales agree.' newline ...
 'nu=Tddot is an extended INPUT, not physical thrust; physical T bounds do not imply a certified nu bound.' newline ...
 'Torque box feasibility is evaluated with nu fixed to zero as an illustrative local projection.' newline]);

times=opts.v64Times(:).';assert(all(diff(times)>0) && ...
 all(times>=2.125-1e-10) && all(times<=2.325+1e-10) && ...
 all(abs((times-2.125)/opts.dt-round((times-2.125)/opts.dt))<1e-7), ...
 'CBF:V64Times','Times must be increasing 25ms grid points in R1 valid interval');
cols={'time_s','obstacleIndex','step_s','status','h0','LfH','Lf2H', ...
 'Lf3H','Lf4H','Gnu_Lf3H','Gtau1_Lf3H','Gtau2_Lf3H', ...
 'Gtau3_Lf3H','maxLowerInputAuthority','numericConvergence', ...
 'physicalThrust_N','rawHLCThrust_N','rawHLCTorqueInf_Nm', ...
 'tauRequested1_Nm','tauRequested2_Nm','tauRequested3_Nm', ...
 'torqueInverseMapError','deltaVsInf','computationSeconds'};
Rows=cell(0,numel(cols));
cf={'time_s','obstacleIndex','lambda','status','nominalResidual', ...
 'bestTorqueOnlyResidual','torqueOnlyFeasible','requiredNuAfterBestTorque', ...
 'physicalThrust_N','HLCSourceTorqueInf_Nm', ...
 'torqueCandidateInf_Nm','mapResidual','deltaVsInf'};
Cases=cell(0,numel(cf));
nMatlabErrors=0;nUnverified=0;stopped=0;
kmax=round((max(times)-2.125)/opts.dt);
prevT=NaN;
for k=0:kmax
    t=2.125+k*opts.dt;
    a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
    if ~all(isfinite(a.raw)) || a.betaRcond<1e-12
        stopped=1;break;
    end
    nominal=max(lo,min(hi,a.raw));
    [u,reason]=v25R1ExactFilter(x,s,sc.obstacles,nominal);
    if ~strcmp(reason,'OK') || ~all(isfinite(u))
        stopped=1;break;
    end
    if any(abs(times-t)<1e-10)
      % Use the existing R1-applied T only to tag observed x; no NEW T policy.
      % q=0 is an explicit initial choice for the local, extended-input
      % authority audit, not a measured physical thrust derivative.
      y=[x(:);u(1);0];
      for j=1:numel(sc.obstacles)
        for hstep=opts.v64LieSteps(:).'
          clock=tic;
          try
            [L,B,lower,affErr]=v64LocalHOCBFCoeffs(y,sc,j,hstep);
            r=[norm(B(1,:)),norm(B(2,:)),norm(B(3,:))];
            lowerAuthority=max(r);
            status='FINITE_COEFFICIENTS_NOT_CERTIFIED';
            if any(~isfinite([L(:);B(:);lower(:);affErr])) || affErr>1e-6
                status='NONFINITE_OR_NONAFFINE_LIE_COEFFICIENTS';
                nUnverified=nUnverified+1;
            end
            Rows(end+1,:)={t,j,hstep,status,L(1),L(2),L(3), ...
                L(4),L(5),B(4,1),B(4,2),B(4,3),B(4,4), ...
                lowerAuthority,NaN,u(1),a.raw(1),norm(a.tau,Inf), ...
                a.tau(1),a.tau(2),a.tau(3),NaN,NaN,toc(clock)}; %#ok<AGROW>
          catch ME
            nMatlabErrors=nMatlabErrors+1;
            v23WriteText(fullfile(work,sprintf('V64_ERROR_T%04d_O%d_E%g.txt', ...
                round(t*1000),j,hstep)),getReport(ME,'extended','hyperlinks','off'));
            Rows(end+1,:)={t,j,hstep,['MATLAB_ERROR_' ME.identifier], ...
              NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN,NaN, ...
              u(1),a.raw(1),norm(a.tau,Inf),a.tau(1),a.tau(2),a.tau(3), ...
              NaN,NaN,toc(clock)}; %#ok<AGROW>
          end
        end
        if size(Rows,1)<2 || ~isequal(Rows{end,1},Rows{end-1,1}) || ...
           ~isequal(Rows{end,2},Rows{end-1,2})
           continue;
        end
        r1=Rows(end-1,:);r2=Rows(end,:);
        if ~startsWith(string(r1{4}),'FINITE_') || ...
           ~startsWith(string(r2{4}),'FINITE_'),continue;end
        ell1=cell2mat(r1(5:9));ell2=cell2mat(r2(5:9));
        bb1=cell2mat(r1(10:13));bb2=cell2mat(r2(10:13));
        mismatch=norm([ell1(2:5),bb1]-[ell2(2:5),bb2],Inf) / ...
            max([1,norm([ell1(2:5),bb1],Inf), ...
                   norm([ell2(2:5),bb2],Inf)]);
        Rows{end-1,15}=mismatch;Rows{end,15}=mismatch;
        if mismatch>opts.v64MaxRelativeError || ...
           abs(r1{14})>1e-3*max(1,norm(bb1)) || ...
           abs(r2{14})>1e-3*max(1,norm(bb2))
           Rows{end-1,4}='UNVERIFIED_DERIVATIVE_OR_MIXED_RELATIVE_DEGREE';
           Rows{end,4}=Rows{end-1,4};nUnverified=nUnverified+1;
           continue;
        end
        % Higher-order coefficient is numerical; no safety certificate.
        % Use smaller step and check whether bounded torques at nu=0 can
        % satisfy the local row. This does NOT change physical thrust.
        L=ell1;B=bb1;gammas=opts.v64Lambda(:).';
        for lambda=gammas
          d=L(5)+4*lambda*L(4)+6*lambda^2*L(3)+ ...
            4*lambda^3*L(2)+lambda^4*L(1);
          tauBase=nominal(2:4);C=B(2:4);
          baseResidual=d+C*tauBase; 
          bestTau=lo(2:4);
          bestTau(C>=0)=hi(find(C>=0)+1);
          % previous line indexes bounds by physical channel 2..4.
          bestResidual=d+C*bestTau;
          feasible=(bestResidual>=-1e-8);
          if feasible
            tauCandidate=v64ProjectOneRow(tauBase,C,-d,lo(2:4),hi(2:4));
          else
            tauCandidate=bestTau;
          end
          nuNeed=NaN;
          if d+C*tauCandidate>=-1e-9
            nuNeed=0;
          elseif abs(B(1))>1e-8
            % Equality value for remaining deficit; NOT an applied thrust command.
            nuNeed=(-d-C*tauCandidate)/B(1);
          end
          [mapResidual,deltaVs]=v64HLCVirtualTorqueMap(x,a,H, ...
                 [u(1);tauCandidate]);
          Cases(end+1,:)={t,j,lambda, ...
              'LOCAL_HOCBF_ROW_NOT_CERTIFIED',baseResidual,bestResidual, ...
              feasible,nuNeed,u(1),norm(a.tau,Inf), ...
              norm(tauCandidate,Inf),mapResidual,deltaVs}; %#ok<AGROW>
        end
      end
    end
    if k<kmax
       x=v25StepOnce(x,u,s,opts);
       if any(~isfinite(x)),stopped=1;break;end
    end
    prevT=u(1); %#ok<NASGU>
end
if ~isempty(Rows)
  writetable(cell2table(Rows,'VariableNames',cols), ...
      fullfile(work,'V64_LOCAL_LIE_AUTHORITY.csv'));
end
if ~isempty(Cases)
  writetable(cell2table(Cases,'VariableNames',cf), ...
      fullfile(work,'V64_LOCAL_HOCBF_ROW_FEASIBILITY.csv'));
end
out=struct('nCases',numel(times)*numel(sc.obstacles), ...
   'nFailedCases',nUnverified+stopped+nMatlabErrors,'nRuntimeErrors',nMatlabErrors, ...
   'nR1FilterStops',stopped);
end

function [L,B,lower,affErr]=v64LocalHOCBFCoeffs(y,sc,obsIdx,epsi)
% Pointwise Lie derivatives only: no plant time rollout, no MPC.
% Tangent finite differences are NUMERICAL and must be scale verified.
L=zeros(1,5);B=zeros(4,4);y=y(:);
for ord=0:4
  L(ord+1)=v64LieDrift(y,ord,sc,obsIdx,epsi);
end
f0=v64AugmentedRHS(y,zeros(4,1),sc);
for j=1:4
   w=zeros(4,1);w(j)=1;
   Gj=v64AugmentedRHS(y,w,sc)-f0;
   for ord=0:3
       yp=v64ProjectManifold(y+epsi*Gj);
       ym=v64ProjectManifold(y-epsi*Gj);
       B(ord+1,j)=(v64LieDrift(yp,ord,sc,obsIdx,epsi)- ...
             v64LieDrift(ym,ord,sc,obsIdx,epsi))/(2*epsi);
   end
end
lower=B(1:3,:);
% Test physical vector-field affineness at the CURRENT (extended) state;
% this does not validate the higher Lie stencil by itself.
w=[0.2;0.1;-0.1;0.05];g=zeros(numel(y),4);
for j=1:4
    e=zeros(4,1);e(j)=1;
    g(:,j)=v64AugmentedRHS(y,e,sc)-f0;
end
affErr=norm(v64AugmentedRHS(y,w,sc)-f0-g*w,Inf);
end

function v=v64LieDrift(y,k,sc,obsIdx,epsi)
if k==0
   v=v64SingleObstacleH(y,sc,obsIdx);
   return;
end
f=v64AugmentedRHS(y,zeros(4,1),sc);
yp=v64ProjectManifold(y+epsi*f);
ym=v64ProjectManifold(y-epsi*f);
v=(v64LieDrift(yp,k-1,sc,obsIdx,epsi)- ...
   v64LieDrift(ym,k-1,sc,obsIdx,epsi))/(2*epsi);
end

function d=v64AugmentedRHS(y,w,sc)
% x19, physical thrust T, physical thrust derivative q; w=[nu;tau3].
y=y(:);w=w(:);
assert(numel(y)==21 && numel(w)==4,'CBF:V64Shape');
f=v23RHS(y(1:19),[y(20);w(2:4)],sc.settings);
d=[f(:);y(21);w(1)];
end

function y=v64ProjectManifold(y)
y=y(:);
y(1:4)=y(1:4)/norm(y(1:4));
y(14:16)=y(14:16)/norm(y(14:16));
% preserve tangent cable angular velocity constraint to first order.
y(17:19)=y(17:19)-y(14:16)*(y(14:16).'*y(17:19));
end

function h=v64SingleObstacleH(y,sc,obsIdx)
x=y(1:19);s=sc.settings;L=s.physical.cableLength;
o=sc.obstacles{obsIdx};rc=s.shape.cableRadius;dm=s.cbf.safetyMargin;
a=L/2+rc;b=sqrt(a*rc);q=x(14:16);c=x(8:10)-L*q/2;
d=o.center(:)-c;
sC=sqrt(b^2*(d'*d)+(a*a-b*b)*(d'*q)^2+s.cbf.smoothEpsilon^2);
sO=sqrt(sum((o.axes(:).*(o.R'*d)).^2)+s.cbf.smoothEpsilon^2);
h=d'*d-sC-sO-dm*sqrt(d'*d+s.cbf.smoothEpsilon^2);
end

function tau=v64ProjectOneRow(tau0,c,rhs,lo,hi)
% Euclidean minimum-change projection onto box AND one linear row.
tau0=max(lo(:),min(hi(:),tau0(:)));c=c(:);
if c'*tau0>=rhs-1e-9,tau=tau0;return;end
maximize=lo(:);maximize(c>0)=hi(c>0);
if c'*maximize<rhs-1e-8,tau=maximize;return;end
left=0;right=1;
for k=1:60
   x=max(lo(:),min(hi(:),tau0+right*c));
   if c'*x>=rhs,break;end
   right=right*2;
end
for k=1:60
  mid=(left+right)/2;
  x=max(lo(:),min(hi(:),tau0+mid*c));
  if c'*x>=rhs,right=mid;else,left=mid;end
end
tau=max(lo(:),min(hi(:),tau0+right*c));
end

function [err,dVs]=v64HLCVirtualTorqueMap(x,a,H,u)
% Keep ORIGINAL v1 jet entirely unchanged and audit v2..4 to tau mapping.
% This is physically a mapping snapshot, NOT a C4 correction of thrust.
err=NaN;dVs=NaN;
try
  % For the observed R1-applied physical T, use its zero-order equivalent.
  % Higher nominal Vfd components are fixed: NOT a consistent full jet.
  vf=v60EquivalentV1(a,u(1));
  beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
  if rcond(beta)<1e-12,return;end
  vv=a.vsRaw(:);p=a.HLCparam;
  alpha0=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,vv,p);
  M=zeros(3,3);
  for k=1:3
      vx=vv;vx(k)=vx(k)+1;
      ak=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,vx,p);
      M(:,k)=ak(:)-alpha0(:);
  end
  if rcond(M)<1e-12,return;end
  delta=M\(beta*u(2:4)-alpha0(:));
  aa=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
      x,a.XD,vf,vv+delta,p);
  mapped=beta\aa(:);
  err=norm(mapped-u(2:4),Inf);
  dVs=norm(delta,Inf);
catch
  err=NaN;dVs=NaN;
end
end

function v64HOCBFWriteHandover(work,opts)
p=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(p),old=fileread(p);else,old='V54 history unavailable';end
p=fullfile(work,'V64_LOCAL_LIE_AUTHORITY.csv');
if isfile(p),a=fileread(p);else,a='V64 authority results missing';end
p=fullfile(work,'V64_LOCAL_HOCBF_ROW_FEASIBILITY.csv');
if isfile(p),b=fileread(p);else,b='V64 preliminary feasible rows unavailable';end
note=[newline '===== V64 HIGH-ORDER / FOUR INPUT HANDOVER =====' newline, ...
 'Source: R193 HLC generated Uf/Beta2/Vs/V2_alpha2, existing 19-state V11_19 plant, V19 cable safety geometry.' newline, ...
 'User: prioritize HIGH-ORDER input coupling. Do NOT invent thrust lower floor, ramp, clamp, gain change, or thrust suppression.' newline, ...
 'From V60/V61: remapping only v1(0) can reduce torque but does not restore a full time jet or prevent raw HLC thrust collapse.' newline, ...
 'From V62: backward differences of switched R1 thrust correction produced enormous nonphysical high-order correction values.' newline, ...
 'From V63: continuous six-state derivative chain reduces jump but fails original CBF inequalities because it cannot instantly track R1 thrust demand.' newline, ...
 'V55 interval: at t2.350 required thrust >=27.93 N, while physical limit is 20 N; original R1 is infeasible.' newline, ...
 'V56: nominal smooth descent tracked; static large downward target can produce negative raw thrust; no HLC error inferred.' newline, ...
 'V57: original R1 t2.150 actual thrust 12.17 N vs raw 8.87 N, then t2.300 actual 13.50 N vs raw 0.415 N and raw torque 135.23 Nm.' newline, ...
 'V58: counterfactual releasing original R1 at t2.325 maps raw thrust -2.72 N to actual 0 N and causes near-zero tether tension.' newline, ...
 'V60/V61 REMAP0: t2.300 corrected torque 0.035 Nm, but raw thrust 0.807 N and map later invalid. Delta 1st derivative did not fix negative raw thrust.' newline, ...
 'V62: introducing switched finite-difference correction high derivatives caused 10^2..10^3 Nm torque demands; these samples are not true continuous-time derivatives.' newline, ...
 'V63 REAL RESULTS (rerun 2026-11-17 18:48): SHADOW max mapped torque at omega 8/16/32 = 71.52/297.01/1989.74 Nm; CLOSED max 0.044/0.833/21.66 Nm with 22 R1 inequality violations each.' newline, ...
 'V64 formulation: original 19-state physical system plus T_dot=q, q_dot=nu; w=[nu,tau_x,tau_y,tau_z].' newline, ...
 'At each source R1 state, pointwise Lie derivative authority rows of cable-obstacle h are audited through order 4.' newline, ...
 'We require lower authority to vanish AND two finite-difference scales to agree. If not, STOP construction of that HOCBF row.' newline, ...
 'Candidate (D+lambda)^4 h>=0 is NOT certified. Necessary auxiliary psi_i>=0, recursive feasibility, discretization bounds, 4D input feasibility, tension and ground constraints still need derivation.' newline, ...
 'Physical limits original: thrust 0..20 N, torque axes -1..1 Nm. No bound exists yet for extended virtual nu=Tddot, hence the V64 calculated nu is a diagnostic, not executable.' newline, ...
 'Candidate tau alterations never applied to the plant; only identical ORIGINAL R1 state trajectory is replayed. No closed-loop 4-input safety is claimed.' newline, ...
 'The source nominal v1 jet stays unchanged; map audits tau to v2..4 using Beta2 and alpha2 to check algebraic input consistency.' newline, ...
 'Next: robust Lie/relative-degree derivation including time-varying references, load/body/cable geometry, actuator and tether constraints; once verified, solve the single physical 4-input safety QP.' newline, ...
 '===== V64 RUN OUTPUT =====' newline,a,newline,b];
v23WriteText(fullfile(work,'V64_FULL_UPDATED_HANDOVER.txt'),[old,note]);
end


% ========================================================================
% V65: DIRECT INVERSE-CONSTRAINT INTERVENTION / THRUST NUMERATOR MECHANISM
%
% 1) Preserve the original HLC and all nominal Vf derivative entries.
% 2) Use exactly the ORIGINAL R1 demanded physical thrust (no invented floor
%    or ramp), and convert it to the 0th equivalent v1 BEFORE torque map.
% 3) In the HLC inverse equation, solve for a bounded physical torque by
%    choosing v2..4; no torque clipping AFTER the inverse calculation.
% 4) Integrate the ORIGINAL 19-state plant to compare original-R1 and the
%    direct-mapped correction. Record the true nominal thrust numerator N,
%    its exact along-plant derivative, and direct input causality at fixed x.
%
% CRITICAL LIMIT: The derivatives of modified v1 are NOT made a time jet.
% The unmodified higher Vf entries do not prove high-order consistency.
% Thus this V65 is only a necessary-conditions experiment, NOT a certified
% high-order 4-input CBF and NOT evidence of safe collision avoidance.
% ========================================================================
function out=v65DirectConsistencySuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
 abs(opts.dt-0.025)<1e-12,'CBF:V65Protocol', ...
 'V65 requires exact V11_19/R193 historical 25ms condition');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,origin]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x0)==19 && all(isfinite(x0)),'CBF:V65Prestate');
v23WriteText(fullfile(work,'V65_INITIAL_STATE_PROVENANCE.txt'),origin);
H=v23MakeHLC(sc.settings,opts.dt);
lo=[sc.settings.input.thrustMin;sc.settings.input.torqueMin(:)];
hi=[sc.settings.input.thrustMax;sc.settings.input.torqueMax(:)];
assert(numel(lo)==4 && numel(hi)==4 && all(hi>lo),'CBF:V65Limits');
labels={'HLC_ONLY','ORIGINAL_R1','DIRECT_INVERSE_CONSTRAINT'};
rows=cell(numel(labels),11);bad=0;errs=0;stops=0;
for j=1:numel(labels)
    label=labels{j};
    try
        [trace,stat]=v65DirectOne(sc,opts,H,lo,hi,x0,label);
        writetable(trace,fullfile(work,['V65_TRACE_' label '.csv']));
        if height(trace)>0
           mt=max(trace.mappedRawTorqueInf_Nm);
           ma=max(trace.appliedTorqueInf_Nm);
           minT=min(trace.hlcRawThrust_N);
           minR=min(trace.r1Residual);
           minH=min(trace.cableH);
           minTen=min(trace.tension_N);
           maxVs=max(trace.deltaVsInf);
           nSat=sum(trace.originalMapOverTorqueLimit);
        else
           mt=NaN;ma=NaN;minT=NaN;minR=NaN;minH=NaN;
           minTen=NaN;maxVs=NaN;nSat=NaN;
        end
        rows(j,:)={label,stat.status,stat.lastTime,height(trace), ...
              mt,ma,minT,minR,minH,minTen,maxVs};
        if ~strcmp(stat.status,'COMPLETE_UNCERTIFIED'),bad=bad+1;end
        if startsWith(stat.status,'R1_FILTER_'),stops=stops+1;end
    catch ME
        errs=errs+1;bad=bad+1;
        v23WriteText(fullfile(work,['V65_ERROR_' label '.txt']), ...
          getReport(ME,'extended','hyperlinks','off'));
        rows(j,:)={label,['MATLAB_ERROR_' ME.identifier],NaN,0, ...
                   NaN,NaN,NaN,NaN,NaN,NaN,NaN};
    end
end
summary=cell2table(rows,'VariableNames', ...
 {'mode','status','lastTime_s','samples','maxMappedRawTorque_Nm', ...
 'maxAppliedTorque_Nm','minNominalRawThrust_N', ...
 'minR1Residual','minCableH','minTension_N','maxVirtualVsChange'});
writetable(summary,fullfile(work,'V65_DIRECT_CONSISTENCY_SUMMARY.csv'));
out=struct('nCases',numel(labels),'nFailedCases',bad, ...
 'nRuntimeErrors',errs,'nR1FilterStops',stops);
end

function [trace,stat]=v65DirectOne(sc,opts,H,lo,hi,x0,mode)
fields={'time_s','hlcRawThrust_N','r1Thrust_N','appliedThrust_N', ...
 'hlcRawTorqueInf_Nm','mappedRawTorqueInf_Nm','appliedTorqueInf_Nm', ...
 'nominalV1','mappedV1','deltaV1','nominalDerivativeJet2Inf', ...
 'deltaVsInf','physicalTorqueInverseResidual','physicalThrustInverseResidual', ...
 'betaSigmaMin','originalMapOverTorqueLimit','r1Residual','r1MinHR', ...
 'cableH','tension_N','loadPosZ_m','referenceZ_m','loadVz_mps', ...
 'verticalError_m','verticalVelocityError_mps','thrustDenominator', ...
 'nominalNumerator_N','gravityRefNumerator_N','feedbackPositionNumerator_N', ...
 'feedbackVelocityNumerator_N','cableNumerator_N', ...
 'nominalNumeratorDotUnderApplied_Nps', ...
 'nominalNumeratorDotUnderBase_Nps', ...
 'deltaNominalNumeratorDotCausedByInput_Nps', ...
 'deltaVelocityFeedbackRate_Nps','deltaCableNumeratorRate_Nps', ...
 'zeroRawThrustBoundaryVelocity_mps','deltaV1LocalLieRate', ...
 'deltaV1DerivativeStatus','highOrderV1ConsistencyProven', ...
 'r1Status'};
K=round(.55/opts.dt);R=cell(K+1,numel(fields));n=0;
stat=struct('status','COMPLETE_UNCERTIFIED','lastTime',2.125);
s=sc.settings;x=x0(:);
for k=0:K
 t=2.125+k*opts.dt;
 a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
 if any(~isfinite([a.raw(:);a.beta(:);a.alpha(:)])) || a.betaRcond<1e-12
     stat.status='NOMINAL_INVERSE_INVALID';stat.lastTime=t;break;
 end
 base=max(lo,min(hi,a.raw));
 [r1,reason]=v25R1ExactFilter(x,s,sc.obstacles,base);
 if strcmp(mode,'HLC_ONLY')
     u=base;vf=a.vfRaw(:).';vsDelta=0;
     mappedRaw=a.raw;beta=a.beta;resMap=norm(u(2:4)-a.tau,Inf);
     thrustMapResidual=base(1)-a.raw(1);
 elseif ~strcmp(reason,'OK')
     stat.status=['R1_FILTER_' reason];stat.lastTime=t;break;
 elseif strcmp(mode,'ORIGINAL_R1')
     u=r1;vf=a.vfRaw(:).';vsDelta=0;
     mappedRaw=a.raw;beta=a.beta;
     resMap=norm(u(2:4)-a.tau,Inf);
     thrustMapResidual=u(1)-a.raw(1);
 else
     % Single simultaneous algebraic correction: physical thrust is EXACT
     % R1 value; v1(0) is mapped into the generated HLC inversion.
     vf=v60EquivalentV1(a,r1(1));
     [u,mappedRaw,beta,vsDelta,resMap,thrustMapResidual,status]= ...
         v65SolveBoundedInverse(x,a,H,lo,hi,vf,r1(1));
     if ~strcmp(status,'OK')
         stat.status=['MAP_' status];stat.lastTime=t;break;
     end
 end
 if ~all(isfinite([u(:);mappedRaw(:);beta(:)]))
    stat.status='NONFINITE_INPUT';stat.lastTime=t;break;
 end
 [minHR,res,~,audit]=v28R1Audit(x,s,sc.obstacles,u(1));
 if ~strcmp(audit,'OK') || ~isfinite(res)
   stat.status=['R1_AUDIT_' audit];stat.lastTime=t;break;
 end
 ten=v23Tension(x,s,u(1));h=v23CableSafety(x,sc);
 phys=v23RHS(x,u,s);basePhys=v23RHS(x,base,s);
 [terms,dN]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,phys);
 [~,dNBase]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,basePhys);
 mm=a.HLCparam(1)+a.HLCparam(6);
 feedbackDdot=-mm*H.F1(2)*(phys(13)-basePhys(13));
 cableDdot=(dN-dNBase)-feedbackDdot;
 assert(abs(terms(1)-a.thrustNumerator)<1e-6*max(1,abs(terms(1))), ...
  'CBF:V65SourceNumeratorMismatch');
 zBound=NaN;
 if H.F1(2)>0
     zBound=(H.F1(1)*(a.refPos(3)-x(10)) +a.refAcc(3)+ ...
        a.HLCparam(5)+terms(5)/mm)/H.F1(2)+a.refVel(3);
 end
 deltaDot=NaN;deltaRegime='NOT_A_DIFFERENTIABLE_R1_CORRECTION';
 if ~strcmp(mode,'HLC_ONLY') && strcmp(reason,'OK')
     try
        [deltaDot,deltaRegime]=v61LocalLieDelta(x,t,sc,H,opts,u);
     catch MEder
        deltaRegime=['DERIVATIVE_ERROR_' MEder.identifier];
     end
 end
 if any(~isfinite([ten;h;dN;dNBase;res]))
    stat.status='NONFINITE_DIAGNOSTIC';stat.lastTime=t;break;
 end
 n=n+1;
 R(n,:)={t,a.raw(1),v65SafeR1Thrust(r1,reason),u(1), ...
    norm(a.tau,Inf),norm(mappedRaw(2:4),Inf),norm(u(2:4),Inf), ...
    a.vfRaw(1),vf(1),vf(1)-a.vfRaw(1), ...
    norm(a.vfRaw(2:6),Inf),vsDelta,resMap,thrustMapResidual, ...
    min(svd(beta)),any(abs(mappedRaw(2:4))>hi(2:4)+1e-8), ...
    res,minHR,h,ten,x(10),a.refPos(3),x(13), ...
    a.refPos(3)-x(10),a.refVel(3)-x(13),a.thrustDenominator, ...
    terms(1),terms(2),terms(3),terms(4),terms(5), ...
    dN,dNBase,dN-dNBase,feedbackDdot,cableDdot,zBound, ...
    deltaDot,deltaRegime,false,reason};
 % Even baseline generated Vfd is a DISCRETE nominal design jet.
 % A complete continuous-time high-order correction is NOT certified.
 stat.lastTime=t;
 if ~strcmp(mode,'HLC_ONLY') && res<-1e-7
    stat.status='CBF_RESIDUAL_NEGATIVE';break;
 end
 if ten<=0
    stat.status='TENSION_NONPOSITIVE';break;
 end
 if h < -1e-7
    stat.status='LEFT_RECTIFIED_SAFE_SET';break;
 end
 if k==K,break;end
 x=v25StepOnce(x,u,s,opts);
 if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
     abs(norm(x(14:16))-1)>1e-3
    stat.status='PLANT_MANIFOLD_INVALID';break;
 end
end
trace=cell2table(R(1:n,:),'VariableNames',fields);
end

function z=v65SafeR1Thrust(r,reason)
if strcmp(reason,'OK'),z=r(1);else,z=NaN;end
end

function [u,mapped,beta,vsChange,mapResidual,thrustResidual,status]= ...
    v65SolveBoundedInverse(x,a,H,lo,hi,vf,Tr1)
status='OK';u=nan(4,1);mapped=nan(4,1);vsChange=NaN;
mapResidual=NaN;thrustResidual=NaN;
try
 P=a.HLCparam;
 vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf,P,H.F2,H.F3,H.F4);
 beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,P);
 alpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,vs(:),P);
 if ~isequal(size(beta),[3,3]) || rcond(beta)<1e-12
    status='BETA_SINGULAR';return;
 end
 tauRaw=beta\alpha(:);
 uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,P);
 mapped=[uf(1);tauRaw];
 thrustResidual=mapped(1)-Tr1;
 if abs(thrustResidual)>1e-7*max(1,abs(Tr1))
     status='THRUST_RECONSTRUCTION_FAILED';return;
 end
 % The generated alpha2 is affine in v2..4; verify numerically.
 M=zeros(3,3);
 for j=1:3
   shifted=vs(:);shifted(j)=shifted(j)+1;
   aa=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,shifted,P);
   M(:,j)=aa(:)-alpha(:);
 end
 if rcond(M)<1e-12
   status='VS_TO_TORQUE_RANK_LOSS';return;
 end
 chk=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf, ...
                    vs(:)+[.123;-.287;.091],P);
 if norm(chk(:)-alpha(:)-M*[.123;-.287;.091],Inf)> ...
       1e-6*max(1,norm(chk(:),Inf))
    status='VS_NONAFFINE';return;
 end
 A=M\beta;
 [tau,status]=v65BoundedVirtualProjection(tauRaw,A,lo(2:4),hi(2:4));
 if ~strcmp(status,'OK'),return;end
 deltaVs=M\(beta*(tau-tauRaw));
 alphaCheck=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf, ...
                                       vs(:)+deltaVs,P);
 tauCheck=beta\alphaCheck(:);
 mapResidual=norm(tauCheck-tau,Inf);
 if mapResidual>1e-7*max(1,norm(tau,Inf))
   status='INVERSE_EQUALITY_RESIDUAL';return;
 end
 u=[Tr1;tauCheck];vsChange=norm(deltaVs,Inf);
 if any(u<lo-1e-7) || any(u>hi+1e-7)
   status='PHYSICAL_BOX_NOT_SATISFIED';return;
 end
catch ME
 status=['ERROR_' ME.identifier];
end
end

function [u,status]=v65BoundedVirtualProjection(u0,A,lo,hi)
% Exact active-set enumeration (3^3 states) for:
% min 1/2 ||A*(u-u0)||_2^2, lo <= u <= hi.
% Unlike post-hoc actuator clipping, the physical box is enforced WHILE
% choosing the virtual input; inversion equality is checked afterwards.
u0=u0(:);lo=lo(:);hi=hi(:);u=nan(3,1);status='OK';
if any(~isfinite([u0;A(:);lo;hi])) || ~isequal(size(A),[3,3])
 status='INVALID_QP_DATA';return;
end
Q=A.'*A;
if rcond(Q)<1e-12,status='RANK_DEFICIENT_METRIC';return;end
best=Inf;
for it=0:26
 digits=dec2base(it,3,3)-'0';
 free=(digits==0);fixed=~free;
 c=zeros(3,1);
 c(digits==1)=lo(digits==1);
 c(digits==2)=hi(digits==2);
 if any(free)
    ff=find(free);fa=find(fixed);
    if isempty(fa)
      c(ff)=u0(ff);
    else
      c(ff)=u0(ff)-Q(ff,ff)\(Q(ff,fa)*(c(fa)-u0(fa)));
    end
 end
 if any(c<lo-1e-9) || any(c>hi+1e-9),continue;end
 val=(c-u0).'*Q*(c-u0);
 if val<best
    best=val;u=c;
 end
end
if ~isfinite(best),status='ACTIVE_SET_NO_SOLUTION';end
end

function [v,dv]=v65NumeratorDecomposition(x,t,sc,H,P,dx)
% Exact source Uf numerator. Analytical derivative along the ORIGINAL
% 19-state nonlinear plant for a specified instantaneous physical input.
mm=P(1)+P(6);mass=P(1);g=P(5);L=P(7);
rz=sc.ref(t,0);rv=sc.ref(t,1);
ra=sc.ref(t,2);rj=sc.ref(t,3);
p=x(14:16);w=x(17:19);
pDot=dx(14:16);wDot=dx(17:19);
c=cross(w,p);cDot=cross(wDot,p)+cross(w,pDot);
grav=mm*(ra(3)+g);
pos=mm*H.F1(1)*(rz(3)-x(10));
vel=mm*H.F1(2)*(rv(3)-x(13));
cable=mass*L*p(3)*(c.'*c);
v=[grav+pos+vel+cable,grav,pos,vel,cable];
dv=mm*(rj(3)+H.F1(1)*(rv(3)-x(13)) + ...
 H.F1(2)*(ra(3)-dx(13)))+ ...
 mass*L*(pDot(3)*(c.'*c)+2*p(3)*(c.'*cDot));
end

function v65WriteHandover(work,opts)
base=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(base),old=fileread(base);else,old='V54 base history missing';end
p=fullfile(work,'V65_DIRECT_CONSISTENCY_SUMMARY.csv');
if isfile(p),summary=fileread(p);else,summary='No V65 execution summary';end
note=[newline newline '===== V65 DIRECT CONSISTENCY CAUSAL EXPERIMENT =====' newline ...
 'USER REQUIREMENT: No invented thrust floors, no arbitrary zero values for derivative inputs, preserve original HLC/reference/plant and original obstacles. No MPC.' newline ...
 'SOURCE R193: T=N/D, N=(m+mL)(F11*(zd-zL)+F12*(vzd-vL)+zdd+g)+m*L*pTz*norm(wL cross pT)^2. D is geometric input coefficient.' newline ...
 'The exact derivative dN/dt is recorded under the physically applied input and under the clipped nominal input at THE SAME STATE. Difference isolates immediate input-channel causality.' newline ...
 'BRANCHES: (1) HLC_ONLY; (2) ORIGINAL_R1; (3) DIRECT_INVERSE_CONSTRAINT.' newline ...
 'Direct branch uses ORIGINAL R1 demanded thrust (NOT a new floor/ramp). It maps T to equivalent v1(0), recomputes Vs and Beta2/alpha2, then solves a 3-dimensional bound-constrained quadratic optimization in PHYSICAL torque with exact inverse equality.' newline ...
 'Objective in the direct optimization: minimize ||M\\Beta*(tau-tau_raw)||^2; M=d(alpha2)/dVs verified affine; all 27 active sets checked; no post-hoc torque clipping in DIRECT branch.' newline ...
 'IMPORTANT LIMIT: only v1(0) is remapped; vf(2:6) are retained nominal source data. This is a direct NECESSARY-CONDITIONS experiment, NOT a full C5 input-jet-consistent CBF.' newline ...
 'No CBF inequality for all 4 inputs has been mathematically certified. Original thrust-only R1 inequality is audited as-is and may fail from lack of authority. Do not label applied inputs safe or stable merely because they are bounded.' newline ...
 'Existing evidence: V60/V61 remap0 reduced torque to ~0.035 Nm at t2.300 but did not resolve HLC raw thrust collapse; V62 differences amplified torque; V63 C5 correction violated R1 due actuation lag; V64 higher Lie rows were only numerical/local.' newline ...
 'V64 had q=Tdot and nu=Tddot arbitrarily zero at snapshots; V65 does NOT make either assumption, and does not introduce dynamic thrust extension.' newline ...
 'To complete common design later: derive true C5 correction dynamics; use exact lower-order CBF set, mixed input relative degrees, physical realizability of actuator inputs, and feasible return to nominal. No made-up physical derivative bounds.' newline ...
 '===== V65 ACTUAL RESULTS =====' newline summary newline];
v23WriteText(fullfile(work,'V65_FULL_UPDATED_HANDOVER.txt'),[old note]);
end


% =======================================================================
% V66 ANALYTIC C5 JET + DIRECT INPUT FEASIBILITY AUDIT
%
% This is an experiment about NECESSARY consistency conditions, not a
% 4-channel safety-certified CBF controller. The C5 pulse is chosen from
% an OFFLINE identified first R1 intervention. This is noncausal to a live
% controller; its only purpose is to test exact jet influence and what
% instantaneous physical boxes can/cannot enforce.
%
% For t in (t0,t0+L), dV1(t)=A*smootherstep_11((t-t0)/L).
% smootherstep_11 = 1/Beta(6,6) * int_0^s r^5(1-r)^5 dr.
% Therefore d^k dV1/dt^k are EXACT derivatives for k=0..5.
% There is no numerical differentiation of R1's nonsmooth correction.
%
% All V2-V4 values are regenerated using the corresponding C5 jet, and
% the exact nonlinear Beta2 and alpha2 equations are enforced for the
% physically bounded torques with no after-the-fact torque saturation.
% A large change in V2-V4 is RECORDED rather than silently accepted as
% a legitimate nominal HLC motion.
%
% IMPORTANT: The SOURCE Vfd components are a discrete-time NOMINAL
% design sequence, not proven continuous time derivatives along the
% CBF-modified plant. This necessary-conditions experiment does not
% claim that summing these two sequences proves full time-jet consistency.
% =======================================================================
function out=v66HighOrderConsistencySuite(work,opts)
assert(strcmpi(opts.plant,'V11_19') && strcmpi(opts.parameterSet,'R193') && ...
 abs(opts.dt-0.025)<1e-12,'CBF:V66Protocol',...
 'V66 uses the exact original V11_19/R193 25-ms condition');
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=opts.dt;
[x0,origin]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x0)==19 && all(isfinite(x0)), 'CBF:V66Prestate');
v23WriteText(fullfile(work,'V66_INITIAL_STATE_PROVENANCE.txt'),origin);
H=v23MakeHLC(sc.settings,opts.dt);
s=sc.settings;
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
assert(numel(lo)==4 && numel(hi)==4 && all(hi>lo),'CBF:V66Limits');
t0=2.125;
a0=v23HLC(x0,t0,sc,H,v23EstimatedMass(opts,t0));
assert(all(isfinite(a0.vfRaw)) && a0.betaRcond>1e-12, ...
 'CBF:V66BadNominalPrestate');
% Determine the first R1 amplitude from a separate *offline benchmark*:
% advance original nominal one interval, then evaluate original R1 at 2.150.
% Do NOT confuse this look-ahead laboratory amplitude with an online policy.
x1=v25StepOnce(x0,max(lo,min(hi,a0.raw)),s,opts);
a1=v23HLC(x1,t0+opts.dt,sc,H,v23EstimatedMass(opts,t0+opts.dt));
[r1,reason]=v25R1ExactFilter(x1,s,sc.obstacles,...
                max(lo,min(hi,a1.raw)));
assert(strcmp(reason,'OK'),'CBF:V66FirstR1Invalid', ...
 'First R1 intervention missing, cannot define reproducible amplitude');
mm=a1.HLCparam(1)+a1.HLCparam(6);
A=(r1(1)-a1.raw(1))*a1.thrustDenominator/mm;
assert(isfinite(A) && mm>0 && A>0,'CBF:V66Amplitude');
step=opts.dt;
Tbound1=factorial(4)*abs(A)/step^4;
Tbound2=factorial(5)*abs(A)/step^5;
info=table(t0,t0+step,A,r1(1),a1.raw(1),...
 Tbound1,Tbound2, ...
 'VariableNames',{'zeroCorrectionTime_s','firstR1InterventionTime_s',...
 'requiredDeltaV1','R1RequiredThrust_N','nominalThrust_N',...
 'minimumPossibleMaxAbsFourthDerivative_ifZeroInitialJet',...
 'minimumPossibleMaxAbsFifthDerivative_ifZeroInitialJet'});
writetable(info,fullfile(work,'V66_FIRST_INTERVENTION_THEOREM.csv'));
D=opts.v66Durations(:)';
assert(~isempty(D) && all(isfinite(D)) && all(D>=opts.dt) && ...
 all(abs(D/opts.dt-round(D/opts.dt))<1e-8), ...
 'CBF:V66Duration','Comparison durations must be integral 25ms steps');
rows=cell(numel(D)*2,12);n=0;errors=0;failed=0;
for j=1:numel(D)
 duration=D(j);
 label=sprintf('RAMP_%03dMS',round(duration*1000));
 try
   [tr,st]=v66FrozenHighOrderShadow(sc,H,opts,lo,hi,x0,t0,A,duration);
   writetable(tr,fullfile(work,['V66_SHADOW_' label '.csv']));
   n=n+1;rows(n,:)={label,'FROZEN_STATE',st.status,st.lastTime,...
     height(tr),max(tr.absDeltaV1_4),max(tr.absDeltaV1_5),...
     max(tr.rawMappedTorqueInf_Nm),max(tr.boundedDeltaVsInf),...
     min(tr.r1Residual),min(tr.nominalHlcRawThrust_N),st.details};
   if ~strcmp(st.status,'SHADOW_COMPLETE_DIAGNOSTIC'),failed=failed+1;end
 catch ME
   errors=errors+1;failed=failed+1;n=n+1;
   rows(n,:)={label,'FROZEN_STATE',['MATLAB_ERROR_' ME.identifier],NaN,...
     0,NaN,NaN,NaN,NaN,NaN,NaN,ME.message};
   v23WriteText(fullfile(work,['V66_ERROR_SHADOW_' label '.txt']), ...
       getReport(ME,'extended','hyperlinks','off'));
 end
 try
   [tr,st]=v66ClosedHighOrderTrial(sc,H,opts,lo,hi,x0,t0,A,duration);
   writetable(tr,fullfile(work,['V66_CLOSED_' label '.csv']));
   n=n+1;rows(n,:)={label,'CLOSED_LOOP',st.status,st.lastTime,...
     height(tr),max(tr.absDeltaV1_4),max(tr.absDeltaV1_5),...
     max(tr.rawMappedTorqueInf_Nm),max(tr.boundedDeltaVsInf),...
     min(tr.r1Residual),min(tr.nominalHlcRawThrust_N),st.details};
   if ~strcmp(st.status,'HORIZON_REACHED_UNCERTIFIED'),failed=failed+1;end
 catch ME
   errors=errors+1;failed=failed+1;n=n+1;
   rows(n,:)={label,'CLOSED_LOOP',['MATLAB_ERROR_' ME.identifier],NaN,...
     0,NaN,NaN,NaN,NaN,NaN,NaN,ME.message};
   v23WriteText(fullfile(work,['V66_ERROR_CLOSED_' label '.txt']), ...
      getReport(ME,'extended','hyperlinks','off'));
 end
end
summary=cell2table(rows(1:n,:),'VariableNames',...
 {'durationLabel','mode','status','lastTime_s','samples',...
 'maxAbsJetFourth','maxAbsJetFifth','maxRawMappedTorque_Nm',...
 'maxVirtualVsAdjustment','minR1Residual','minNominalHlcRawThrust_N',...
 'failureDetail'});
writetable(summary,fullfile(work,'V66_C5_EXACT_JET_SUMMARY.csv'));
out=struct('nCases',n,'nFailedCases',failed,...
 'nRuntimeErrors',errors,'nR1FilterStops',0);
end

function z=v66ExactC5Jet(t,t0,duration,amplitude)
% Quintic-endpoint FLATNESS in derivatives up to order 5. Explicit exact
% derivatives of polynomial phi(s)=2772*int_0^s r^5*(1-r)^5 dr.
z=zeros(1,6);
s=(t-t0)/duration;
if s<=0,return;end
if s>=1,z(1)=amplitude;return;end
c=factorial(11)/(factorial(5)^2);
for k=0:5
 accum=0;
 for j=0:5
   p=6+j;
   coeff=c*(-1)^j*nchoosek(5,j)/(6+j);
   ff=1;
   for jj=0:k-1,ff=ff*(p-jj);end
   accum=accum+coeff*ff*s^(p-k);
 end
 z(k+1)=amplitude*accum/duration^k;
end
end

function [tr,st]=v66FrozenHighOrderShadow(sc,H,opts,lo,hi,x,t0,A,duration)
% A fine grid is NECESSARY: high jets can have zero values at 25-ms nodes
% yet extremely large values between them. x is purposefully FROZEN;
% these are algebraic audits, never a simulated vehicle flight.
f={'time_s','deltaV1','absDeltaV1_1','absDeltaV1_2',...
 'absDeltaV1_3','absDeltaV1_4','absDeltaV1_5',...
 'candidateThrust_N','nominalHlcRawThrust_N','rawMappedTorqueInf_Nm',...
 'boundedTorqueInf_Nm','boundedDeltaVsInf','betaSigmaMin',...
 'thrustInOriginalPhysicalBox','inverseStatus','r1Residual',...
 'r1Status','nominalV1BelowZeroThrustBoundary',...
 'v1PhysicalLower','v1PhysicalUpper','nominalV1InPhysicalBox'};
M=20;R=cell(M+1,numel(f));n=0;
a=v23HLC(x,t0,sc,H,v23EstimatedMass(opts,t0));
st=struct('status','SHADOW_COMPLETE_DIAGNOSTIC','lastTime',t0,...
 'details','Frozen-state algebraic jet check, NOT a flight trajectory');
for k=0:M
 t=t0+duration*k/M;
 z=v66ExactC5Jet(t,t0,duration,A);
 vf=a.vfRaw(:).'+z;
 uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
 T=uf(1);
 beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
 vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam,H.F2,H.F3,H.F4);
 alp=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,vs(:),a.HLCparam);
 validBeta=isequal(size(beta),[3 3]) && all(isfinite(beta(:))) && ...
             rcond(beta)>=1e-12;
 sigma=NaN;rawInf=NaN;boundedInf=NaN;vsInf=NaN;
 status='NOT_IN_PHYSICAL_THRUST_BOX';
 if validBeta
   sigma=min(svd(beta));
   if all(isfinite(alp(:)))
     rawInf=norm(beta\alp(:),Inf);
   end
   if T>=lo(1)-1e-9 && T<=hi(1)+1e-9
      [u,~,~,vsInf,~,~,status]= ...
        v65SolveBoundedInverse(x,a,H,lo,hi,vf,T);
      if strcmp(status,'OK'),boundedInf=norm(u(2:4),Inf);end
   end
 else
    status='BETA_NOT_INVERTIBLE';
 end
 [~,rReason]=v25R1ExactFilter(x,sc.settings,sc.obstacles,...
                             max(lo,min(hi,a.raw)));
 rResidual=NaN;
 if strcmp(rReason,'OK')
    [~,rResidual,~,audit]=v28R1Audit(x,sc.settings,sc.obstacles,T);
    if ~strcmp(audit,'OK'),rResidual=NaN;end
 end
 zZero=a.vfRaw(1)-a.raw(1)*a.thrustDenominator/...
             (a.HLCparam(1)+a.HLCparam(6));
 bounds=a.vfRaw(1)+([lo(1),hi(1)]-a.raw(1))*...
       a.thrustDenominator/(a.HLCparam(1)+a.HLCparam(6));
 vLo=min(bounds);vHi=max(bounds);
 n=n+1; R(n,:)={t,z(1),abs(z(2)),abs(z(3)),abs(z(4)),...
 abs(z(5)),abs(z(6)),T,a.raw(1),rawInf,boundedInf,...
 vsInf,sigma,double(T>=lo(1) && T<=hi(1)),status,...
 rResidual,rReason,double(a.vfRaw(1)<zZero),...
 vLo,vHi,double(a.vfRaw(1)>=vLo && a.vfRaw(1)<=vHi)};
 st.lastTime=t;
end
tr=cell2table(R(1:n,:),'VariableNames',f);
end

function [tr,st]=v66ClosedHighOrderTrial(sc,H,opts,lo,hi,x,t0,A,duration)
f={'time_s','nominalHlcRawThrust_N','appliedThrust_N',...
 'originalR1Demand_N','nominalHlcRawTorqueInf_Nm',...
 'rawMappedTorqueInf_Nm','appliedTorqueInf_Nm',...
 'boundedDeltaVsInf','betaSigmaMin','deltaV1',...
 'absDeltaV1_1','absDeltaV1_2','absDeltaV1_3',...
 'absDeltaV1_4','absDeltaV1_5','r1Residual',...
 'cableH','tension_N','loadVz_mps','loadAltitudeError_m',...
 'thrustPhysicalBoxSatisfied','torquePhysicalBoxSatisfied',...
 'nominalHlcThrustIsNegative','thrustZeroBoundaryV1',...
 'inverseStatus','r1Status','nominalNumerator_N',...
 'numeratorDotApplied_Nps','numeratorDotNominal_Nps',...
 'numeratorDotDifference_Nps',...
 'immediateVelocityFeedbackDifference_Nps',...
 'immediateCableFeedbackDifference_Nps',...
 'v1PhysicalLower','v1PhysicalUpper','nominalV1InPhysicalBox'};
K=round(.55/opts.dt);R=cell(K+1,numel(f));n=0;
st=struct('status','HORIZON_REACHED_UNCERTIFIED','lastTime',t0,...
 'details','No high-order CBF guarantee; C5 correction chosen OFFLINE');
s=sc.settings;
for k=0:K
 t=t0+k*opts.dt;
 a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
 if ~all(isfinite([a.raw(:);a.vfRaw(:);a.beta(:)]))
    st.status='NOMINAL_HLC_NONFINITE';st.lastTime=t;break;
 end
 z=v66ExactC5Jet(t,t0,duration,A);
 vf=a.vfRaw(:).'+z;
 uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,a.HLCparam);
 T=uf(1);
 % NEVER clamp T after the jet was chosen: that would break the jet.
 if ~isfinite(T) || T<lo(1) || T>hi(1)
   st.status='THRUST_OUTSIDE_PHYSICAL_BOX';st.lastTime=t;
   st.details='The mathematically C5 input request has no feasible physical thrust here';
   break;
 end
 [u,mapped,beta,vsInf,eqr,~,status]=...
    v65SolveBoundedInverse(x,a,H,lo,hi,vf,T);
 if ~strcmp(status,'OK')
    st.status=['INVERSE_' status];st.lastTime=t;
    st.details='HLC inverse or bounded-torque condition failed';break;
 end
 [r1,rReason]=v25R1ExactFilter(x,s,sc.obstacles,...
                                      max(lo,min(hi,a.raw)));
 rr=NaN;
 if strcmp(rReason,'OK')
   [~,rr,~,audit]=v28R1Audit(x,s,sc.obstacles,u(1));
   if ~strcmp(audit,'OK'),rr=NaN;end
 end
 h=v23CableSafety(x,sc);ten=v23Tension(x,s,u(1));
 zZero=a.vfRaw(1)-a.raw(1)*a.thrustDenominator/...
          (a.HLCparam(1)+a.HLCparam(6));
 bounds=a.vfRaw(1)+([lo(1),hi(1)]-a.raw(1))*...
       a.thrustDenominator/(a.HLCparam(1)+a.HLCparam(6));
 vLo=min(bounds);vHi=max(bounds);
 dxApplied=v23RHS(x,u,s);
 dxNominal=v23RHS(x,max(lo,min(hi,a.raw)),s);
 [terms,dNa]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,dxApplied);
 [~,dNn]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,dxNominal);
 velocityD=-(a.HLCparam(1)+a.HLCparam(6))*H.F1(2)*(dxApplied(13)-dxNominal(13));
 cableD=(dNa-dNn)-velocityD;
 n=n+1;
 R(n,:)={t,a.raw(1),u(1),v65SafeR1Thrust(r1,rReason),...
 norm(a.tau,Inf),norm(mapped(2:4),Inf),norm(u(2:4),Inf),...
 vsInf,min(svd(beta)),z(1),abs(z(2)),abs(z(3)),abs(z(4)),...
 abs(z(5)),abs(z(6)),rr,h,ten,x(13),x(10)-a.refPos(3),...
 double(u(1)>=lo(1) && u(1)<=hi(1)),...
 double(all(u(2:4)>=lo(2:4)) && all(u(2:4)<=hi(2:4))),...
 double(a.raw(1)<0),zZero,status,rReason,...
 terms(1),dNa,dNn,dNa-dNn,velocityD,cableD,...
 vLo,vHi,double(a.vfRaw(1)>=vLo && a.vfRaw(1)<=vHi)};
 st.lastTime=t;
 if ~isfinite(rr)
   st.status='R1_UNDEFINED_OR_NONFINITE';break;
 end
 if rr<-1e-7
   st.status='R1_CBF_INEQUALITY_VIOLATED';
   st.details='Original R1 thrust-only safety condition fails; NOT SAFE';break;
 end
 if h<-1e-8
   st.status='GEOMETRIC_SAFE_SET_LEFT';break;
 end
 if ten<=0
   st.status='NONPOSITIVE_TENSION';break;
 end
 if eqr>1e-7
   st.status='INVERSE_RESIDUAL_INVALID';break;
 end
 if k==K,break;end
 x=v25StepOnce(x,u,s,opts);
 if ~all(isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
    abs(norm(x(14:16))-1)>1e-3
    st.status='PLANT_INVALID';break;
 end
end
tr=cell2table(R(1:n,:),'VariableNames',f);
end

function v66WriteHandover(work,A,opts,summary)
base=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(base),old=fileread(base);else,old='V54 base not present';end
note=[newline newline '========== V66 COMPLETE SCIENTIFIC HANDOVER ==========' newline ...
 'METHODOLOGICAL PRIORITY: Do not set thrust derivative to zero, invent thrust floors, post-clip after virtual inverse, or treat HLC Vfd(6) as irrelevant to temporal regularity.' newline ...
 'SOURCE AUDIT in R193: Uf v1(0); Beta2 v1(0); Vs v1(0:3); V2_alpha2 v1(0:4); Vfd returns six nominal components (0:5); fifth has no DIRECT reference in the four physical inversion functions.' newline ...
 'Critical distinction: nominal Vfd higher terms are DISCRETE-DESIGN values, not guaranteed real-plant Lie derivatives. Correction C5 jet alone does NOT certify nominal + correction as actual full derivative jet.' newline ...
 'V66: exact C5 analytic smoothstep11 derivative (0:5), NOT finite differences. A is derived from an OFFLINE first R1 intervention at 2.150, so profile is a noncausal controlled experiment and must NEVER be described as a live safe CBF policy.' newline ...
 'Original physical thrust and torque limits are enforced during virtual inversion. If thrust is out of the physical box, STOP; no clipping of a C5 command. Virtual v2-v4 magnitude required to enforce physical torque bounds is fully logged. These are necessary algebraic conditions, not proof of closed-loop temporal consistency.' newline ...
 'No physical thrust-rate or thrust-acceleration bounds were invented. There is no added T_HLC floor. The zero-thrust boundary v1=T_nom-free formula from source Uf is only MEASURED and not imposed as safety CBF.' newline ...
 sprintf('OFFLINE R1 first intervention delta v1 A=%.12g; dt=%.12g. ',A,opts.dt) ...
 'Taylor remainder: max fourth derivative >= 24*abs(A)/dt^4 for initially zero derivatives 0..3; max fifth derivative >= 120*abs(A)/dt^5 if derivatives 0..4 start at zero.' newline ...
 'V65: 0th thrust inverse map improved torque to 0.366 Nm max (0.035 Nm at t2.300) but raw nominal thrust fell to 0.807 N; failed MAP_BETA_SINGULAR at 2.325. Original R1 reached -2.723 N nominal thrust and 135.23 Nm raw torque.' newline ...
 'V65 same-state dN/dt causal difference t2.300 approx -246.91 N/s, predominantly vertical velocity feedback; distinguishing raw nominal from applied thrust is essential.' newline ...
 'V62 rear finite differences produced torque >1000 Nm; V63 smooth six-jet could not meet original R1 condition at first activation; V64 relative order was numerical only and arbitrarily zeroed Tdot and Tddot; V65 only 0th jet.' newline ...
 'V66 does NOT solve the high-order 4-input CBF and does NOT prove avoidance or recovery. Feasible algebraic inversion at samples is not a certificate of forward invariance, viability, or safe equilibrium.' newline ...
 'NEXT: If these trials expose infeasible instant requirements, formulate CBF on the actual extended-system input with verified mixed relative degrees and physical actuator dynamics. Prove auxiliary CBF initial-set conditions and feasible return to HLC, then validate 19-state closed loop.' newline ...
 '========== V66 ACTUAL OUTCOMES ==========' newline ...
 evalc('disp(summary)') newline];
v23WriteText(fullfile(work,'V66_FULL_UPDATED_HANDOVER.txt'),[old note]);
end

% ========================================================================
% V67: SOURCE VFD SEMANTICS, ACTUAL FIRST DERIVATIVE, VIRTUAL INVERSE AUDIT
% THEORY CLAIMS (AND NO MORE):
% - The R193 generated Vfd is compared against F1*Ad^k*e (k=0..5),
%   where Ad is the ZERO-ORDER-HOLD sampled nominal DOUBLE-INTEGRATOR
%   closed-loop error map (not necessarily the exact sampled nonlinear plant).
% - For a continuous nominal double-integrator closed loop, the kth
%   derivative of v1 would be F1*Ac^k*e, Ac=[0,1;-F11,-F12].
% - The forward difference of sampled nominal v1 is
%   F1*((Ad-I)/dt)^k*e. Neither is silently identified with Vfd(k+1).
% - The actual first Lie/time derivative is computed using the ORIGINAL
%   19-state plant and the chosen applied 4-input at the SAME physical x.
% - Higher actual derivatives require input time derivatives / a specified
%   differentiable extension. Nothing is guessed to be zero.
% - A continuous-nominal jet is SHADOW-EVALUATED in original generated
%   inverse; it is NEVER APPLIED as a modified HLC command.
% ========================================================================
function out=v67SourceDerivativeAudit(work,opts)
assert(strcmpi(opts.plant,'V11_19') && ...
       strcmpi(opts.parameterSet,'R193') && abs(opts.dt-.025)<1e-12, ...
       'CBF:V67Protocol','V67 requires original V11_19/R193/dt=.025');
sc=CBF_V19_Scenarios('straight_single','R193');
sc.dt=opts.dt;s=sc.settings;
[x0,origin]=v40GetV19PreInterventionState(sc,opts,2.125);
assert(numel(x0)==19 && all(isfinite(x0)),'CBF:V67State');
v23WriteText(fullfile(work,'V67_INITIAL_STATE_PROVENANCE.txt'),origin);
H=v23MakeHLC(s,opts.dt);
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
F=H.F1(:).';dt=opts.dt;
Ad=[1-F(1)*dt^2/2,dt-F(2)*dt^2/2;...
    -F(1)*dt,1-F(2)*dt];
Ac=[0,1;-F(1),-F(2)];
Adiff=(Ad-eye(2))/dt;
% Source-generated Vfd is intended to be observed, never edited.
sourceFields={'mode','time_s','derivativeOrder','generatedVfd',...
    'nominalDiscreteAdPower','continuousNominalAcPower',...
    'forwardDifferencePower','sourceMinusDiscrete',...
    'sourceMinusContinuous','sourceMinusForwardDifference',...
    'dt_s','verticalError_m','verticalRateError_mps'};
stateFields={'mode','time_s','nominalRawThrust_N',...
 'appliedThrust_N','rawNominalTorqueInf_Nm',...
 'shadowContinuousJetTorqueInf_Nm','shadowContinuousJetBetaSigmaMin',...
 'shadowContinuousJetStatus','actualFirstDerivativeUnderNominal',...
 'actualFirstDerivativeUnderApplied',...
 'generatedSecondComponent','continuousNominalFirstDerivative',...
 'actualMinusGeneratedUnderNominal',...
 'actualMinusGeneratedUnderApplied','deltaNdotFromApplied_Nps',...
 'verticalVelocityError_mps','r1Status','r1Residual',...
 'maxSourceVsDiscreteError','maxSourceVsContinuousDifference'};
S=cell(2*12*6,numel(sourceFields));SN=0;
Q=cell(2*12,numel(stateFields));QN=0;
summaryFields={'mode','status','lastTime_s','samples',...
 'maxSourceVsDiscreteError','maxSourceVsContinuousDifference',...
 'maxShadowTorqueInf_Nm','minNominalThrust_N','lastR1Status'};
SS=cell(2,numel(summaryFields));nErrors=0;nFailed=0;nStop=0;
modes={'HLC_ONLY','ORIGINAL_R1'};
for mm=1:numel(modes)
    label=modes{mm};x=x0(:);maxDis=0;maxCont=0;maxTau=0;
    minRaw=Inf;last=2.125;ns=0;stateStatus='COMPLETE_UNCERTIFIED';
    lastReason='NOT_R1';
    try
       for kk=0:8
          t=2.125+kk*dt;
          a=v23HLC(x,t,sc,H,v23EstimatedMass(opts,t));
          if ~all(isfinite([a.raw(:);a.vfRaw(:)]))
              stateStatus='NONFINITE_NOMINAL_INPUT';break;
          end
          e=[a.refPos(3)-x(10);a.refVel(3)-x(13)];
          vfAd=zeros(1,6);vfAc=zeros(1,6);vfFd=zeros(1,6);
          for k=0:5
             vfAd(k+1)=F*(Ad^k)*e;
             vfAc(k+1)=F*(Ac^k)*e;
             vfFd(k+1)=F*(Adiff^k)*e;
             SN=SN+1;
             S(SN,:)={label,t,k,a.vfRaw(k+1),vfAd(k+1),...
                vfAc(k+1),vfFd(k+1),a.vfRaw(k+1)-vfAd(k+1),...
                a.vfRaw(k+1)-vfAc(k+1),...
                a.vfRaw(k+1)-vfFd(k+1),dt,e(1),e(2)};
          end
          eDis=max(abs(a.vfRaw(:)-vfAd(:)));
          eCont=max(abs(a.vfRaw(:)-vfAc(:)));
          maxDis=max(maxDis,eDis);maxCont=max(maxCont,eCont);
          minRaw=min(minRaw,a.raw(1));
          base=min(hi,max(lo,a.raw));
          if strcmp(label,'ORIGINAL_R1')
              [u,reason]=v25R1ExactFilter(x,s,sc.obstacles,base);
              lastReason=reason;
              if ~strcmp(reason,'OK')
                 stateStatus=['R1_FILTER_' reason];nStop=nStop+1;break;
              end
          else
              u=base;reason='NOT_APPLIED';
          end
          [~,res,~,audit]=v28R1Audit(x,s,sc.obstacles,u(1));
          if ~strcmp(audit,'OK'),res=NaN;end
          rhsNom=v23RHS(x,base,s);
          rhsApp=v23RHS(x,u,s);
          j1Nom=F*[a.refVel(3)-x(13);a.refAcc(3)-rhsNom(13)];
          j1App=F*[a.refVel(3)-x(13);a.refAcc(3)-rhsApp(13)];
          [~,nDotNom]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,rhsNom);
          [~,nDotApp]=v65NumeratorDecomposition(x,t,sc,H,a.HLCparam,rhsApp);
          shadowStatus='OK_SHADOW_ONLY';shadowTau=NaN;shadowSigma=NaN;
          try
              beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vfAc,a.HLCparam);
              vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vfAc,a.HLCparam,H.F2,H.F3,H.F4);
              alp=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vfAc,vs(:),a.HLCparam);
              if isequal(size(beta),[3,3]) && all(isfinite(beta(:))) && ...
                   all(isfinite(alp(:))) && rcond(beta)>=1e-12
                  shadowTau=norm(beta\alp(:),Inf);
                  shadowSigma=min(svd(beta));
              else
                  shadowStatus='BAD_SHADOW_INVERSE';
              end
          catch MEshadow
              shadowStatus=['SHADOW_ERROR_' MEshadow.identifier];
          end
          QN=QN+1;
          Q(QN,:)={label,t,a.raw(1),u(1),norm(a.tau,Inf),...
              shadowTau,shadowSigma,shadowStatus,j1Nom,j1App,...
              a.vfRaw(2),vfAc(2),j1Nom-a.vfRaw(2),...
              j1App-a.vfRaw(2),nDotApp-nDotNom,...
              a.refVel(3)-x(13),reason,res,eDis,eCont};
          if isfinite(shadowTau),maxTau=max(maxTau,shadowTau);end
          ns=ns+1;last=t;
          if kk<8
              x=v25StepOnce(x,u,s,opts);
              if any(~isfinite(x)) || abs(norm(x(1:4))-1)>1e-3 || ...
                  abs(norm(x(14:16))-1)>1e-3
                  stateStatus='PLANT_MANIFOLD_INVALID';break;
              end
          end
       end
    catch ME
       nErrors=nErrors+1;stateStatus=['MATLAB_ERROR_' ME.identifier];
       v23WriteText(fullfile(work,['V67_ERROR_' label '.txt']),...
           getReport(ME,'extended','hyperlinks','off'));
    end
    if ~strcmp(stateStatus,'COMPLETE_UNCERTIFIED'),nFailed=nFailed+1;end
    SS(mm,:)={label,stateStatus,last,ns,maxDis,maxCont,maxTau,minRaw,lastReason};
end
sourceTable=cell2table(S(1:SN,:),'VariableNames',sourceFields);
stateTable=cell2table(Q(1:QN,:),'VariableNames',stateFields);
summary=cell2table(SS,'VariableNames',summaryFields);
writetable(sourceTable,fullfile(work,'V67_SOURCE_VFD_0TO5_AUDIT.csv'));
writetable(stateTable,fullfile(work,'V67_ACTUAL_FIRST_DERIVATIVE_CAUSAL.csv'));
writetable(summary,fullfile(work,'V67_DERIVATIVE_SEMANTICS_SUMMARY.csv'));
% The source identity should hold for R193. If it fails, report visibly.
sourceTol=1e-7;
if any(summary.maxSourceVsDiscreteError>sourceTol)
  v23WriteText(fullfile(work,'V67_SOURCE_IDENTITY_WARNING.txt'),...
    sprintf('Source Vfd != proposed Ad power within tolerance %g; DO NOT assume source semantics.\n',sourceTol));
  nFailed=nFailed+1;
end
out=struct('nCases',2,'nFailedCases',nFailed,...
  'nRuntimeErrors',nErrors,'nR1FilterStops',nStop);
end

function v67WriteSourceHandover(work,opts)
base=fullfile(work,'CBF_CUMULATIVE_HANDOVER_V54.txt');
if isfile(base),history=fileread(base);else,history='V54 base not present';end
recent=[newline newline '========== V55-V67 CUMULATIVE FINDINGS ==========' newline ...
 'V55: original R1 shared thrust-only CBF becomes infeasible at 2.350 s: thrust >= 27.93 N > physical 20 N. This is a LOCAL feasibility check, not impossibility of earlier corrective actions.' newline ...
 'V56: normal HLC tracks smooth descent (0.75 m case) well; hard step down can generate negative raw thrust. CBF initial 0-time rows can be infeasible; avoid treating those rows as flight evidence.' newline ...
 'V57/V58: CBF thrust changes around 2.150 s from HLC 8.87 to applied 12.17 N; subsequent vertical speed drives HLC raw thrust near zero and negative; late forced release can hit zero applied thrust and very low cable tension.' newline ...
 'V60/V61/V65: rebuilding torque inverse using CBF-applied thrust, but only zero-order v1, reduces torque at 2.300 s from 135 Nm class to 0.035 Nm in the tested state. This is NOT 0:5 derivative consistency. Raw nominal thrust still collapses.' newline ...
 'V62: rear differences of 25 ms R1 thrust corrections create huge derivative entries and raw torque (>1000 Nm). At nonsmooth switching these differences are NOT continuous derivatives.' newline ...
 'V63: continuous correction integrator chain has consistent correction derivatives, but its applied thrust cannot satisfy the original instantaneous R1 condition. Faster response increases torque demand.' newline ...
 'V64: local numerical 4th-order obstacle input action found pitch torque; numerical differences and zero Tdot/Tddot choices DO NOT certify true 4-input HOCBF or feasible control.' newline ...
 'V66: exact analytic C5 ramp derivative of an OFFLINE R1 thrust command remains huge if squeezed into 25 ms; up to 275548 Nm frozen-state raw inverse. This is NOT a jointly chosen CBF correction. Original R1 constraints failed in closed loops.' newline ...
 'V67: source-exact generated Vfd is checked componentwise against F1 Ad^k e; compare against F1 Ac^k e and F1 ((Ad-I)/dt)^k e. Ac is a CONTINUOUS NOMINAL double-integrator error model ONLY; not a claim for actual nonlinear plant high derivatives.' newline ...
 'V67: actual first v1 derivative computed using original nonlinear plant at the SAME state for both nominal 4-input and R1-modified applied 4-input. Difference in thrust-numerator derivative is also reported. Do not set unknown thrust/input derivatives to zero.' newline ...
 'V67: alternative continuous-nominal 0..5 jet is evaluated in source inverse ONLY in SHADOW; NOT applied as controller, and NOT a proven valid high-order correction under CBF. No thrust floor, artificial input-rate limit, post-hoc smoothing, HLC gain change, or predictive control introduced.' newline ...
 'What must be established before a genuine 0..5 jointly determined correction: the chosen regularity of applied thrust and 3 torque inputs, input-affine/mixed-relative-order Lie derivatives, kinematic relation between actual v1 and derivatives along the full plant, generated source Vfd semantic choice, exact beta/alpha inverse equality, actuator bounds and CBF viability. Jet slots cannot be optimized independently without integrability.' newline ...
 'The raw HLC thrust-zero condition is determined by its ORIGINAL numerator N=0 at positive geometric D; measured strong vertical-velocity-feedback dependence does NOT imply an arbitrary fixed speed/height limit.' newline ...
 '========== V67 OBSERVED MATLAB OUTPUT ==========' newline];
summaryPath=fullfile(work,'V67_DERIVATIVE_SEMANTICS_SUMMARY.csv');
if isfile(summaryPath)
  recent=[recent evalc('disp(readtable(summaryPath))') newline];
else
  recent=[recent 'Summary was not produced; refer to error log' newline];
end
v23WriteText(fullfile(work,'V67_FULL_UPDATED_HANDOVER.txt'),[history recent]);
v23WriteText(fullfile(work,'V67_README_THEORY_AND_LIMITATIONS.txt'),recent);
end


% ===== V69 mathematical high-order jet / predicted sample audit =====
% These checks NEVER modify the 19-state plant, HLC gains or CBF.
% v69ContJet: true 0..5 continuous-time derivatives UNDER THE STATED
% error ODE e_dot=Ac*e-B*(delta+rho). It is not an assertion that the
% actual Flight follows this ODE with rho=0.
% v69DiscJet: k-step predicted values under the explicitly stated R193
% discrete update e_{j+1}=Ad*e_j-Bd*(delta_j+rho_j).
% Source Vfd has F*Ad^k*e at zero correction and is not a time jet.
function result = v69HighOrderJetOnly()
    F=[82.34,24.83]; % illustrative gains for algebraic audit, not a HLC edit
    kp=F(1);kd=F(2); h=0.025;
    Ac=[0,1;-kp,-kd];B=[0;1];
    Ad=[1-kp*h^2/2, h-kd*h^2/2; -kp*h, 1-kd*h];
    Bd=[h^2/2;h]; % source-discretization correction for ZOH acceleration
    labels={'ZERO_CORRECTION_IDEAL','SMOOTH_CORRECTION_IDEAL', ...
        'SMOOTH_CORRECTION_WITH_RESIDUAL','RESIDUAL_ONLY'};
    es=[-.025,-.005,.03,-.018; .14,-.06,.035,.08];
    ds=[zeros(6,1),[.18;-.43;1.25;-2;6;-12], ...
        [.18;-.43;1.25;-2;6;-12],zeros(6,1)];
    rs=[zeros(6,2),[.025;-.075;.2;-.35;1;-3], ...
        [.025;-.075;.2;-.35;1;-3]];
    fields={'caseName','orderK','continuousJ','continuousClosed', ...
        'discretePredictedV','discreteClosed','sourceNoCorrectionVfd', ...
        'continuousNominalDerivative','deltaDerivativeAtZero', ...
        'rhoDerivativeAtZero','absContinuousIdentityError', ...
        'absDiscreteIdentityError'};
    rows=cell(4*6,numel(fields));
    rc=0;maxCont=0;maxDisc=0;maxSource=0;
    for c=1:4
        e=es(:,c); d=ds(:,c);r=rs(:,c);
        [Jcont,Jcont2]=v69ContJet(e,F,Ac,B,d,r);
        [Jdisc,Jdisc2]=v69DiscJet(e,F,Ad,Bd,d,r,h);
        for k=0:5
            vc=F*(Ad^k)*e;
            errCont=abs(Jcont(k+1)-Jcont2(k+1));
            errDisc=abs(Jdisc(k+1)-Jdisc2(k+1));
            rc=rc+1;
            rows(rc,:)={labels{c},k,Jcont(k+1),Jcont2(k+1), ...
                 Jdisc(k+1),Jdisc2(k+1),vc,F*(Ac^k)*e, ...
                 d(k+1),r(k+1),errCont,errDisc};
            maxCont=max(maxCont,errCont);maxDisc=max(maxDisc,errDisc);
            if c==1
                maxSource=max(maxSource,abs(Jdisc(k+1)-vc));
            end
        end
    end
    outdir=fullfile(fileparts(mfilename('fullpath')),'_CBF_TEST_OUTPUT');
    if ~exist(outdir,'dir'),mkdir(outdir);end
    work=tempname;mkdir(work);
    cleanupWork=onCleanup(@()v69Cleanup(work));
    T=cell2table(rows,'VariableNames',fields);
    writetable(T,fullfile(work,'V69_JET_IDENTITY_AUDIT.csv'));
    theory=[ ...
      'V69 mathematical audit: two distinct generators, k=0,...,5.' newline ...
      'SOURCE: R193 generated Vfd(k+1)=F*Ad^k*e (predicted samples).' newline ...
      'Ac=[0 1;-kp -kd], Ad=[1-kp*h^2/2,h-kd*h^2/2;-kp*h,1-kd*h].' newline ...
      'CONTINUOUS ASSUMPTION e_dot=Ac*e-B*(delta+rho), B=[0;1].' newline ...
      'delta and rho are explicit smooth TEST inputs; rho is NOT assumed zero in general.' newline ...
      'q0=e; Jk=F*qk+delta^(k); q(k+1)=Ac*qk-B*(delta^(k)+rho^(k)).' newline ...
      'Closed: Jk=F*Ac^k*e + delta^(k) - sum_{j<k} F*Ac^(k-1-j)*B*(delta^(j)+rho^(j)).' newline ...
      'DISCRETE SOURCE-STYLE MODEL (sample sequence, NOT derivative):' newline ...
      'e(j+1)=Ad*e(j)-Bd*(delta_j+rho_j); Bd=[h*h/2;h].' newline ...
      'Vk=F*Ad^k*e + delta_k - sum_{j<k} F*Ad^(k-1-j)*Bd*(delta_j+rho_j).' newline ...
      'This Bd follows the source first-order velocity / second-order position step;' newline ...
      'it is NOT the exact ZOH discretization expm(Ac*h).' newline ...
      'ZERO-CORRECTION CONTINUOUS Jk and Vfd(k+1) are generally DIFFERENT by definition.' newline ...
      'NEVER add continuous derivative corrections to predicted-sample slots without' newline ...
      ' establishing the intended symbolic meaning in the original inverse map.' newline ...
      'CONTINUOUS Jk units: m/s^(2+k). DISCRETE Vk units: m/s^2 for all k.' newline ...
      'This unit test verifies algebraic identities only, not actual 19-state' newline ...
      ' plant Lie derivatives, actuator feasibility, CBF safety, or Flight behavior.' newline ...
      'No source HLC coefficients or CBF code were changed.' newline ...
      'No artificial thrust lower bound, zero rate, or assumed physical input dynamics.' newline ...
      'See V68_HIGH_ORDER_JET_THEORY_AND_HANDOVER.md from previous handover.' newline ...
      sprintf('NUMERICAL maxCont=%.12g; maxDisc=%.12g; maxSource=%.12g\n', ...
                  maxCont,maxDisc,maxSource)];
    fid=fopen(fullfile(work,'V69_THEORY_AND_HANDOVER.txt'),'w');
    assert(fid>=0,'Cannot open V69 handover output');
    fprintf(fid,'%s',theory);fclose(fid);
    tol=1e-8;
    passed=maxCont<tol && maxDisc<tol && maxSource<tol;
    if passed
       status='PASS_MATHEMATICAL_JET_IDENTITIES__NOT_FLIGHT_VALIDATION';
       nFailed=0;
    else
       status='FAILED_MATHEMATICAL_JET_IDENTITY';
       nFailed=1;
    end
    stamp=datestr(now,'yyyymmdd_HHMMSS_FFF');
    zipPath=fullfile(outdir,['CBF_HLC_JET_V69_' stamp '.zip']);
    v69WriteEmbeddedHistory(fullfile(work,'V69_FULL_UPDATED_HANDOVER.txt'));
    zip(zipPath,{'V69_JET_IDENTITY_AUDIT.csv','V69_THEORY_AND_HANDOVER.txt', ...
        'V69_FULL_UPDATED_HANDOVER.txt'},work);
    assert(exist(zipPath,'file')==2,'Output ZIP not created');
    result=struct('status',status,'zipPath',zipPath,'nCases',4, ...
       'nRuntimeErrors',0,'nFailedCases',nFailed,'nR1FilterStops',0, ...
       'maxContinuousIdentityError',maxCont, ...
       'maxDiscreteIdentityError',maxDisc, ...
       'maxSourceIdentityError',maxSource);
end

function [jet,closed]=v69ContJet(e,F,A,B,d,r)
    q=zeros(2,6);jet=zeros(1,6);closed=zeros(1,6);
    q(:,1)=e;
    for k=0:5
        jet(k+1)=F*q(:,k+1)+d(k+1);
        val=F*(A^k)*e + d(k+1);
        for j=0:k-1
            val=val-F*(A^(k-1-j))*B*(d(j+1)+r(j+1));
        end
        closed(k+1)=val;
        if k<5
            q(:,k+2)=A*q(:,k+1)-B*(d(k+1)+r(k+1));
        end
    end
end

function [vals,closed]=v69DiscJet(e,F,A,Bd,d,r,h)
    q=zeros(2,6);vals=zeros(1,6);closed=zeros(1,6);
    q(:,1)=e;
    dc=zeros(1,6);rr=zeros(1,6);
    for k=0:5
        t=k*h;
        dc(k+1)=v69Taylor(d,t);
        rr(k+1)=v69Taylor(r,t);
    end
    for k=0:5
        vals(k+1)=F*q(:,k+1)+dc(k+1);
        val=F*(A^k)*e+dc(k+1);
        for j=0:k-1
            val=val-F*(A^(k-1-j))*Bd*(dc(j+1)+rr(j+1));
        end
        closed(k+1)=val;
        if k<5
            q(:,k+2)=A*q(:,k+1)-Bd*(dc(k+1)+rr(k+1));
        end
    end
end

function y=v69Taylor(jet,t)
    y=0;
    for n=0:numel(jet)-1
        y=y+jet(n+1)*(t^n)/factorial(n);
    end
end

function v69Cleanup(work)
    if exist(work,'dir')==7,rmdir(work,'s');end
end


function v69WriteEmbeddedHistory(filePath)
    % Copy archived previous context from this single .m file so that the
    % result ZIP contains the complete previous V67 handover and V68 theory.
    src=fileread([mfilename('fullpath') '.m']);
    beginTag=['% V69_FULL_' 'HISTORY_BEGIN'];
    endTag=['% V69_FULL_' 'HISTORY_END'];
    ix=strfind(src,beginTag);iy=strfind(src,endTag);
    if numel(ix)~=1 || numel(iy)~=1 || iy(1)<=ix(1)
        error('V69:HistoryNotEmbedded','Embedded handover markers missing');
    end
    content=src(ix(1)+numel(beginTag):iy(1)-1);
    content=regexprep(content,'(?m)^%[|]','');
    f=fopen(filePath,'w','n','UTF-8');
    assert(f>=0,'Cannot write embedded cumulative handover');
    fprintf(f,'%s',content);
    fclose(f);
end

