%|## 取り扱い
%|V70の研究引継ぎ原文は受領ZIP内 `V70_FULL_UPDATED_HANDOVER.txt` に収録。今回の文書はその内容を改変せず、**実行結果に基づいた判定と残課題を追記するための別添**である。
% V71_FULL_HISTORY_END

% ========================================================================
% V72: SOURCE-FAITHFUL 25ms ZERO-ORDER HOLD (ZOH) PHYSICAL JETS.
% No 6-stage filter. At t_n the physical state is continuous; the four
% applied commands u_(n-1),u_n may jump. On either open hold interval,
% u^(k) = 0 for k>=1 by the ACTUAL simulation signal law. Compute the
% order 0..5 v1 one-sided jets independently with the same x(t_n).
% Continuous-time jets at t_n need not have a two-sided derivative.
% This is NOT sampled-data CBF certification or HLC inverse redesign.
% ========================================================================
function result=v72ActualZOHBoundaryJet(opts)
    root=fileparts(mfilename('fullpath'));
    if exist('test_CBF_SetupPaths','file')==2,test_CBF_SetupPaths();end
    required={'CBF_V19_Scenarios','with_load_model_euler_for_HL', ...
        'CBF_V19_OriginalPlantStep','lqrd'};
    for ii=1:numel(required)
        if exist(required{ii},'file')==0
            error('CBF:V72SourceMissing','Required R193 file missing: %s',required{ii});
        end
    end
    if exist('HLC_SUSPENDED_LOAD','class')~=8
        error('CBF:V72HLCMissing','HLC_SUSPENDED_LOAD class missing');
    end
    sc=CBF_V19_Scenarios('straight_single','R193');
    sc.dt=0.025; s=sc.settings;
    H=v23MakeHLC(s,sc.dt);
    massEstimate=0.01; % R193 historical HLC initial estimate, not physical truth
    if isfield(opts,'v72MassEstimate'),massEstimate=opts.v72MassEstimate;end
    assert(isscalar(massEstimate)&&isfinite(massEstimate)&&massEstimate>0, ...
        'CBF:V72MassEstimate');
    horizon=2.4;
    if isfield(opts,'v72Horizon'),horizon=opts.v72Horizon;end
    assert(isscalar(horizon)&&horizon>=0.025&&horizon<=4, ...
        'CBF:V72Horizon');
    nSteps=round(horizon/sc.dt);
    lo=[s.input.thrustMin;s.input.torqueMin(:)];
    hi=[s.input.thrustMax;s.input.torqueMax(:)];
    modes={'NOMINAL_ZOH','ORIGINAL_R1_ZOH'};
    samples=struct([]);summary=struct([]);
    maxModel=0;maxDirect=0;maxTaylor=0;
    maxJ0=0;maxJumpIdentity=0;maxBoundaryJetJump=0;
    for mi=1:numel(modes)
        mode=modes{mi};
        if mi==2 && exist('CBF_V18_R1_RectifiedCable','file')~=2
            error('CBF:V72R1Missing', ...
                'Original CBF_V18_R1_RectifiedCable is required');
        end
        x=sc.x0(:);
        assert(numel(x)==19&&all(isfinite(x)),'CBF:V72InitialState');
        prevU=nan(4,1);nR1=0;nUpdates=0;firstR1=NaN;
        stopReason='HORIZON_REACHED';
        caseModel=0;caseDirect=0;caseTaylor=0;caseJ0=0;
        caseOriginalStepError=0;
        caseIdentity=0;caseJetJump=0;caseInputJump=0;
        maxRawTorque=0;minRawThrust=Inf;lastTime=0;count=0;
        for n=0:nSteps
            t=n*sc.dt;
            a=v23HLC(x,t,sc,H,massEstimate);
            u=min(hi,max(lo,a.raw(:)));
            if mi==2 && t>=2.125-1e-9
                [candidate,reason]=v25R1ExactFilter(x,s,sc.obstacles,u);
                if ~strcmp(reason,'OK')
                    stopReason=['R1_UNAVAILABLE_' reason];
                    break; % No fictional fallback and no safety-success claim
                end
                u=candidate(:);
                nR1=nR1+1;
                if isnan(firstR1),firstR1=t;end
            end
            if numel(u)~=4||any(~isfinite(u))
                stopReason='NONFINITE_APPLIED_ZOH';break;
            end
            boundError=max([lo-u;u-hi;0]);
            if boundError>1e-8
                stopReason='PHYSICAL_COMMAND_OUT_OF_BOUNDS';break;
            end
            % Real applied command is exactly constant on (t_n,t_(n+1)).
            % This assumption is grounded in the *existing* R193 simulation.
            Uright=zeros(4,5);Uright(:,1)=u;
            [Jr,~]=v70PhysicalJet(x,Uright,s,sc,t,H.F1);
            [d,~]=deal(v70RHS19(x,u,s),[]);
            ref0=sc.ref(t,0);ref1=sc.ref(t,1);ref2=sc.ref(t,2);
            direct0=H.F1(1)*(ref0(3)-x(10))+H.F1(2)*(ref1(3)-x(13));
            direct1=H.F1(1)*(ref1(3)-x(13))+H.F1(2)*(ref2(3)-d(13));
            directError=max(abs([Jr(1)-direct0,Jr(2)-direct1]));
            original=v70Source24(x,u,s);
            from24=[d(1:4);original(10:12);original(13:15); ...
                original(16:18);original(19:21);original(22:24)];
            modelError=max(abs(d-from24));
            % Short local Taylor validation wholly WITHIN THIS HOLD interval.
            h=0.001;
            xx=v70Step(x,u,s,h,12);
            p1=sc.ref(t+h,0);v1=sc.ref(t+h,1);
            vExpected=H.F1(1)*(p1(3)-xx(10))+H.F1(2)*(v1(3)-xx(13));
            vTaylor=sum(Jr.*(h.^(0:5))./factorial(0:5));
            localTaylorError=abs(vExpected-vTaylor);
            if n==0
                Jl=nan(1,6);uLeft=nan(4,1);
                j0Error=NaN;firstJump=NaN;analyticJump=NaN;
                analyticJumpError=NaN;inputJump=NaN;jetJump=NaN;
                hasLeft=false;
            else
                % At SAME x_n, t_n: previous held input defines LEFT jet,
                % newly selected applied input defines RIGHT jet.
                uLeft=prevU;
                Uleft=zeros(4,5);Uleft(:,1)=uLeft;
                [Jl,~]=v70PhysicalJet(x,Uleft,s,sc,t,H.F1);
                j0Error=abs(Jr(1)-Jl(1));
                firstJump=Jr(2)-Jl(2);
                b3=v72ThrustAxis(x(1:4));
                analyticJump=-H.F1(2)*x(16)*dot(x(14:16),b3)* ...
                    (u(1)-uLeft(1))/(s.physical.massDrone+s.physical.massLoad);
                analyticJumpError=abs(firstJump-analyticJump);
                inputJump=norm(u-uLeft,Inf);
                jetJump=norm(Jr-Jl,Inf);
                nUpdates=nUpdates+1;
                caseJ0=max(caseJ0,j0Error);
                caseIdentity=max(caseIdentity,analyticJumpError);
                caseJetJump=max(caseJetJump,jetJump);
                caseInputJump=max(caseInputJump,inputJump);
            end
            caseModel=max(caseModel,modelError);
            caseDirect=max(caseDirect,directError);
            caseTaylor=max(caseTaylor,localTaylorError);
            maxRawTorque=max(maxRawTorque,norm(a.tau,Inf));
            minRawThrust=min(minRawThrust,a.thrust);
            count=count+1;lastTime=t;
            rec=struct('mode',mode,'time_s',t,'sampleIndex',n, ...
                'hasLeftHold',hasLeft,'rawHLCThrust_N',a.thrust, ...
                'rawHLCTorqueInf_Nm',norm(a.tau,Inf), ...
                'appliedThrust_N',u(1),'appliedTauX',u(2), ...
                'appliedTauY',u(3),'appliedTauZ',u(4), ...
                'previousThrust_N',uLeft(1), ...
                'previousTauX',uLeft(2),'previousTauY',uLeft(3), ...
                'previousTauZ',uLeft(4),'commandJumpInf',inputJump, ...
                'v1Jet0Left',Jl(1),'v1Jet1Left',Jl(2), ...
                'v1Jet2Left',Jl(3),'v1Jet3Left',Jl(4), ...
                'v1Jet4Left',Jl(5),'v1Jet5Left',Jl(6), ...
                'v1Jet0Right',Jr(1),'v1Jet1Right',Jr(2), ...
                'v1Jet2Right',Jr(3),'v1Jet3Right',Jr(4), ...
                'v1Jet4Right',Jr(5),'v1Jet5Right',Jr(6), ...
                'v1ValueJumpError',j0Error,'v1FirstDerivativeJump',firstJump, ...
                'v1FirstDerivativeJumpFromPlant',analyticJump, ...
                'firstDerivativeJumpIdentityError',analyticJumpError, ...
                'maxJetJumpInf',jetJump, ...
                'directJet01Error',directError,'source24RhsError',modelError, ...
                'oneMsTaylorError',localTaylorError, ...
                'original24StepVsReduced19Error',NaN, ...
                'loadHeight_m',x(10),'loadVerticalSpeed_mps',x(13), ...
                'beta2SigmaMin',a.sigmaMin, ...
                'appliedInputLaw','ACTUAL_ZOH_25MS_RIGHT_OPEN_HOLD', ...
                'classicalTwoSidedDerivativeAtUpdate','NOT_ASSUMED');
            if isempty(samples),samples=rec;else,samples(end+1)=rec;end %#ok<AGROW>
            if ~(isfinite(modelError)&&isfinite(directError)&&isfinite(localTaylorError) ...
                    && modelError<5e-9 && directError<1e-8 && localTaylorError<1e-5)
                stopReason='R193_SOURCE_OR_JET_VALIDATION_FAILED';break;
            end
            if n>0 && (j0Error>1e-8||analyticJumpError>1e-7)
                stopReason='ZOH_BOUNDARY_IDENTITY_FAILED';break;
            end
            if n<nSteps
                % Exactly one applied 4-input held across this 25ms interval.
                % Use SAME original R193 ZOH plant step as historical baseline.
                % Reduced19 RK4 is an independent RHS-consistency witness.
                xOriginal=CBF_V19_OriginalPlantStep(x,u,s,sc.dt,4);
                xReduced=v70Step(x,u,s,sc.dt,4);
                stepError=max(abs(xOriginal(:)-xReduced(:)));
                samples(end).original24StepVsReduced19Error=stepError;
                caseOriginalStepError=max(caseOriginalStepError,stepError);
                x=xOriginal(:);
                if any(~isfinite(x))
                    stopReason='NONFINITE_PLANT_STATE';break;
                end
                prevU=u;
            end
        end
        maxModel=max(maxModel,caseModel);maxDirect=max(maxDirect,caseDirect);
        maxTaylor=max(maxTaylor,caseTaylor);maxJ0=max(maxJ0,caseJ0);
        maxJumpIdentity=max(maxJumpIdentity,caseIdentity);
        maxBoundaryJetJump=max(maxBoundaryJetJump,caseJetJump);
        pass=strcmp(stopReason,'HORIZON_REACHED');
        record=struct('mode',mode,'stopReason',stopReason, ...
            'reachedHorizon',pass,'nSamplesRecorded',count, ...
            'lastTime_s',lastTime,'nUpdates',nUpdates, ...
            'nR1FilterDecisions',nR1,'firstR1Decision_s',firstR1, ...
            'maxPhysicalInputJumpInf',caseInputJump, ...
            'maxV1JetBoundaryDifferenceInf',caseJetJump, ...
            'maxV1ZerothContinuityError',caseJ0, ...
            'maxAnalyticFirstJetJumpError',caseIdentity, ...
            'maxR193Source24RHSerror',caseModel, ...
            'maxDirectJet01Error',caseDirect, ...
            'maxOneMsTaylorError',caseTaylor, ...
            'maxOriginal24StepVsReduced19Error',caseOriginalStepError, ...
            'maxRawHLCTorqueInf',maxRawTorque, ...
            'minRawHLCThrust',minRawThrust, ...
            'physicalInputLaw','R193_IDEAL_25MS_ZOH', ...
            'safetyCertified',false);
        if isempty(summary),summary=record;else,summary(end+1)=record;end %#ok<AGROW>
    end
    numericalOk= maxModel<5e-9 && maxDirect<1e-8 ...
        && maxTaylor<1e-5 && maxJ0<1e-8 && maxJumpIdentity<1e-7 ...
        && ~any(strcmp({summary.stopReason},'R193_SOURCE_OR_JET_VALIDATION_FAILED')) ...
        && ~any(strcmp({summary.stopReason},'ZOH_BOUNDARY_IDENTITY_FAILED'));
    outdir=fullfile(root,'_CBF_TEST_OUTPUT');
    if exist(outdir,'dir')~=7,mkdir(outdir);end
    work=tempname;mkdir(work);cleanup=onCleanup(@()v69Cleanup(work)); %#ok<NASGU>
    writetable(struct2table(summary),fullfile(work,'V72_ZOH_BOUNDARY_SUMMARY.csv'));
    writetable(struct2table(samples),fullfile(work,'V72_ZOH_C0_C5_ONE_SIDED_JETS.csv'));
    theory=v72TheoryChapter();
    v23WriteText(fullfile(work,'V72_ZOH_THEORY_AND_ERROR_REVIEW.txt'),theory);
    v71WriteFullHandover(fullfile(work,'V72_FULL_CUMULATIVE_HANDOVER.txt'), ...
        sprintf('%s\n%s',v71HandoverChapter(),theory));
    status='PASS_R193_ZOH_ONE_SIDED_C0_C5_MODEL_CONDITIONAL__NO_SAFETY_CERTIFICATION';
    if ~numericalOk,status='FAIL_V72_ZOH_MODEL_OR_JET_VALIDATION';end
    stamp=datestr(now,'yyyymmdd_HHMMSS_FFF');
    zipPath=fullfile(outdir,['CBF_HLC_JET_V72_' stamp '.zip']);
    zip(zipPath,{'V72_ZOH_BOUNDARY_SUMMARY.csv', ...
        'V72_ZOH_C0_C5_ONE_SIDED_JETS.csv', ...
        'V72_ZOH_THEORY_AND_ERROR_REVIEW.txt', ...
        'V72_FULL_CUMULATIVE_HANDOVER.txt'},work);
    assert(exist(zipPath,'file')==2,'CBF:V72ResultZipNotCreated');
    fatal=sum(~ismember({summary.stopReason}, ...
        {'HORIZON_REACHED','R1_UNAVAILABLE_INFEASIBLE_SHARED_THRUST', ...
         'R1_UNAVAILABLE_INITIAL_RECTIFIED_SET_INVALID', ...
         'R1_UNAVAILABLE_ZERO_INPUT_AUTHORITY_POSITIVE_RHS', ...
         'R1_UNAVAILABLE_NONAFFINE_OR_EARLY_TORQUE'}));
    result=struct('status',status,'zipPath',zipPath, ...
        'nCases',numel(summary),'nRuntimeErrors',0, ...
        'nFailedCases',double(~numericalOk)+fatal, ...
        'nR1FilterStops',sum(startsWith(string({summary.stopReason}), ...
            'R1_UNAVAILABLE_')),'maxSourceError',maxModel, ...
        'maxTaylorError',maxTaylor,'maxJet0JumpError',maxJ0, ...
        'maxFirstJetJumpIdentityError',maxJumpIdentity, ...
        'maxLegitimateBoundaryJetDifference',maxBoundaryJetJump);
end

function b3=v72ThrustAxis(q)
    q=q(:);
    b3=[2*(q(2)*q(4)+q(1)*q(3)); ...
        2*(q(3)*q(4)-q(1)*q(2)); ...
        q(1)^2-q(2)^2-q(3)^2+q(4)^2];
end

function theory=v72TheoryChapter()
    theory=sprintf([ ...
    'V72 ZOH 25ms PHYSICAL ONE-SIDED HIGH-ORDER DERIVATIVES\n' ...
    'Date 2026-11-18; based on original R193 HLC and physical plant.\n' ...
    'IMPORTANT USER CORRECTION: original HLC and R1 both update every\n' ...
    '  25ms; applied four controls are ZOH and actually held between updates.\n' ...
    '  DO NOT insert a six-stage command filter merely to obtain C5 inputs.\n' ...
    '  V71 changed the physical input law and cannot prove original HLC behavior.\n' ...
    'V71 ERROR ARCHIVE 20261118_121412: MATLAB row width mismatch: at\n' ...
    '  v71CausalC5JetTest line 32015, rows initialized cell(0,25) but\n' ...
    '  26 cells appended. V71 produced NO flight-validation CSV; this is\n' ...
    '  a software instrumentation error, NOT high-order mathematics failure.\n' ...
    'MATHEMATICAL ZOH SIGNAL: u(t)=u_n on [t_n,t_(n+1)), dt=0.025s.\n' ...
    '  For each open interval (t_n,t_(n+1)), u^(j)=0, j>=1 BY DEFINITION\n' ...
    '  of the APPLIED simulation input, not as an arbitrary approximation.\n' ...
    '  At a boundary t_n, x(t_n-) = x(t_n+) in the ideal plant, but\n' ...
    '  u(t_n-) = u_(n-1), u(t_n+) = u_n; one-sided state output jets\n' ...
    '  can differ. Their equality is NOT required by sampled-data HLC.\n' ...
    '  If controls jump, classical two-sided input derivatives and output\n' ...
    '  high-order derivatives may be undefined AT THAT SINGLE INSTANT.\n' ...
    '  Do NOT conflate this with CBF on/off; nominal HLC updates too.\n' ...
    'MEASURABLE / AVAILABLE in the R193 IDEAL SIMULATION: current 19-state\n' ...
    '  estimate-layout x, known actually applied 4-command u_(n-1) and u_n,\n' ...
    '  known reference derivatives 0..6 and model source parameters.\n' ...
    '  Source-matched 19-state v70RHS19 and Taylor AD v70PhysicalJet are\n' ...
    '  unchanged. For each left/right hold, pass U=[u, zeros(4,4)].\n' ...
    '  Then compute J_(0..5) from the genuine plant (not finite differences).\n' ...
    '  All jets depend only on the CURRENT state and the CURRENT or PREVIOUS\n' ...
    '  known held command. No future HLC/CBF input or new actuator state.\n' ...
    'ANALYTIC SAME-STATE BOUNDARY CHECK for v1=kp*(zd-zL)+kd*(vzd-vL):\n' ...
    '  J0+ - J0- = 0;\n' ...
    '  J1+ - J1- = -kd*(pTz*(pT dot b3)/(m+mL))*(T_n-T_(n-1)).\n' ...
    '  At that instant, torque jumps need not directly enter v1 dot.\n' ...
    '  Higher one-sided jets include true torque effects through dynamics.\n' ...
    'TEST: original NOMINAL_ZOH versus original R1_ZOH without any filter,\n' ...
    '  no modifications to HLC, original R1, or physical dynamics.\n' ...
    '  Applied 4 inputs exactly clipped as in original baseline. R1 failure\n' ...
    '  stops case, never silently falls back or calls it safe.\n' ...
    '  Use original CBF_V19_OriginalPlantStep with 4 substeps to propagate\n' ...
    '  each hold, and independently compare v70Step (same RK4 schedule).\n' ...
    '  Source24 RHS equality, direct J0/J1, one-ms Taylor vs RK4, boundary\n' ...
    '  J0 continuity and analytic J1 jump tested. Actual left/right\n' ...
    '  high-order derivative DIFFERENCES are recorded, NOT marked errors.\n' ...
    '  A sampled-data CBF safety guarantee requires enforcing a discrete\n' ...
    '  condition or verified safety across EACH intersample hold. Checking\n' ...
    '  one-sided jets alone does not prove any barrier invariance.\n' ...
    '  This is not a continuous-time C5 input controller or complete CBF.\n' ...
    '  No arbitrary new nominal thrust floor. HLC mass estimate 0.01kg\n' ...
    '  differs from simulator physical 0.14kg; real actuator behavior and\n' ...
    '  high-order jet accuracy on hardware are not verified.\n' ...
    '  V67 source Vfd retains discrete nominal value semantics; physical\n' ...
    '  ZOH one-sided jets are NOT silently plugged into Vs/V2_alpha2.\n' ...
    '  Next: validate source HLC inverse semantic correspondence, then\n' ...
    '  design sampled-data CBF using original dt, held 4 physical inputs,\n' ...
    '  full physical constraints and intersample safety, no postfilter.\n' ...
    'CUMULATIVE HISTORY: previous original research history preserved;\n' ...
    '  V71 theoretical trial and error provenance recorded; V72 added.\n']);
end

function result=v72ErrorArtifact(ME)
    root=fileparts(mfilename('fullpath'));
    outdir=fullfile(root,'_CBF_TEST_OUTPUT');
    if exist(outdir,'dir')~=7,mkdir(outdir);end
    work=tempname;mkdir(work);cleanup=onCleanup(@()v69Cleanup(work)); %#ok<NASGU>
    report=getReport(ME,'extended','hyperlinks','off');
    v23WriteText(fullfile(work,'V72_RUNTIME_ERROR.txt'),report);
    try
        v71WriteFullHandover(fullfile(work,'V72_FULL_CUMULATIVE_HANDOVER.txt'), ...
            sprintf('%s\n%s',v71HandoverChapter(),v72TheoryChapter()));
        names={'V72_RUNTIME_ERROR.txt','V72_FULL_CUMULATIVE_HANDOVER.txt'};
    catch EH
        v23WriteText(fullfile(work,'V72_HANDOVER_ERROR.txt'),EH.message);
        names={'V72_RUNTIME_ERROR.txt','V72_HANDOVER_ERROR.txt'};
    end
    stamp=datestr(now,'yyyymmdd_HHMMSS_FFF');
    zipPath=fullfile(outdir,['CBF_HLC_JET_V72_ERROR_' stamp '.zip']);
    zip(zipPath,names,work);
    result=struct('status',['FAILED_V72_RUNTIME_' ME.identifier], ...
        'zipPath',zipPath,'nCases',0,'nRuntimeErrors',1, ...
        'nFailedCases',1,'nR1FilterStops',0);
end


function result=v74InverseConsistencyShadow(opts)
% No changes to R193 HLC, original 25ms ZOH or original R1 policy.
% Unlike V65, this includes 0..4 realized V1 jet from the same u=[T;tau].
% Fifth feedback derivative is audited separately; realized v1^(5)
% requires reference degree seven and is NOT used by source inverse map.
root=fileparts(mfilename('fullpath'));
if exist('test_CBF_SetupPaths','file')==2,test_CBF_SetupPaths();end
required={'CBF_V19_Scenarios','CBF_V19_OriginalPlantStep','lqrd', ...
    'CBF_V18_R1_RectifiedCable'};
for k=1:numel(required)
    if exist(required{k},'file')==0
        error('CBF:V74SourceMissing','Required source missing: %s',required{k});
    end
end
if exist('HLC_SUSPENDED_LOAD','class')~=8
    error('CBF:V74HLCMissing','HLC_SUSPENDED_LOAD missing');
end
sc=CBF_V19_Scenarios('straight_single','R193');sc.dt=0.025;
s=sc.settings;H=v23MakeHLC(s,sc.dt);
mhat=0.01;
if isfield(opts,'v74MassEstimate'),mhat=opts.v74MassEstimate;end
assert(isscalar(mhat)&&isfinite(mhat)&&mhat>0,'CBF:V74Mass');
sest=s;sest.physical.massLoad=mhat; % only controller-known estimate
lo=[s.input.thrustMin;s.input.torqueMin(:)];
hi=[s.input.thrustMax;s.input.torqueMax(:)];
allRows=struct([]); allSummary=struct([]); errors=0;
labels={'NOMINAL_ZOH','ORIGINAL_R1_ZOH'};
for im=1:numel(labels)
    mode=labels{im};x=sc.x0(:);stop='HORIZON_REACHED';
    maxMap=0;minRawT=Inf;maxRawTau=0;maxPhysics=0;
    lastT=NaN; nMeasured=0;nMapFail=0;nOpt=0;
    for n=0:round(2.35/sc.dt)
        t=n*sc.dt;
        a=v23HLC(x,t,sc,H,mhat);
        u=min(hi,max(lo,a.raw(:)));
        if im==2 && t>=2.125-1e-9
            [candidate,reason]=v25R1ExactFilter(x,s,sc.obstacles,u);
            if ~strcmp(reason,'OK')
                stop=['R1_UNAVAILABLE_' reason];break;
            end
            u=candidate(:);
        end
        if any(~isfinite(u)) || any(u<lo-1e-8) || any(u>hi+1e-8)
            stop='INVALID_PHYSICAL_ZOH_COMMAND';break;
        end
        lastT=t;
        if t>=2.125-1e-9 && t<=2.325+1e-9
            nMeasured=nMeasured+1;
            rec=struct('mode',mode,'time_s',t,'status','OK', ...
                'sourceHlcThrust_N',a.thrust, ...
                'sourceRawTorqueInf_Nm',norm(a.tau,Inf), ...
                'appliedThrust_N',u(1), ...
                'appliedTauX_Nm',u(2),'appliedTauY_Nm',u(3), ...
                'appliedTauZ_Nm',u(4), ...
                'estimatedMass_kg',mhat, ...
                'plantMass_kg',s.physical.massLoad, ...
                'sourceBetaSigmaMin',a.sigmaMin, ...
                'sourceInverseResidual',norm(a.beta*a.tau-a.alpha,Inf), ...
                'sourcePhysicalResidual',norm(a.beta*u(2:4)-a.alpha,Inf), ...
                'sourceVirtualVsNorm',norm(a.vsRaw,Inf), ...
                'sourceV1Jet0',a.vfRaw(1), ...
                'remap0RawTorqueInf',NaN, ...
                'remap0PhysicalResidual',NaN, ...
                'remap0VsDeltaToMatchApplied',NaN, ...
                'feedbackJetRawTorqueInf',NaN, ...
                'feedbackJetPhysicalResidual',NaN, ...
                'realJetRawTorqueInf',NaN, ...
                'realJetPhysicalResidual',NaN, ...
                'realJetThrustIdentityError',NaN, ...
                'realVsIndependentPhysicalResidual',NaN, ...
                'realVsActualMinusNominalInf',NaN, ...
                'realVsCorrectionToMatchAppliedInf',NaN, ...
                'realVsCorrectionRelative',NaN, ...
                'realVsAffineError',NaN, ...
                'realBetaSigmaMin',NaN, ...
                'realV1Jet0',NaN,'realV1Jet1',NaN, ...
                'realV1Jet2',NaN,'realV1Jet3',NaN, ...
                'realV1Jet4',NaN,'feedbackV1Jet5',NaN, ...
                'realV1FifthAvailable',false, ...
                'realV2Sixth',NaN,'realV3Sixth',NaN, ...
                'realYawSecond',NaN, ...
                'feasibleSearchPerformed',false, ...
                'feasibleTauInf',NaN, ...
                'feasibleVsDeviationFromSourceInf',NaN, ...
                'feasibleInverseResidual',NaN, ...
                'feasibleCostImprovement',NaN, ...
                'feasibleTauX',NaN,'feasibleTauY',NaN, ...
                'feasibleTauZ',NaN, ...
                'correctedJetIsGenuinePhysicalDerivative',true, ...
                'correctedVsIsIndependentPhysicalDerivative',false, ...
                'cbfSafetyCertified',false);
            try
                % Source RE-MAP0: physical thrust -> V1(0), source higher values retained.
                vf0=v60EquivalentV1(a,u(1));
                mm0=v74InverseMap(x,a,H,vf0);
                rec.remap0RawTorqueInf=mm0.rawTauInf;
                rec.remap0PhysicalResidual=norm(mm0.beta*u(2:4)-mm0.alpha,Inf);
                [dvs0,rr0,~,~]=v74MatchVs(x,a,H,vf0,u,mm0);
                if isfinite(rr0),rec.remap0VsDeltaToMatchApplied=norm(dvs0,Inf);end
                % Physical jets: SAME state, SAME *applied* u, estimated mass.
                [vReal,vFb,vActual,xJet]=v74RealJet(x,u,sest,sc,t,H.F1,a.XD);
                rec.realV1Jet0=vReal(1);rec.realV1Jet1=vReal(2);
                rec.realV1Jet2=vReal(3);rec.realV1Jet3=vReal(4);
                rec.realV1Jet4=vReal(5);rec.feedbackV1Jet5=vFb(6);
                rec.realV2Sixth=vActual(1);
                rec.realV3Sixth=vActual(2);rec.realYawSecond=vActual(3);
                fbag=v74InverseMap(x,a,H,vFb);
                rec.feedbackJetRawTorqueInf=fbag.rawTauInf;
                rec.feedbackJetPhysicalResidual=norm(fbag.beta*u(2:4)-fbag.alpha,Inf);
                mm=v74InverseMap(x,a,H,vReal);
                rec.realJetRawTorqueInf=mm.rawTauInf;
                rec.realJetPhysicalResidual=norm(mm.beta*u(2:4)-mm.alpha,Inf);
                rec.realBetaSigmaMin=min(svd(mm.beta));
                % Uf matches actual acceleration only under ESTIMATED model.
                rec.realJetThrustIdentityError=abs(mm.thrust-u(1));
                alphaPhysical=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
                    x,a.XD,vReal,vActual(:),a.HLCparam);
                rec.realVsIndependentPhysicalResidual= ...
                    norm(mm.beta*u(2:4)-alphaPhysical(:),Inf);
                rec.realVsActualMinusNominalInf=norm(vActual(:)-mm.vs,Inf);
                [dvs,rr,M,affineErr]=v74MatchVs(x,a,H,vReal,u,mm);
                rec.realVsAffineError=affineErr;
                if isfinite(rr)
                    rec.realVsCorrectionToMatchAppliedInf=norm(dvs,Inf);
                    rec.realVsCorrectionRelative=norm(dvs,Inf)/ ...
                        max(1,norm(mm.vs,Inf));
                end
                maxMap=max(maxMap,rec.realVsIndependentPhysicalResidual);
                maxPhysics=max(maxPhysics,rec.realJetThrustIdentityError);
                % Independent physical-output identity is NOT enforced by selecting Vs.
                % If it fails, record failure rather than calling exact-map feasible.
                if rec.realJetThrustIdentityError>1e-6*max(1,abs(u(1)))
                    rec.status='THRUST_INVERSE_INCONSISTENT';nMapFail=nMapFail+1;
                elseif rec.realVsIndependentPhysicalResidual> ...
                         1e-5*max(1,norm(mm.beta*u(2:4),Inf))
                    rec.status='PHYSICAL_OUTPUT_INVERSE_IDENTITY_FAILED';
                    nMapFail=nMapFail+1;
                end
                % 3-axis bounded shadow search at only the two diagnostic times.
                if im==2 && strcmp(rec.status,'OK') && ...
                     any(abs(t-[2.275,2.300])<1e-8) && ...
                     all(isfinite(M(:))) && rcond(M)>1e-11
                    [best,baseCost,improved]=v74BoundedShadowSearch( ...
                        x,a,H,sest,sc,t,u,lo,hi);
                    rec.feasibleSearchPerformed=true;nOpt=nOpt+1;
                    if isfinite(baseCost) && isfinite(improved) && ...
                            isfinite(best.residual)
                        rec.feasibleTauInf=norm(best.tau,Inf);
                        rec.feasibleTauX=best.tau(1);
                        rec.feasibleTauY=best.tau(2);
                        rec.feasibleTauZ=best.tau(3);
                        rec.feasibleVsDeviationFromSourceInf=best.distanceInf;
                        rec.feasibleInverseResidual=best.residual;
                        rec.feasibleCostImprovement=baseCost-improved;
                    else
                        rec.status='BOUNDED_SHADOW_SEARCH_NO_FINITE_CANDIDATE';
                    end
                end
            catch MEinner
                rec.status=['SHADOW_ERROR_' MEinner.identifier];errors=errors+1;
            end
            if isempty(allRows),allRows=rec;else,allRows(end+1)=rec;end %#ok<AGROW>
        end
        minRawT=min(minRawT,a.thrust);
        maxRawTau=max(maxRawTau,norm(a.tau,Inf));
        if n<round(2.35/sc.dt)
            x=CBF_V19_OriginalPlantStep(x,u,s,sc.dt,4);
            if any(~isfinite(x)),stop='PLANT_STATE_NONFINITE';break;end
        end
    end
    r=struct('mode',mode,'lastTime_s',lastT,'stopReason',stop, ...
        'nShadowSamples',nMeasured,'maxSourceRawTorqueInf_Nm',maxRawTau, ...
        'minSourceRawThrust_N',minRawT, ...
        'maxIndependentPhysicalInverseResidual',maxMap, ...
        'maxRealizedThrustInverseError',maxPhysics, ...
        'nPhysicalInverseIdentityFailures',nMapFail, ...
        'nFeasibleShadowSearches',nOpt, ...
        'nShadowRuntimeErrors',errors, ...
        'flightPolicy','UNMODIFIED_R193_25MS_ZOH', ...
        'new4InputCBFImplemented',false, ...
        'safetyCertified',false);
    if isempty(allSummary),allSummary=r;else,allSummary(end+1)=r;end %#ok<AGROW>
end
rootout=fullfile(root,'_CBF_TEST_OUTPUT');
if exist(rootout,'dir')~=7,mkdir(rootout);end
work=tempname;mkdir(work);cc=onCleanup(@()v69Cleanup(work)); %#ok<NASGU>
writetable(struct2table(allRows),fullfile(work,'V74_INVERSE_JET_SHADOW.csv'));
writetable(struct2table(allSummary),fullfile(work,'V74_SHADOW_SUMMARY.csv'));
v23WriteText(fullfile(work,'V74_SCOPE_AND_LIMITS.txt'),v74TheoryChapter());
v74WriteHandover(fullfile(work,'V74_FULL_CUMULATIVE_HANDOVER.txt'));
zipname=['CBF_HLC_INVERSE_V74_' datestr(now,'yyyymmdd_HHMMSS_FFF') '.zip'];
zipPath=fullfile(rootout,zipname);
zip(zipPath,{'V74_INVERSE_JET_SHADOW.csv','V74_SHADOW_SUMMARY.csv', ...
    'V74_SCOPE_AND_LIMITS.txt','V74_FULL_CUMULATIVE_HANDOVER.txt'},work);
assert(exist(zipPath,'file')==2,'CBF:V74ZIPMissing');
if errors>0
    status='INCOMPLETE_V74_SHADOW_RUNTIME_ERRORS';
elseif any([allSummary.nPhysicalInverseIdentityFailures]>0)
    status='V74_PHYSICAL_INVERSE_IDENTITY_DISAGREES__REQUIRES_DERIVATION_REVIEW';
else
    status='PASS_V74_MODEL_CONDITIONAL_PHYSICAL_INVERSE_SHADOW__NOT_CBF';
end
result=struct('status',status,'zipPath',zipPath,'nCases',numel(allSummary), ...
    'nRuntimeErrors',errors,'nFailedCases',errors+ ...
        sum([allSummary.nPhysicalInverseIdentityFailures]), ...
    'nR1FilterStops',sum(startsWith(string({allSummary.stopReason}), ...
        'R1_UNAVAILABLE_')));
end

function [vReal,vFb,vActual,X]=v74RealJet(x,u,s,sc,t,F,XD)
% Taylor of actual same-ZOH R193 plant: 6 derivatives of x,y, yaw order2.
% Requires no future input, no higher commanded-input derivative and NO true mL.
N=7;X=zeros(19,N);X(:,1)=x(:);
U=zeros(4,N);U(:,1)=u(:); % exact ZOH on the OPEN 25ms interval
for k=0:5
    D=v70JetRHS(X,U,s);
    X(:,k+2)=D(:,k+1)/(k+1);
end
vReal=nan(1,6);vFb=zeros(1,6);
for k=0:5
    r0=sc.ref(t,k);r1=sc.ref(t,k+1);
    vFb(k+1)=F(1)*(r0(3)-factorial(k)*X(10,k+1))+ ...
        F(2)*(r1(3)-factorial(k)*X(13,k+1));
end
for k=0:4
    vReal(k+1)=factorial(k+1)*X(13,k+2)-XD(4*(k+2)+3); 
end
% NOTE: XD(4*(k+2)+3) is z_d^(k+2) in 28-component [x,y,z,yaw] ref.
vActual=[factorial(6)*X(8,7)-XD(25); ...
         factorial(6)*X(9,7)-XD(26); ...
         v74YawSecond(X)-XD(12)];
assert(all(isfinite([vReal(1:5),vFb,vActual.'])), ...
    'CBF:V74NonfiniteRealJet');
end

function d2=v74YawSecond(X)
q=X(1:4,1);qp=X(1:4,2);qpp=2*X(1:4,3);
a=1-2*(q(3)^2+q(4)^2);
b=2*(q(1)*q(4)+q(2)*q(3));
ap=-4*(q(3)*qp(3)+q(4)*qp(4));
bp=2*(qp(1)*q(4)+q(1)*qp(4)+qp(2)*q(3)+q(2)*qp(3));
app=-4*(qp(3)^2+q(3)*qpp(3)+qp(4)^2+q(4)*qpp(4));
bpp=2*(qpp(1)*q(4)+2*qp(1)*qp(4)+q(1)*qpp(4)+ ...
        qpp(2)*q(3)+2*qp(2)*qp(3)+q(2)*qpp(3));
den=a*a+b*b;
if den<1e-9,error('CBF:V74YawChartSingular','yaw chart unavailable');end
p=a*bp-b*ap;
d2=(a*bpp-b*app)/den-2*p*(a*ap+b*bp)/(den*den);
end

function map=v74InverseMap(x,a,H,vf)
map=struct('beta',nan(3),'alpha',nan(3,1),'vs',nan(3,1), ...
    'rawTauInf',NaN,'thrust',NaN);
P=a.HLCparam;
map.vs=H.obj.Vs_SuspendedLoadxyDst(x,a.XD,vf,P,H.F2,H.F3,H.F4);
map.vs=map.vs(:);
map.beta=H.obj.Beta2_SuspendedLoadxyDst(x,a.XD,vf,P);
map.alpha=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,map.vs,P);
map.alpha=map.alpha(:);
uf=H.obj.Uf_SuspendedLoadxyDst(x,a.XD,vf,P);
map.thrust=uf(1);
if ~isequal(size(map.beta),[3,3]) || numel(map.alpha)~=3 || ...
        any(~isfinite([map.beta(:);map.alpha(:);map.vs;map.thrust]))
    error('CBF:V74InverseMapNonfinite');
end
if rcond(map.beta)>1e-14
    v=map.beta\map.alpha;
    map.rawTauInf=norm(v,Inf);
end
end

function [delta,residual,M,affineErr]=v74MatchVs(x,a,H,vf,u,map)
% The source inverse has to be affine in Vs, but this is VERIFIED at each x.
M=zeros(3);
for j=1:3
    v=map.vs;v(j)=v(j)+1;
    yy=H.obj.V2_alpha2_SuspendedLoadxyDst(x,a.XD,vf,v,a.HLCparam);
    M(:,j)=yy(:)-map.alpha;
end
probe=[0.173;-0.219;0.087];
check=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
    x,a.XD,vf,map.vs+probe,a.HLCparam);
affineErr=norm(check(:)-map.alpha-M*probe,Inf);
residual=NaN;delta=nan(3,1);
if any(~isfinite(M(:))) || rcond(M)<1e-12 || ...
     affineErr>1e-6*max(1,norm(map.alpha,Inf))
    return;
end
delta=M\(map.beta*u(2:4)-map.alpha);
alphaCorrected=H.obj.V2_alpha2_SuspendedLoadxyDst( ...
    x,a.XD,vf,map.vs+delta,a.HLCparam);
residual=norm(map.beta*u(2:4)-alphaCorrected(:),Inf);
end

function [best,baseCost,minCost]=v74BoundedShadowSearch(x,a,H,sest,sc,t,u,lo,hi)
% This is a finite-budget SHADOW search, not a guaranteed global optimum.
% T is fixed at the original R1 ZOH value; tau is chosen inside its box.
% For each trial tau, recompute exact ZOH physical jets and solve Vs affine
% correction. Cost measures deviation from ORIGINAL source virtual target.
refVs=a.vsRaw(:);baseTau=u(2:4);den=max(1,norm(refVs,2));
[baseCost,base]=v74Candidate(baseTau,x,a,H,sest,sc,t,u(1),refVs,den,baseTau);
best=base;minCost=baseCost;
% Bound-respecting deterministic finite exploration, no Optimization toolbox.
for factor=[0,1]
  for j=1:3
     tryTau=baseTau;tryTau(j)=lo(j+1)+(hi(j+1)-lo(j+1))*factor;
     [val,rr]=v74Candidate(tryTau,x,a,H,sest,sc,t,u(1),refVs,den,baseTau);
     if val<minCost,minCost=val;best=rr;end
  end
end
steps=[.5,.2,.05];
for step=steps
  for pass=1:2
    accepted=false;
    for j=1:3
      for dir=[-1,1]
        tau=best.tau;
        tau(j)=min(hi(j+1),max(lo(j+1),tau(j)+dir*step));
        [val,rr]=v74Candidate(tau,x,a,H,sest,sc,t,u(1),refVs,den,baseTau);
        if val<minCost,minCost=val;best=rr;accepted=true;end
      end
    end
    if ~accepted,break;end
  end
end
end

function [cost,result]=v74Candidate(tau,x,a,H,sest,sc,t,T,refVs,den,baseTau)
% Note: no validity claim is made if only an algebraic, not physical Vs, is used.
result=struct('tau',tau(:),'distanceInf',Inf,'residual',Inf);
cost=Inf;
try
    u=[T;tau(:)];
    [vf,~,~,~]=v74RealJet(x,u,sest,sc,t,H.F1,a.XD);
    mm=v74InverseMap(x,a,H,vf);
    [dv,res,~,~]=v74MatchVs(x,a,H,vf,u,mm);
    if ~isfinite(res) || res>1e-5*max(1,norm(mm.beta*tau(:),Inf))
        return;
    end
    corrected=mm.vs+dv;
    result.distanceInf=norm(corrected-refVs,Inf);
    result.residual=res;
    cost=(norm((corrected-refVs)/den,2))^2 + ...
        1e-4*norm(tau(:)-baseTau(:),2)^2;
catch
end
end

function theory=v74TheoryChapter()
theory=sprintf([ ...
'V74 R193 SOURCE-HLC INVERSE / PHYSICAL ZOH JET SHADOW. 2026-11-18.\n' ...
'R193 x19 and 25ms ZOH unchanged, no feedback controller modification.\n' ...
'HLC estimated mass is used in model-based jets; true simulator mass\n' ...
'is recorded separately and NEVER fed to online HLC mapping.\n' ...
'Source Vfd is an Ad^k sample value sequence, not a derivative jet.\n' ...
'REMAP0 is a partial algebraic mapping, NOT higher-order consistent.\n' ...
'J_FB is genuine derivative of ORIGINAL feedback function under held u;\n' ...
'it must not be called a realized vertical virtual input.\n' ...
'J_REAL[k]=d^k/dt^k (zLoad_ddot-zRef_ddot) under same ZOH u; k=0..4.\n' ...
'J_REAL[5] is deliberately NaN because source inverse does not use it\n' ...
'and derivative requires unavailable reference degree seven.\n' ...
'Independent Vs witness: load x6-xref6, load y6-yref6, yaw2-yawref2\n' ...
'from physical state Taylor order6, NOT chosen to enforce inverse map.\n' ...
'Compare source βτ-α(J_REAL,Vs_actual), not just virtual correction.\n' ...
'βτ=α(J_REAL,Vs_nom+deltaVs), when solvable, is an algebraic\n' ...
'identity; alone it does not prove input-output differential validity.\n' ...
'Physical input bounds are respected in a limited SEARCH, not post hoc\n' ...
'asserted as a CBF certificate. Shadow candidate is NOT applied.\n' ...
'No CBF safety modification, no ZOH intersample safety certification,\n' ...
'no proof of nominal raw-thrust recovery or safe obstacle hovering.\n' ...
'The original R1 flight may end before 2.35s by infeasible thrust.\n']);
end

